/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20251003-4","meetingId":"r07-c-settlement","date":"2025年10月3日","dateIso":"2025-10-03","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を138件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"私からは、２４３ページの高齢者安否確認事業の熱中症等予防対策についてお伺いします。そこでお伺いします。","respondent":"菅野高齢者福祉課長","answer":"高齢者見守り宅配事業の目的に関するご質問にお答えします。今年も猛暑が見込まれるということ、汗をあまりかかないといった理由から、区として飲料配付による高齢者の見守り支援を実施することといたしました。","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"熱中症で救急搬送される高齢者の方の約８割、これが７５歳以上の方で、最多の発生場所は住居となるということを確認いたしております。無料飲料水等お届けサービスについて、配達内容、配達期間、対象世帯、配達の件数、配達事業者等説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"そのアンケート結果により、継続的な支援が必要と判断された方には、関係機関と連携してサポートする予定としております。そのうちアンケート回答数が２万２,１９７ということで、配達した方の３分の２の方がアンケートに答えていただけているという形になっております。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"こちら本数は分かったのですけれども、１本あたり何ミリリットルだったのでしょうか。苦情などなかったのか、また、どのように対策をされていたのかも説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"実態としては、水が５００ｍｌ、あとはスポーツ飲料６８０ｍｌなどという形でお配りさせていただいているというように認識しております。","id":"exchange-003"},{"speaker":"えのした委員","kind":"確認","question":"配達事業者が、これ玄関先でアンケートを取られているのでしょうか。今課長おっしゃっていただいた内容以外にも、今回のこの支援に対してのご意見等がありましたか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"あるお手紙によりますと、自分はなかなか高齢で、買物に行くときにやはり飲物を持つことが重いから難しいと。アンケートを実施する際には、例えばインターホン越しのアンケートの回答など、そのような形の対応も取らせていただきました。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問・要望","question":"多くの反響があり、本当に高齢者の方から喜ばれているのだと実感をしております。これ１世帯だけだからと思うのですけれども、しっかり効果検証を図ってほしいと求めましたが、区のご見解を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"アンケートの結果に関しましては、１回目のアンケート結果を、事業を検証してまいります。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"本日は２７７ページ、保育園運営費、４２０ページ、国民健康保険料についてお伺いいたします。保育園運営費より、一日保育士体験事業についてお伺いいたします。","respondent":"染谷保育施設運営課長","answer":"親育ちを支援していくという観点から、平成２１年度に試行実施、全ての保育園でこちらのほう事業を実施しているというものになります。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"この制度を松居さんが１０年以上前、品川区の保育園の園長を集めて「どうですか」と言ったときに、とても喜んで賛同されたそうです。長年続いてきたこの一日保育士体験の制度、近年参加されたパパ、ママからの感想や反響などはいかがか尋ねました。","respondent":"染谷保育施設運営課長","answer":"有意義だったというお答えをいただいておりますし、安心してお預けできるというありがたいお言葉、そういったものをいただいているところです。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区、とてもいいことを長年続けてきたのだなと思うと同時に、この取組にもっと注目して品川区から発信していっていただきたいなと思います。一言で意気込み等をお聞かせいただけたらと思います。","respondent":"染谷保育施設運営課長","answer":"事業開始した平成２１年当時の実績から見ましても、現時点の昨年度の実績、アンケートにも非常に温かいお言葉いただいております。非常に、保護者の方との信頼関係を築くという意味でも意義のある事業だと感じておりますので、今後もしっかりと進めてまいりたいと感じております。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"質問","question":"続きまして、国民健康保険についてお伺いします。令和６年度の品川区国民健康保険の外国人の滞納額はお幾らか尋ねました。","respondent":"山下国保医療年金課長","answer":"国民健康保険制度における国民健康保険料の外国人の方の滞納といいますか、未納の額です。現年度分８億８,０００万円程度あるのですけれども、全体の８分の１、約１２％ほどと捉えているところです。","id":"exchange-009"},{"speaker":"おぎの委員","kind":"質問","question":"外国人の方の滞納が１億１,０００万円ということで、これだけの数字があれば、ほかにどういった事業ができるかということを考えてしまいます。今板橋区など３０以上の自治体で行われておりますが、こちらのほう、品川区ではどうか尋ねました。","respondent":"山下国保医療年金課長","answer":"ただいま委員よりご紹介ございました新たな仕組みにつきましては、東京出入国在留管理局とも、当区としましてもいろいろ事前に照会等していますので、引き続きそちらのほうの調整等進めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"２３５ページの日常生活用具給付事業について、２３３ページの障害者理解・普及啓発事業に関連して、耳マークについてお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"眼鏡のつるに１００円ライターほどの装置を装着しまして、タッチすると目の前の文章を撮影し、音声で読み上げるという機能がついたものです。当事者の方からご要望があり、時代に即したものとして取り入れました。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ｉＰｈｏｎｅやｉＰａｄ等の端末を視覚障害者支援用具として追加することについて、一昨年の決算特別委員会においても要望させていただきました。このような利便性の高い日常生活用具についてどのように検討が進められているのか、改めて要望も含めてお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"検討会でもそのような要望をいただきました。今後導入自治体の事例を参考にいたしまして、また日常生活用具給付等検討会でご意見を聞きながら、検討していきたいと考えています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"このアイコサポートの個人契約では月額５,５００円と割高のため、地域の視覚障害者の方々からは行政からの補助を求める声があります。ぜひ前向きに進めてほしいと求めましたが、区の見解をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"アイコサポートについては、使用範囲がこれまで、いわゆる品川区であれば品川区内に限られており、区外では使用できないといった課題がございました。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"身体障害者マーク７３.４％、ヘルプマークが５２.３％に比べて、まだまだ認知されていないことが現状です。自治体、病院、この耳マークの品川区での普及啓発の現状についてお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"耳マークの普及の現状についてです。案内表示がありますけれども、聞こえをサポートするメッセージを添えまして、耳マークもそこに併せて掲示をしています。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"我が会派でも、ヘルプカードの裏面に耳マークを掲示したカードを入れることや、シールを張ることで周知していくことを求めさせていただきました。","respondent":"松山障害者支援課長","answer":"耳マークシール等のご提案についてです。どういったような方法、どういったようなツールが効果的なのか、今後も当事者や団体等の意見をお伺いしながら、検討を図っていきたいと考えています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党は、子どもの権利条約に照らして教育施策の見直しをと繰り返し求めてまいりましたし、区としての条例制定も求めてきただけに大歓迎です。区の認識はいかがか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"それから団体、今年度から実施しております品川区こども会議など、そうした直接的に意見を聞く場というものを今後も継続していきたいと考えています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"同時に、子どもに関わる大人こそが子どもの権利を理解しなければいけないというようなお話も伺いました。質問しますけれども、大人全体でそういった共通理解ができるような状況につなげるようなものにしていただきたい、いかがか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"そちらとても大切な要素だと考えています。広く品川区が条例を制定することを認識していただくような取組をし、大人は子どもの声を聴くことの大切さについても触れていきたいと考えています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"伺いたいのですが、品川区でも通学定期への補助制度をつくることを求めますけれども、いかがでしょうか。拡充するよう求めるとともに、子ども料金を１８歳まで引き上げる改正を行うよう求めていただきたいのですけれども、いかがか尋ねました。","respondent":"柏木子育て応援課長","answer":"ただ、小学生から高校生までを対象とした夏休み中のお米支援プロジェクトや、すまいるスクールの午後５時までの利用料無料化などを実施しています。それで、鉄道料金等の子ども料金の年齢引上げですが、それにつきましては、各鉄道会社等が検討すべき事項だと考えています。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもというものは１８歳までが子どもということなので、かなりこの子ども料金というものを１８歳まで引き上げているところもありますので、この通学交通費について支援を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問・要望","question":"６５歳以上は無料で利用でき、実際に８,６００人以上の参加があったと、事務事業評価シートで確認しました。こうした制度がある中で、さらに入浴券を配付することの意義や、２つの入浴支援の事業の兼ね合いについて、福祉部としてどのようにお考えか伺います。","respondent":"豊嶋生活福祉課長","answer":"上期は２０件、下期は１４件程度、お戻しの件数があったというように聞いてあります。６５歳以上の割合ですが、５４５世帯のうち４３３世帯という数字が上がっております。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問・要望","question":"６５歳以上の割合がほとんどということで、戻しが２０件と１４件の計３４件ということで、戻されてはいないというところだと思います。何％が利用したかというところもしっかり評価をして、届く支援にしていただきたいと考えますが、こちらについて区の見解を伺います。","respondent":"豊嶋生活福祉課長","answer":"上期と下期で対象世帯が変わっていることもありますので、延べという表記をさせていただいているです。引き続きケースワーカーを通しまして、適切な使用になるように今後もお話を進めてまいりたいと考えています。","id":"exchange-021"},{"speaker":"せらく委員","kind":"質問","question":"ご本人からは喜ばれると感謝もあったりする中で、少子高齢化が進む中では、この制度が持続可能なのかという点も課題だと考えています。お祝いの気持ちの部分にプラスして、効果や有効性についても検証をしていただくことが大切だと考えますが、区として方向性を伺います。","respondent":"東野福祉計画課長","answer":"区としては、このお祝い事業、とてもご高齢の方に喜ばれている事業ということで、今後も続けていくことで進めていきたいと考えています。効果の測定の在り方につきましては、委員のご提案も含めまして、どういったものができるか研究してまいります。","id":"exchange-022"},{"speaker":"せらく委員","kind":"確認","question":"最後に、住民税非課税世帯等物価高騰対策支援給付金について少し伺っていきます。３回の給付を行ったと決算書を見て確認したのですけれども、総額２３億８,０００万円の事業なのですが、その認識を確認したいと思います。","respondent":"豊嶋生活福祉課長","answer":"今すぐパッと数字が出ないもので大変申し訳ございませんが、大体１割から２割程度というものだったというように記憶はしています。","id":"exchange-023"},{"speaker":"せらく委員","kind":"質問・要望","question":"様々なケースがあって、そういった膨れてしまうこともあるかと思いますが、こちら給付をメインでしっかりしてほしいと求めました。今後も考えてまいります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問","question":"２５１ページ、２６３ページ、一時保護所運営費についてお伺いいたします。１点目に高齢者福祉施設運営費、高齢者多世代交流支援施設運営費についてお伺いいたします。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長","answer":"私からは、多世代交流支援施設ゆうゆうプラザの現状について、お答えをします。今申し上げたような形で、ゆうゆうプラザは多世代交流の促進および高齢者のさらなる健康福祉の増進を日々図っているところです。区内には特別養護老人ホームが１２施設あります。地域とのイベントに高齢者の方に参加してもらったり、夏休みに中学生がボランティアで来たりなど、そういった形で交流等が行われると伺っております。","id":"exchange-025"},{"speaker":"横山委員","kind":"質問","question":"私は今年６月、東京都から委託された民間一時保護所であるさつき一時保護所を視察し、職員の方々からお話を伺いました。位置情報が分かればリスクを軽減することが可能ではないかというお話を伺いましたが、現在の区のお考えを説明するよう求めました。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長、長谷川児童相談課長","answer":"大型商業施設との連携事例についてはこれまでに実績がないのですけれども、食事や健康についてのイベントを実施したところです。私からは、介護職員のインセンティブ等についてお答えします。そういったことの取組を通して、介護人材の確保定着にもつながっていると考えております。私立の中学校や高校の場合には、食事代として１,０００円を渡しており、不測の事態が起こった際にはその中から支出してもらう運用としております。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がありませんので要望だけ、一時保護所の拡充をお願いしたいと考えています。委託や、児童養護施設の一時保護委託というような手法もあるかと思いますので、ぜひ保護先の拡充をお願いしたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"私からは、２３７ページの福祉タクシー・自動車燃料費助成、それから２６１ページのヤングケアラー支援事業について伺います。福祉タクシー・自動車燃料費助成について伺います。","respondent":"松山障害者支援課長","answer":"令和６年度から、自動車燃料費助成について月５００円増額するとともに、福祉タクシー券と共通の券といたしました。利用者数については、令和６年度で４,０６７人です。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"会派から支援額の増額、それから効率的な支給と利便性向上のためのキャッシュレス決済の支給の検討を要望させていただいておりました。券種を細かく１００円単位にしていただきたいという要望に応えて、紙の枚数が増えて、これは非常に悩ましいところだなという理解です。","respondent":"松山障害者支援課長","answer":"福祉タクシーのデジタル活用についての検討状況と課題です。検討状況についてですが、マイナンバーを活用した実証実験を行っている自治体もございまして、動向を注視しています。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問","question":"区では初めての取組であると考えておりまして、新しい取組を１つ前に進めていただいたのだと考えておりますので、大きな一歩と評価しております。","respondent":"松山障害者支援課長","answer":"事務委託先が品川区社会福祉協議会でございまして、事務委託費用は１,４８５万５,０００円です。区内外で約１６０事業所です。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"４,０００人の利用者の方々のものを毎月確認して、こういった確認の手間などもかなり負担としてかかっているのかなというところで思っております。この支援策をさらによくするために、選択肢として検討や研究を進めていただきたいと考えますが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"今後についてのお尋ねです。教育委員会のほうで実例があるということですので、話を聞きながら研究してまいりたいと考えております。","id":"exchange-031"},{"speaker":"山本委員","kind":"提案","question":"次に、ヤングケアラー支援事業について伺います。昨年の決算特別委員会で、やはり区としての課題は、そういった方々を見つけていくということの手法をご提案させていただきましたとの意見を述べました。","respondent":"吉野子ども家庭支援センター長","answer":"それから、現在なのですけれども、ＬＩＮＥ相談という形でやっておりまして、約１４０人の方と相談業務をしています。こういった仕組みはとても大切であると感じております。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"さらに前に進めて、プラットフォーム構築等、引き続きご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"２７７ページ、区立保育園費から若手保育士の育成について、そして保育の質の向上について、質問をさせてほしいと求めました。初めに、入区１年から２年の若手保育士が、ここ数年間で退職した人数を年度ごとにお伺いいたします。","respondent":"染谷保育施設運営課長","answer":"入区１年目、２年目の若手保育士の退職の状況です。ここ３年の状況でお伝えいたしますと、令和４年度が３人、令和５年度が４人、令和６年度が３人の退職となっております。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"令和５年度４人、令和６年度３人という、実際にこのような若手の方に辞められている人がいるという実態が分かりました。退職理由につきまして、差し支えない範囲で教えてほしいと求めました。","respondent":"染谷保育施設運営課長","answer":"退職の理由につきましては、多岐にわたるところはありますけれども、中には残念ながら職場への適応が難しく、退職を選択したケースなどもありますが、その他、別業種への転職、進学、夫の転勤の関係など、様々な理由によりまして退職という形となっております。","id":"exchange-035"},{"speaker":"新妻委員","kind":"提案","question":"このヒアリングの中で、何か具体的な改善案が提案された際、また、年度途中で他の園への異動を希望した保育士がいた場合の対応をお伺いいたしますとの意見を述べました。","respondent":"染谷保育施設運営課長","answer":"組織改正などを含めて検討を進める中で、それから相談者の立場が守られるように、窓口で知り得た事実等に関しては秘密は守られると。年度途中に新規採用職員を対象としたヒアリングを実施するなど、そういったところの対応を実施してまいりたいと考えております。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区に来てくださった方がしっかり希望を持ちながら、またその夢をかなえていける、そのような職場であってほしいと思っています。次に、区立保育園におけるパワーハラスメントの現状、また状況をお伺いいたします。","respondent":"染谷保育施設運営課長","answer":"現場の監督者として指導助言を行うなど、適切な対応を行っているところであります。人事課や人権・ジェンダー平等推進課のほうにハラスメントの相談窓口が設置されておりますので。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問・要望","question":"ヒアリングをする中で課長もつかんでいらっしゃることもあるかと思いますので、改善がしていかれますように取組を進めてほしいと求めました。これは経験の違いや年齢のギャップも多分に考えられますが、区の人材育成の取組は機能しているのか、お伺いをいたします。","respondent":"染谷保育施設運営課長","answer":"力を発揮できる職場をつくっていくということは非常に重要であると考えておりまして、人事課で実施する研修のほかに、こちら用意しております。園長、若手の人材育成と働きやすい職場環境づくりの両面におきまして、しっかりと推進していくという体制を取っているところです。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"１つまたお願いをさせていただきたいことは、研修制度の充実をしっかりと進めてほしいと求めました。そのような忙しい園の業務もやりながらも、しっかりと研修が受けられる体制を区のほうで後押ししてほしいと求めましたが、再度見解を伺います。","respondent":"染谷保育施設運営課長","answer":"なかなか保育士の方、研修のメニューがある中でも、時間的な余裕がなくて研修を受けられないというような話を聞くこともあります。現在、研修に行きやすい状況というものも各園で取れるようにということは、きちんとこちらのほうで整えていきたいと考えております。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"しかし、その一方、なぜ病児保育を行う施設はなかなか増えないのでしょうか。病児保育を行う上での困難さについて、この間の増設の取組を行ってきた区としては、どのように把握をされ、対応を行ってきたのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"病児保育につきましては、以前からその供給量が不足している部分と、それからあと地域偏在に係る部分についてが課題となっておりました。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問","question":"核家族は８５％に及んで、共働き家庭は全体の３分の２となっております。品川区は、病児保育における、この側面をどのように評価をされているのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"病児保育におきましては、やはり様々、ご家庭によりまして、就労の仕方など、そういったところ異なる部分あるかと思います。やはり就労支援と、病児保育の事業については非常に重要な施策であるというように現状認識しています。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今回品川区では、あずかるこちゃん病児保育という予約システムが導入され、９月２６日から運用が始まったと私は認識をしております。それと、あと今回参加を見送った施設があるとお聞きをしましたけれども、その理由について示すよう求めました。","respondent":"染谷保育施設運営課長","answer":"施設数が増えていく中で、各事業者、病児保育を受託していただいている事業者の方たちのご判断の中で実施をしていくと。より利便性の向上と、そういったところをきちんと整えながら、順次導入のほう進めさせていただければと考えているところです。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"独自に今まで利用者と信頼関係を築いてきた施設というものは、何というのですか、選択肢もあってよいかと思います。その辺について、区のお考えをお聞かせ願います。","respondent":"染谷保育施設運営課長","answer":"全てシステムのほうに切替えをしていくということではなくて、それぞれの状況に応じて、予約の方法については検討していければと考えております。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２３３ページ、障害者理解・普及啓発事業に関連をして、９月２５日から旧リボンの跡地で障害者就労体験事業が実施をされておるかと思います。","respondent":"松山障害者支援課長","answer":"既に２５日オープン以降、非常に多くの方にご利用いただいて、大変にぎわっております。会館の地域活動支援センターも含めまして、ご利用者の方と近隣の町会等とも、関わりを持っていきたいと考えています。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ地域に根づいて、これから継続してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"２８３ページ、２８７ページ、あと宿舎借り上げ支援事業について伺います。こうした保育園の運営支援のため、定員割れ補助、ぜひ区で実施をすべきだと思いますが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"経営支援につきましても、今年でいきますと、空き定員を活用しました未就園児の定期預かり事業などを実施しております。新たに発生する保育ニーズに対応した事業実施を通じまして、経営支援をしていきたいと考えているところです。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"民間保育市場に与える影響が大きいということはどのようなことなのか、また、認可外施設の不公平感ということもおっしゃられました。これがどのようなことなのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"民間市場に与える影響ですが、認可外保育施設、民間事業者でそれぞれ努力をされて、入園者を獲得しているというような状況がありますので、そうしたところに与える影響というものが多いと考えているところです。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体の約２０％というところでやっているという状況ですので、改めてこれを実施すべきだというように求めたいと思います。私立保育園の運営安定化のため、やはりこうした支援をしていくということが私は必要だと思いますけれども、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"今令和５年から実施していまして、その中で、今年度に関してはそうした状況に対応できるようになってきているというようなお話も聞いてあります。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で、助成金の支払いが３月下旬頃になっているということで、月々出してもらったら助かるという声も伺いました。こうした園の負担もさらに軽減をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"区としては、数年前から継続的に宿舎借り上げ支援事業補助金実施してございまして、この事業、国や東京都の制度を活用した事業です。事務的な問題から非常に難しいところがあるのですけれども、現場の声を聴きながら、改善できるところを対応していきたいと考えております。","id":"exchange-049"},{"speaker":"澤田委員","kind":"質問","question":"本日は、２３５ページ、移動支援事業、２８９ページ、私立幼稚園経費についてお伺いします。通学支援の加算や支援員の報酬を加算するなどして、移動支援を応援してほしいと求めましたが、お考えを説明するよう求めました。","respondent":"松山障害者支援課長","answer":"区としても、委員ご指摘の移動支援の通学支援については、特に課題だと認識しております。７月末に移動支援事業所連絡会を実施し、そして車に対する支援というものは事業者からも求められており、アイデアや改善策を今検討しています。","id":"exchange-050"},{"speaker":"澤田委員","kind":"質問・要望","question":"区としても、知的障害者（児）移動支援従事者養成講座が現在行われていると思いますが、年１回だったものが２回に増えたのかなと記憶しております。どのように感じていらっしゃるかということも教えていただきたいということと。","respondent":"松山障害者支援課長","answer":"ただこの、例えば令和２年度から令和６年度まで研修受講者数が７１人おりまして、そのうち事業者に登録した人数が１５人ということでございました。今のところ研修に受講されても、なかなか登録数としては増えないということも課題だと認識しております。","id":"exchange-051"},{"speaker":"澤田委員","kind":"意見","question":"戦略広報課ともしっかりと手を組みながら、いろいろな方向から進めていくことも今後の人材確保の後押しになるのではないかと考えます。ご見解を説明するよう求めました。","respondent":"松山障害者支援課長","answer":"現在、地域自立支援協議会の子ども支援部会の中でも、移動支援の仕事についてＰＲするための動画をつくろうというようなお声も上がってきております。委員ご提案の区報も含めてですけれども、様々な機会やツールを使いまして、積極的に今後も発信してまいります。","id":"exchange-052"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、幼稚園経費についてお伺いいたします。特別な支援を必要な児童が、私立幼稚園における障害児の支援の方法について検討してほしいと求めましたが、区のお考えを説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"障害のあるお子様をお預かりいただいている幼稚園に対しまして、先ほどお話しいただきましたような運営を補助する観点から、補助実施をしております。今後につきましても、こうした社会情勢の変化等々勘案しながら、適切な補助額、対象などを検討してまいりたいと考えております。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"２８８ページの生活保護費より排外主義やデマについて、２４５ページ、特別養護老人ホーム運営費より停電時の対応について、それぞれ伺います。","respondent":"豊嶋生活福祉課長","answer":"これは多分恐らく生活保護に限らず、全てのものについて同じではないかと考えています。こちらのほうは保護の申請、それから審査を行っておりますので、特段優遇されているといったことは一切ございません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"確認しますが、外国籍の受給者について近年の傾向はどうなのか、そのような事実はあるのか伺います。例えば広報しながわなども活用する、こうした積極的な対応を求めますが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"令和６年度１１３人、令和７年度１１５人ということで、特段増えているといった事実はないというようにこちらは認識しています。引き続きそのような形で、お困りの方がお気軽にというか、誰でも相談しやすいような広報に努めてまいりたいと考えています。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした停電になったときにクーラーが動くのか、利用されている方はご高齢者の方でありますので、そこを確認させてほしいと求めました。いずれにしても高齢者の命を守る停電対策、新たに必要ではないかと思いますが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"どの用途を優先して活用するか、施設ごと、あとは季節などに応じて、その判断が必要となるのではないかというように認識しております。近年の異常気象からより重要になっていると認識をしておりますが、例えば東京都では、活用して新たに整備している施設もあります。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"電気のクーラーの場合は、非常用電源が途切れてしまったり、そもそもないと止まってしまうということが実態だと伺っております。ガスタンクもつけることで、ガスの供給が止まっても引き続きクーラーが使えるということの話も伺いますので、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"今後建設予定の、例えば小山台住宅跡地の高齢者施設等におきましては、７２時間クーラーを稼働する非常用電源を整備する予定というようにしています。","id":"exchange-057"},{"speaker":"松永委員","kind":"確認","question":"２４３ページの高齢者安否確認事業について、時間がありましたら２５１ページの高齢者住宅対策事業の身寄りのない高齢者について伺いたいと思います。","respondent":"松山障害者支援課長","answer":"東京２０２５デフリンピックの競技として、この東京２０２５デフリンピック周知啓発についてはスポーツ推進課と一緒に、「あつまれ！あるいは区民となる金子選手に向けての応援ですとか、そういったところはスポーツ推進課と一緒に今後も大会に向けて盛り上げていく予定です。","id":"exchange-058"},{"speaker":"松永委員","kind":"質問","question":"区立学校における聴覚障害や手話への理解を深める教育は、具体的にどのように展開されているのでしょうか。この結果、児童・生徒の意識にどのような変化が見られているのか、認識について伺います。","respondent":"藤村総務課長","answer":"今、「あつまれ！東京２０２５デフリンピック関係についてお話しいただいているところですけれども、本日民生費という観点ですので、お答え可能かと思います。","id":"exchange-059"},{"speaker":"松永委員","kind":"質問・要望","question":"次は２４３ページの高齢者安否確認事業の高齢者施策の充実と見守り、いわゆる安全性の確保体制について伺いたいと思います。高齢者の安否確認や安全な生活の確保につなげていくために、対象者への周知や利用促進の具体的な方策について、本区の見解を伺います。","respondent":"東野福祉計画課長","answer":"令和６年度、個人負担を無償化したというところが大きな要因かと考えています。様々な手段を用いまして、今後も周知に努めてまいります。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問・要望","question":"戸別訪問ができないということを伺っていまして、ぜひ見回りの際には、そこもしっかりとした形で取り組んでほしいと求めました。どういった活動というか、区のお考えをお知らせほしいと求めました。","respondent":"東野福祉計画課長","answer":"民生委員の件、先ほどございました高齢者宅の訪問時になかなかピンポンが押せないというのは、多分戸別訪問が難しいという点であったかと思います。支え愛・ほっとステーションなどと協働した形での見守りを、今後も続けていければと考えています。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問","question":"最後になりますが、高齢者住宅の対策事業について伺います。低所得高齢者や身寄りのない高齢者に対する、今のあっせん状況を伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"高齢者地域支援課のほうで進めておりますあっせん状況ですけれども、昨年度の実績としましては、７４件の方にあっせんをさせていただいて、助成をさせていただいたといったところです。","id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"２３３ページ手話理解促進、２４１ページ障害者就労支援事業、２２６ページ福祉計画費、２９３ページ葬祭扶助費について伺っていきたいと思います。","respondent":"松山障害者支援課長","answer":"令和３年度に品川区手話言語条例を制定いたしましたので、来年度が条例制定５周年となります。イベントなどを企画しまして、引き続き手話言語の機運醸成、それから積極的な周知を図っていきたいと考えております。","id":"exchange-063"},{"speaker":"つる委員","kind":"質問・要望","question":"私はこの間９月に２回お邪魔して、また接客のあり方とかを伺う中で、メニューの下に点字で何か書いてあるのです。そこに設置しろではないのですが、こういった取組を参考に、ぜひ品川区でも展開ほしいと求めましたが、ご見解を説明するよう求めました。","respondent":"松山障害者支援課長","answer":"登録企業が今６１社になりましたので、例えばご提案いただいたカフェの一部をお借りするようなことも交渉の中で伝えていきたいと考えています。今後も就労、働きたい人が働けるように努めてまいります。","id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"そのうちの約３割に当たる４２名の方が単身の身寄りのない高齢者ということも伺っている中で、これからそうした身寄りのない高齢者が増えていく。","respondent":"豊嶋生活福祉課長","answer":"生活保護受給者の方で、身寄りがない方が亡くなった場合ということでお答えします。生前からお話しする話ではないとは思うのですけれども、ケースワーカーのほうとしては、事務作業の一連の流れとして対応をさせていただいているです。","id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"ご答弁の中にあったそれをどうこうということではなくて、別の所管として、例えば終活についての情報提供・支援というのがあるわけであります。","respondent":"東野福祉計画課長","answer":"今年度から終活支援パッケージ「あんしんの３点セット」の無償化というものを始めております。そこをきちんとしたスキームをつくる必要があると考えています。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"たまたま障害者施策推進から質問に入りましたが、実は高齢者施設での虐待事例も伺っております。福祉全体としての第三者的な相談窓口の設置について、ご見解を伺います。","respondent":"東野福祉計画課長","answer":"委員からご質問の、福祉行政に関する第三者機関ということについてお答えしたいと思います。具体的には、第三者の目でその相談に応じるというようなものですので、まず今あるところをご利用いただければと考えております。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、これは高齢者施設のほうでも同じことですので、ぜひ要望とともに見解があったら伺いたいと思います。ちょっとよく分からないので、改めてご説明伺います。","respondent":"東野福祉計画課長","answer":"例えばそういったところでもどうしてもらちが明かないというような場合につきましては、さらなる検討が必要かと考えます。小山台の複合施設の建設にあたりましては、福祉施設の指定管理候補者予定者という形で、補助金の関係もありまして先行して選定をしております。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問","question":"ここで障害者のどういう施設とかその機能ができるのかについては、当事者のご意見を伺いたいというふうに言ったところ、いや。区が前におっしゃっていた事業者のアイデアというのと、この設計が先に進むということの整合性がどのようにつくのか伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"現在児童発達支援センターと、それから就労継続支援Ｂ型事業所を予定してというところで、整備を進めているところになります。今後公募を予定しております指定管理者・運営事業者の意見等も取り入れた設計を行うということも、効果としてはありますけれども、区立施設。","id":"exchange-069"},{"speaker":"吉田委員","kind":"意見","question":"障害者の場合、どういう事業でどういう方たちかによって設計が違いますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"せお委員","kind":"質問","question":"２５９ページすまいるスクール運営費、２７５ページベビーシッター利用支援事業費についてお伺いします。まず、間食を違うものにできないかという保護者の声というのは今まで区のほうにありましたか尋ねました。","respondent":"上野子ども育成課長","answer":"糖分・塩分・油脂は控え目で極力食品添加物が少ないものが望ましいという言葉を入れさせていただいて、対応に努めているところです。２点目、ご質問いただきました間食を変更した場合に、そちらについては予算編成の検討過程で決まるものと考えているところです。","id":"exchange-071"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらは要望いたします。４,０００万円ほどの差というのは単純に利用者の増加を見込んでいるのか、令和６年度の状況も含めて説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"こちらの実績についてご説明申し上げます。当該事業は令和４年にスタートしておりまして、年々利用者が増加している、成長が見込まれている事業です。","id":"exchange-072"},{"speaker":"せお委員","kind":"質問・要望","question":"事業者にもお話をお伺いしましたが、同じ人が来てくれないと子どもが慣れないというお声は多いそうです。マッチングサービスの課題というのをどのように捉えているかを含めて、区の考え方を説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"ベビーシッター支援事業におけるマッチングサービスの考え方について、ご説明します。利用者とベビーシッターの個人間の契約という形になりますので、事故発生時における対応等について課題があるというふうに認識をしております。","id":"exchange-073"},{"speaker":"せお委員","kind":"質問・要望","question":"私は以前から、ただ現在そういう社会ではないので、本当にそういう点でもベビーシッターを活用した病児保育を充実させたいなと思っています。もし分かりましたら、そちらの進捗状況も分かれば併せて説明するよう求めました。","respondent":"芝野保育入園調整課長","answer":"今の事業スキームでは内容までは把握というか、申込み時に把握しておりませんので、件数のほうは把握していないところです。令和７年度中に開始される予定となっておりまして、引き続き東京都と連携を取りながら、病児・病後児保育に係る利用者支援の充実を図ってまいります。","id":"exchange-074"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えば行政から送られてきた書類とかの説明をしてほしいとか、電球が切れてしまって取り替えるとか、原因としても挙げられると思います。","respondent":"菅野高齢者福祉課長","answer":"ケアマネジャーに向けた法定研修の受講料支援事業についてご説明をします。残りの４分の３は、既に都の支援事業も同様のスキームで行っておりますので、結果負担がゼロとなるようなスキームとなっております。","id":"exchange-075"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実質的には自己負担はないということなのですけれども、今、ご回答の中で、所属する事業所ということでお話がありました。では、今休職中であったり、ケアマネジャーの業務を離れている方についてはどうか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"こちら事業所に対する支援ということになっておりますので、あくまでも所属する方が法定研修を受講した場合の受講料負担というようなスキームになっております。","id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問","question":"申し込みして受講して、終わるのが２月の中旬になってしまう。まずは区として受講料２万８,０００円、この金額に対して何か助成をしていただければと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"居宅介護支援事業所が２４か所ということで、約二百二、危機的状況にはなっていないというようなところは認識しているところです。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実際ハートページを見てみたのですけれども、訪問介護事業所５８社掲載されている中で、そのうちの１０社が総合事業の指定を既にもう取っていない。支援の方が２０％、そういったこともぜひ検討してほしいと求めましたが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"今、ご指摘いただきました点を踏まえて、今後検討といいますか研究をしてまいりたいと考えています。","id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"令和７年度デフリンピック認知度１２０％プロジェクトもありますし、これは要望させてほしいと求めました。この夏、命が危険になるような状況になると思うのですが、そうしたときの対応について説明するよう求めました。","respondent":"松山障害者支援課長、佐藤保育事業担当課長、豊嶋生活福祉課長","answer":"東京２０２５デフリンピックにつきましては、スポーツ所管と連携をしまして盛り上げていけるよう努めてまいります。保育所等におけるスポットワーク・隙間バイトについてのご質問にお答えします。その状況をいち早く察知したケースワーカーがその方とお話をして、お金を払って開通していただくお手続を一緒にしているというところが現状です。","id":"exchange-079"},{"speaker":"大倉委員","kind":"質問","question":"いわゆる隙間バイトは、周知も併せて把握はしておいたほうがいいのではないかと思っているのですが、その点について伺いたいと思います。そのしっかりとした周知について、ご答弁ほしいと求めました。","respondent":"佐藤保育事業担当課長、豊嶋生活福祉課長","answer":"こども家庭庁より通知があった際には、毎月行われております保育園長会などでも取り上げて、ご説明をさせていただいているところです。委員ご指摘の内容については、私は承知をしておりませんでした。ケースワーカーのほうには周知をしてまいりたいと考えているとともに、引き続き気を引き締めて運営をしてまいりたいと考えています。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は保健師をぜひとも増員して、地域からの学習会や講座をしてほしいという要求に応えられるように、いかがでしょうか。地域包括支援センターの役割に地域づくりというのもありますので、その意味からもぜひとも実施を求めたいと思いますが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"今年の夏は猛暑ということもありますので、７５歳以上の世帯の方にスポーツ飲料とかをお配りして、そういった形で対応をしています。今後、地域に地域包括支援センターを配置するにあたって、他自治体の事例も参考にさらに検討を進めていきたいと思っているところです。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"このような状況が続けば、関係者の疲弊にもつながりかねないという要望をいただきました。介護認定というのは現在の利用者の実態に合わせた認定になるように、ぜひとも見直してほしいと求めましたが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"公平性の確保に努めておりますが、全国構成比と比較して要支援の割合が現在高くなっておりますので、分析を進めているところです。より良いサービスが受けられるように、そしてそれが自立支援・重度化防止につながるように、保険者として努めてまいりたいと思います。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"私は、２２６ページ社会福祉費についてお聞きします。この辺について、ちょっとご見解だけ説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"こういう仕組みがあるものがあるならば、こういうものもやはり所得に応じて改善すべきではないかと私は思うのですが、教えてください。答えるよう求めました。","respondent":"崎村企画課長","answer":"応能負担が原則であるというのは、委員のおっしゃるとおりかと思います。品川区が今年度も含めて無償化に取り組んでおりますのは、所得制限なく無償化にしているものですので、そちらはご理解いただければと思います。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"その点についてどう思うのでしょうか。支援が行き届かないこの方たちにもっと支援をするべきだ、そういう方向で進むべきだと思うのですが、ご見解を説明するよう求めました。","respondent":"崎村企画課長","answer":"これも施政方針で申し上げましたけれども、やはりもらえる人、所得制限のほうは撤廃をしていくといったところです。そういったところで、こういう社会を目指していくというのが品川区の姿勢であります。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問","question":"国・都・２３区で話し合って、２４時間いつでも家族を預けられる施設を造るべきだと私は思うのですが、どう思いますが。子どもを預けて２人で働いていける、何とかそういう預けられる仕組みを国・都・２３区で考えて、ご見解を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"そういったことが家族の負担になるというところが背景となって、２０００年に介護保険制度が施行されたと認識しております。介護保険制度の中では、少しでも介護離職でご家族の方が困るとか、そういうことがないような形でしっかりとケアプランを作っていきたいと思います。","id":"exchange-086"},{"speaker":"塚本委員","kind":"質問・要望","question":"併せて２５９ページの若者の心と体の健康相談事業、単身現役世代に対する政策的な課題というところについて伺わせてほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"１つ目が、従来の児童センターにおいて実施している乳幼児親子向けの事業、こちらが１点です。それから３つ目が、具体的にはまだ検討中なのですけれども、そういった取組を実施する予定です。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後、政策として打つべき必要性のあることなのではないかというのはいかがかということでお伺いしたい。どなたになるか分かりませんが、ちょっとその課題認識をお知らせほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"お仕事に関することですとか人間関係に関すること、それから住まいに関することなど様々な課題を抱えている方がいらっしゃると認識しております。やはりそういった方々への支援というのも必要と考えていますので、今後、区として実施していけるように検討をしたいと考えています。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"今伺った話は確かにやっていただいていて、これは大事なところだと思うのですけれども、やはりちょっと対象が限定されると思うのです。最後にもう一度、ご答弁ほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"ただいま委員から、そういった幅広く若者に対応できるセクションをというお話いただきました。何かしらの形で、まずはそうした対応を区として始め、いずれはそういったニーズがあればセクションも必要になってくることかなと認識しております。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"ということは、かなり遅くまで民間学童に行っているのではないかと思うのですが、その実態はどのように捉えられていますでしょうか。どういう理由で食べられないのかという品川区の実態をどこまで把握をされて、この朝食支援というのをやっておられるのか説明するよう求めました。","respondent":"上野子ども育成課長","answer":"こちらなのですけれども、利用実績といたしましては、今年度３７校全校で平日２８日間実施をいたしました。食べてこられない方につきましては、現在１％の方が毎日食べていないということでご回答いただいたという状況になっております。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"仕事で早く出ていかなくてはいけないのだったら、早く起きて作ったらいいではないですか。これは何回も私は一般質問でも取り上げていますけれども、いいですか、心身の調和のとれた発達を図るように努めるものとする」と。","respondent":"上野子ども育成課長","answer":"まずは仕出し弁当につきましても朝食支援につきましても、昼食または朝食の選択肢を増やすということを第一に実施しているものです。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、しっかりと状況を確認したのですかというのはそこにあるのです。それをちゃんと知らせてほしいと求めましたが、いかがか尋ねました。","respondent":"上野子ども育成課長","answer":"施策の方向性としまして、政策基盤となる行政サービスは、所得制限なくすべての方に提供するという考えに基づいて実施しているものです。","id":"exchange-092"},{"speaker":"西村委員","kind":"質問","question":"２５５ページ子育て支援事業に関連して、朝の居場所事業を伺いたいと思います。多くの自治体がこの取組を始めている一方で、賛否両論の議論も見られる事業ですので、伺ってまいりたいと思います。","respondent":"上野子ども育成課長","answer":"朝の小１の壁という問題がございまして、社会全体でここは真摯に向き合い、解決に向けて取り組むべき重要な課題と認識しております。区内でも校門の前で学校の開門を待つ児童がいらっしゃいますので、児童の安全・安心の確保を目的に、居場所事業を開始したところです。","id":"exchange-093"},{"speaker":"西村委員","kind":"意見","question":"子どもの健康や親子の貴重な朝の時間に与える影響についても、同時に考えなくてはいけないと考えています。こういった生活リズムへの配慮はどのように事業に取り入れて設計をしておられるのか、説明するよう求めました。","respondent":"上野子ども育成課長","answer":"それから朝食提供につきましては、こちらからサービスをご提供しまして、それぞれのご家庭のご事情に合わせて選択いただくものと考えております。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほどご答弁ありました小１の壁を壊すために、小１を犠牲にするのかという声もあります。子どもを真ん中にした取組になっているのか、もう一度ご答弁をお願いいたします。","respondent":"上野子ども育成課長","answer":"ご質問いただいた件につきまして、長時間お子様が外でお過ごしになるという面も確かにあることは認識しております。その中で、区としてもしっかり見守りをしていって、ご家庭の所にお返ししていくということで対処していきたいと考えております。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"子育て環境の改善に向けてどのような方向性でサービスを提供していかれるのか、しっかりと議論をして進めていただきたいと強く思います。","respondent":"上野子ども育成課長","answer":"朝食支援につきましてですけれども、こちらもいろいろなご事情を抱えたご家庭があると認識している中でどうしても朝食の提供が難しい場合については、朝食提供も一つの選択肢として、行政としてサービスを提供するという考えに基づいて実施するものです。","id":"exchange-096"},{"speaker":"西村委員","kind":"意見","question":"この２割の子どもたちへの支援はもちろん必要なのですけれども、しっかりと分析と検証していただく必要があると考えています。品川区は何を目的としまして、子どもたちのどのような成長を目指すのか、もう一度ご答弁をお願いいたしますとの意見を述べました。","respondent":"上野子ども育成課長","answer":"総務省の調査で、区内の子ども食堂で朝食支援を実施しているという区民の声などをいただいていることから開始したものです。品川区として朝食支援事業といたしましては、ひとつ行政サービスの選択肢として朝の居場所で朝食を提供するということで、実施しているものです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問・要望","question":"そういった子どもの姿、朝食事業を通して、子どもたちの育ちを真剣に考えていただきたいというふうに思っております。食事の楽しさ、朝ご飯の大切さを伝え、おいしいと思える朝食の時間になってほしいと願いますが、ご答弁をお願いいたします。","respondent":"上野子ども育成課長","answer":"お子さんが食事に対してしっかり向き合うというところについては、非常に重要なことだと考えております。私どもの朝食支援事業ですけれども、そこから食育等については、また別の事業のところで考えてまいりたいなと考えております。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に要望になりますが、この高齢者の方々が急に聞いたお話で、開始もすぐで驚いておられたというお声を聞いております。朝の居場所事業が人の手配ができないまま、無理にでもと進めることがないようにお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"田中委員","kind":"質問・要望","question":"２３７ページ、福祉団体に対する助成金および２３９ページ、心身障害者福祉会館運営費に関してお伺いしたいと思います。電気使用量を確認でき、使用料や電気料金を抑えることができた」というのが、なぜか特別養護老人ホームのモニタリング評価の最初に書いてあるのです。","respondent":"菅野高齢者福祉課長","answer":"平塚橋特別養護老人ホームに関するモニタリングの評価の結果等についてのご質問にお答えします。令和６年度につきましては、そういった電気料金の工夫をさせていただいて、よりよい施設管理をしていただいているという観点から評価をしています。","id":"exchange-100"},{"speaker":"田中委員","kind":"確認","question":"私も確認はしておりますけれども、入所調整会議で実態をどう捉えて、会議に望まれているのか。現場との乖離が、入所調整会議との乖離がどうもあるような気がしてならないのですが、現状についての認識をお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"例えば今、どうしても料金が少し高くなるというところで、多床室に比べるとご希望が少なめではあるという認識はあります。そういったところは、今後、いろいろ工夫はしていかなくてはいけないと思っているところです。","id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"どういう労働環境なのかというのは、ほかの施設で普通に公休としてとっていた数字にようやく追いついたというような数字だと私は伺っております。正規職員の方が定着しない背景を、区として認識をし、そこの改善を私は求めていただきたいと考えています。","respondent":"菅野高齢者福祉課長","answer":"順番にお答えします。指定管理者制度においては、社会保険労務士による労務環境チェックを５年に１回していますので、決して悪いものではないと捉えております。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問","question":"こういうモニタリング評価とか、介護専門学校の卒業生の意見をしっかり聞くというのも、私はぜひ取り入れるべきだと思います。","respondent":"菅野高齢者福祉課長","answer":"平塚橋特別養護老人ホームがどうこうというのではなくて、法人にどなたが就職されたかというところで、人数を出しています。令和６年度においては、１人、そちらの法人に就職したいという生徒がいらっしゃったと捉えております。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"確認","question":"これがまずすまいるスクールと同じものかということの確認です。保護者の方から、先ほどの委員と同じような形で、子どもが食べるにはというご意見があったので、そこを確認します。","respondent":"染谷保育施設運営課長","answer":"区立幼稚園における預かり保育で提供しているおやつですけども、すまいるスクールと同一の業者で提供させていただいているものになります。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"確認","question":"でもこれはきっと栄養の側面から考えるといいものだと思うのですけれども、先ほど、子ども育成課長から来年度の改善についてのお話がありました。それがこの区立幼稚園の預かり保育の軽食にも適用されるのか、そこを確認します。","respondent":"染谷保育施設運営課長","answer":"預かり保育のおやつにつきましても、幼稚園からも様々なご要望などを頂いているところもありますので、きちんとそちらのほうについては、価格なんかもきちんと確認した上ですけれども、検討はさせていただきたいと考えております。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、特別支援保育園・幼稚園等のほうをお尋ねします。特に小学校での連携という観点で、意義、成果についてご説明をお願いします。","respondent":"染谷保育施設運営課長","answer":"こちらの事業の目的につきましては、５歳児を対象として、就学に向けてというところで、実施をしているものです。子どもに関して、教育のほうに伝えるというところでは、就学に向けてきちんと教育委員会との連携はとれていると考えております。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この事業は実は要綱が定められていなくて、心理士たちとの契約の形式も報償費ということですから、１件決定で、それで研修の講師という立場なのです。ですから、制度としてきちんと整えてほしいというご要望を出しているのですが、その検討の結果はどうなっていますか。","respondent":"染谷保育施設運営課長","answer":"１件決定で報償費でお支払いをしているという状況ではありますが、特別支援保育等実施要綱ですとか、きちんと規定をしていければと考えております。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問","question":"きちんと規定をしていければということですので、早急にお願いいたします。令和７年度の予算の話になってしまうのですけども、５歳児健康相談事業というところで、簡潔にこれはどのような事業か説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"５歳児健診に関係する相談事業ですけれども、これは今年初めてモデル実施を５歳児健診でしていますので、そうしたご要望に対応するために実施しているものです。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"それは５歳児健診に向けての事業です。今、こちらは今年は保健センターのほうで５歳児健診をモデル実施していると思うのですが、あるいは知識などを活用してはいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"モデル実施で実施しております５歳児健康診査事業におきまして、学校心理士の先生方を活用させていただいている点のご質問にお答えをいたします。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問","question":"品川区が今までやってきたことが５歳児健診で活かされたということで、５歳児健診に向けて、非常に仕組みが構築されてきたのだと思います。","respondent":"石橋品川保健センター所長","answer":"円滑な就学に向けて、この５歳児健診の実施を目的としてやっております。その辺りも含めまして、しっかりと全庁的に円滑な就学に向けてということで、品川区の子どもを支えていければと考えています。","id":"exchange-110"},{"speaker":"松本委員","kind":"質問","question":"私からは２４９ページ、デジタル活用による高齢者社会参加促進事業、２６２ページ、児童相談所費について伺います。申し訳ないのですけれども、これは実績値を目標値そのまま転記してしまったのではないかと思うのですが、この点はいかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"事務事業評価を行うに当たりまして、目標値を人数にしたほうが分かりやすいということで、目標値を途中から少し変更したことによるものです。目標値を全教室の定員人数に設定しまして、実績については、実際に参加された人数を記載していく運用に改めていく予定です。","id":"exchange-111"},{"speaker":"松本委員","kind":"確認","question":"で、令和６年の通信利用動向調査報告書を確認すると、７０歳から７４歳の約９割がスマートフォンを所有している。お伺いしたいのですけれども、これは年代別の参加者の割合は把握されていますか。","respondent":"樫村高齢者地域支援課長","answer":"シニアにやさしいスマホ教室についてのお尋ねです。世代別の参加人数については集計をしておりませんけれども、令和６年度は定員２１６名に対しまして、１２７名の方に参加いただいたところです。","id":"exchange-112"},{"speaker":"松本委員","kind":"質問","question":"そうすると、ある程度、定員に対して半分ぐらいということですか。どこかでやめていくことも考えないといけないのですが、この辺り、区としてはどういうお考えをお持ちなのか伺えればと思います。","respondent":"樫村高齢者地域支援課長","answer":"スマホ教室の転換期についてのお尋ねだと認識をしております。今後も継続していく考えですけれども、社会情勢等を総合的に考慮しながら、事業の転換期を含めて検討していく必要があると考えているところです。","id":"exchange-113"},{"speaker":"松本委員","kind":"質問","question":"教室をやるにしてもどういう教室をやるのかが、そうした、YouTubeやＳＮＳなどの使い方までこのスマホ教室はされているのでしょうか。内容についてもお願いいたします。","respondent":"樫村高齢者地域支援課長","answer":"ただ、その時々の受講者のレベルですとか、進捗状況、ご要望などに応じて、臨機応変にその都度、内容を若干変更したりして、実施しているところです。","id":"exchange-114"},{"speaker":"松本委員","kind":"質問","question":"実は若い人ではなくて、６０代、７０代というようなこともあります。そうすると、このスマホ教室の内容もリスクを意識したものがあってもいいと思うのですが、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"スマートフォンが今、生活に必要不可欠となっている今の社会におきましては、ＩＴリテラシーというのは非常に重要であると認識をしています。逆に委員からご指摘があったように、ＳＮＳで加害者にならないための注意点等を講座の中で丁寧に説明をしまして、注意喚起をしています。","id":"exchange-115"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２３５ページの日中一時支援事業と、２３９ページの心身障害者福祉会館運営費について伺いたいと思います。延べ床面積が増える検討を進めてほしいという声も寄せられておりますけれども、そこら辺もどうなっているのか伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"４８年ほど経過しておりますが、必要な修繕等は行いながら運営している状況で、リニューアルが必要というようなところは認識しています。新たな整備というところで検討を進めておりますので、具体的なところを申し上げられる状況ではございませんが、検討を続けているところです。","id":"exchange-116"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、課題のところも居ながら工事が難しい等々、出されたと思いますが、とはいえ、本格的に建て替えの検討はいつ頃始めるのかも分からないでしょうか。６０年まではあと１２年ということになりますので、そこら辺もまだ見えない状況でしょうか、伺います。","respondent":"佐藤障害者施策推進課長","answer":"現在、ほかにも整備中、整備予定の施設もあります。先ほど、お話もございました、まずは全体の更新、工程をなるべく早くまとめていけるようなところで検討しています。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"新たに建設できる土地がないなど課題の多い都心部ですから、進めるためにも計画等が必要だと思います。いつまでにつくっていくのかという計画が必要だと繰り返し求めてきましたけれども、現在どのように考えられているか説明するよう求めました。","respondent":"佐藤障害者施策推進課長","answer":"心身障害者福祉会館のお話でも申し上げましたが、現在も整備中、また整備予定の施設もある状況ではあります。様々な必要量等を分析しまして、今後の整備予定を出していくところで現在、考えてあります。","id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"確認","question":"ではそういった世田谷区のものと同等とは言わずとも、建てていくための計画がつくられていくということでよろしいかという少し確認をさせてください。なぜ自宅送迎できないかを伺いたいと思います。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"施設の計画、予定の示し方につきましては、どんな形でできるかというのは検討してまいりますが、必要量等を踏まえてお示しできるように考えているところです。私からはぐるっぽの児童学園の送迎バスの件についてお答え申し上げます。","id":"exchange-119"},{"speaker":"こんの委員","kind":"確認","question":"２４７ページ、２５９ページ、すまいるスクール運営費の３点をお伺いしたいと思います。そこでまず確認ですが、品川区の取組現状と今後の方針について説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"従来２５年以上、居住支援手当の支給や、家賃の補助をするという住まいの支援等を幅広く支援しています。基本報酬が下がったということにつきまして、その分の事業者への支援金というところも１０月から始めさせていただいたところです。","id":"exchange-120"},{"speaker":"こんの委員","kind":"質問","question":"１事業所に１５万円ですからなかなかこれは何台も買えないというようなところだけれども、事業所はこの介護の従事者の確保に苦慮していると。移動の負担の軽減を図る観点から、介護人材の確保促進につながるといったことを考えるわけですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区内で訪問介護事業所が約６０事業所ありますが、そのうちの今、１２事業所が申請をしているとは伺っております。約２割の事業所ということで、自転車の利用がどの程度あるのかというところの部分について、しっかりと現状把握していきたいと考えています。","id":"exchange-121"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺をどうか現状をまずは把握していただきながら、考えてほしいと求めましたので、後でお願いいたします。こちらは社会福祉協議会がしてくださっている事業でありますが、支援員の確保について、現状の取組を示すよう求めました。","respondent":"菅野高齢者福祉課長","answer":"２点目の社会福祉協議会で実施しておりますさわやかサービスについて、お答えします。反対にこの有償ボランティアの利用人数につきましては、同じく１０月３日現在で、利用会員は３９４世帯となっております。","id":"exchange-122"},{"speaker":"こんの委員","kind":"質問","question":"現状を伺いました。お願いします。","respondent":"菅野高齢者福祉課長","answer":"社会福祉協議会では、やはり提供会員の募集は常に行っているとは伺っております。２９９人という協力会員が多いのか少ないのか、より多くの方がサービスを提供されるように努めていきたいと考えています。","id":"exchange-123"},{"speaker":"こんの委員","kind":"質問","question":"課長のご答弁をお聞きしていますと、マッチングしているかどうか、品川区としても一緒に考えていくべきではないかと感じたところです。その報酬額については、ご時勢に合った金額の見直しも今後は必要ではないかと考えるわけですけれども、ご見解を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"東京都の最低賃金が１,２２６円に改められたとも認識しておる中、有償ではあれ、ボランティアというところが事業の肝となっております。で、そこを高くしてしまうと、双方が納得のいくような金額の部分については探っていかなくてはいけないのかと考えています。","id":"exchange-124"},{"speaker":"こんの委員","kind":"質問","question":"先日、私は一般質問で、ファミリーサポート事業のほうでもこうした提供会員の確保を取り上げさせていただきました。補助金の使い方、こうしたことが必要ではないかと私は考えるわけですが、いま一度ご答弁いただけますか。","respondent":"菅野高齢者福祉課長","answer":"令和６年度決算で、事業主体の社会福祉協議会に対して、区としては人件費等の約４,１００万円を補助金として交付しています。そこに補助金を投入することがいいことかどうかも含めまして、今後、研究していきたいと思います。","id":"exchange-125"},{"speaker":"こんの委員","kind":"質問・要望","question":"状況をよく見ていただきながら、いずれにしても確保していかなければいけない大事な人材だと思いますので、どうか研究しながら、その点を今後、検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"藤原委員","kind":"質問・要望","question":"２８９ページ、生活保護費の生活福祉課職員について、まず伺います。職員のメンタルをどう確保していくか、メンタル面で支えていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"３人で初めは行って、足らなかったので、後から３人の応援を呼んで、そこまでの対応をさせていただいたというところを多分ご覧いただいたと思います。","id":"exchange-127"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、私はここは続けていただきたい。いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"ただ、そのたびに私のほうはこの敬老事業、お祝い事業ということで、続けていきたいということで表明をしております。これからもお祝いという形で、敬老の感謝の意を示していきたいと思います。","id":"exchange-128"},{"speaker":"藤原委員","kind":"質問","question":"でも、私個人の思いは、なぜ要介護よりも要支援のほうが多いのですかと。いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"品川区は要支援１、２が多いですが、こちらは予防の効果ができているものと信じているところです。引き続き、こういった予防活動ですとか、高齢者クラブの活動も積極的に区として支援してまいりたいと考えています。","id":"exchange-129"},{"speaker":"藤原委員","kind":"質問","question":"要介護３とか４とか５とかどんどん減っていけば、今までずっと質問していた介護士の方々たちの処遇改善とかを言わないで済む日が来るかもしれません。ぜひ、ここをもう１回、どうやっていくのだと。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長","answer":"介護予防に力を入れて、これからも展開してまいりたいと考えています。それが、やはりご本人にとっても、ご家族にとっても、そして区にとっても、大変よいことだと考えています。私のほうも、品川区の介護保険事業計画の中でも、やはり８つのプロジェクトの中の一つが健康づくりと介護予防の推進を打ち立てております。","id":"exchange-130"},{"speaker":"まつざわ委員","kind":"質問","question":"児童センターについて伺います。その結果、どの世代にも中途半端な場所という状況は生じていないか尋ねました。","respondent":"上野子ども育成課長","answer":"近年、子ども、若者を取り巻く環境は急速に変化しておりまして、児童センターにもその変化に即した対応が求められております。サードプレイス、すなわち家庭や学校以外の居場所としての機能強化を求める声を頂いておりまして、そちらが課題であると認識しております。","id":"exchange-131"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"やはりせっかくですから子どもたちで企画そして運営ができるといった子どもたち主体の新しい児童センターにしていただきたいと考えています。それとは別に、令和６年度における児童センターの中高生の利用実数、人数であったり割合はどのようになっているのか尋ねました。","respondent":"上野子ども育成課長","answer":"そのうち保護者を除いた数、６０万７,９０３人のうち、中高生は６万９,０１２人の１１％となります。この１１％はティーンズ館での利用が主となっておりまして、それから部活、このような数字になっていると認識をしております。","id":"exchange-132"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そういった子どもたちが安心して利用できる第３の居場所という形で、しっかり特化したリニューアルをしていただきたいと思っています。この児童センターの機能分散と、世代別特化という考え方について、ご見解を説明するよう求めました。","respondent":"上野子ども育成課長","answer":"子どもたちの声を聞きながら、子ども・若者活動拠点のような居場所づくりや多様な活動機会の創出につながる取組を進めてまいります。今後も利用者のニーズや価値観を踏まえ、従来の児童センターが担う役割も大切にしながら、時代に即した施設整備や事業展開を目指してまいります。","id":"exchange-133"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要望としまして、成長段階に応じました、児童センターの世代別特化に関する調査・研究を速やかに開始していただきたいと思っています。先ほど言いましたティーンズプレイスを試験的に設置するなど、具体的なモデル事業に着手することを求めますが、ご見解を説明するよう求めました。","respondent":"上野子ども育成課長","answer":"ただいま委員からご要望のございました調査・研究、それからサテライト型のティーンズプレイスの試験的な設置につきましても、今後、児童のニーズ等を踏まえながら、検討してまいりたいと考えております。","id":"exchange-134"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"令和６年度に本区では約４,１８６万円の予算を執行しまして、２９１名の民生委員、児童委員の皆様の活動を支援してまいりました。現在の民生委員制度の持続の可能性について、どのような危機感を品川区はお持ちか尋ねました。","respondent":"東野福祉計画課長","answer":"定年延長ですとか、平日の活動ができないような状況、それから日頃からの地域のつながりが不足しているような状況といったものがあります。","id":"exchange-135"},{"speaker":"まつざわ委員","kind":"質問","question":"その中でやはりやってくれる方の善意ももう限界に来ていると私は思っています。その中で、具体的にどのような募集活動、そしてまた魅力の発信といったことに取り組んでいるのか説明するよう求めました。","respondent":"東野福祉計画課長","answer":"現在、定員３２５名のところ、こちらの決算書の記載では２９１名とありますが、２人減って２８９名という状況です。そういったところと分担しながら、高齢者の見守り、地域の見守りをしているような状況です。","id":"exchange-136"},{"speaker":"まつざわ委員","kind":"提案","question":"そういった部分で、少し提案したいのが、例えばＯＢ、ＯＧの方もやっています。そうすると、１人当たりの担当世帯数というのか尋ねました。","respondent":"東野福祉計画課長","answer":"毎年５月、民生委員ブースを設けまして、ＰＲ活動を行わせていただきました。各地区１３地区で、その地区ごとにその解消という形で、受持ちのバランスをとっているところです。","id":"exchange-137"},{"speaker":"まつざわ委員","kind":"質問","question":"最後に補助員の制度を言おうかと思ったら、補助員は支え愛もいて、随分しっかりとしていたので、例えば若手人材の参画を進めるために、夜間、休日中心の活動であったり、オンライン相談できる人材を確保すると思いますが、これは品川区でやっていくべきと思いますが。","respondent":"東野福祉計画課長","answer":"今後の活動につきましては、委員が提案のＩＣＴなどの活用についても考えていかなくてはいけないと考えています。日中の活動にも取り組んでいる自治体がありますので、そういった自治体の例を参考にしながら、区としても進めてまいりたいと思います。","id":"exchange-138"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/239858?Template=document&Id=7255#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":114953,"voices":328}},{"id":"r07-20251006-4","meetingId":"r07-c-settlement","date":"2025年10月6日","dateIso":"2025-10-06","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 令和６年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 令和６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"西村委員","kind":"質問","question":"９月の豪雨災害に伴って発生した災害ごみについて伺います。今回の災害での清掃事業所の現場の対応状況と判断について伺います。","respondent":"篠田品川区清掃事務所長","answer":"かなりひどい状況になっているというようなご連絡をいただきまして、それで急遽、翌日の対応をどうしようかということで整理をしたところです。今回、事業系のごみも収集していこうというようなことを基本的には決めまして、当日の対応とさせていただいたところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"提案","question":"この経験を将来の災害対応に活かしまして、体制を構築するために提案をさせてほしいと求めました。清掃事務所として、収集量の把握方法ですとか、決定のスピードをどのように確保し、被災者への周知をどのように行ったのか、説明するよう求めました。","respondent":"篠田品川区清掃事務所長","answer":"まず、専用の車４台を仕立てまして、災害ごみだけを収集するということで走らせました。それから、連絡をいただいて受け付けたものは全て、そういったものも収集していこうという形で整理をして対応したところです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"被災者の負担軽減を標準的な運用としまして定着させてほしいと求めましたが、いかがでしょうか。無料収集の対象などを明確にしてほしいと求めましたが、いかがか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"清掃事務所としても対応できることはしていこうということで、今後につきましても、同じような対応を取っていきたいと考えているところです。特殊な対応というのは取れるかどうかというのはなかなか難しいところがありますので、今、検討しています。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"基金の活用など、どのように行っていかれるのか、ぜひともご検討ほしいと求めました。１点だけ、近隣区の状況について伺いたいのですが、実際のところはいかがでしたか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"いろいろ聞き及んだ範囲ですと、やはりどこも基本的には手続として罹災証明が必要だということですので、その形で対応されたと聞いています。３週間ぐらいかかっているというような形で、結果的には、私どもの今回の判断というのは間違っていなかったと感じているところです。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"５月には補正予算の編成も行われたと承知しておりますが、トータルの事業規模について伺いたいと思います。令和７年度予算特別委員会で我が会派のこしば新議員が質問した、中小店舗、２点併せてお答えほしいと求めました。","respondent":"小林地域産業振興課長","answer":"１万２,５００円の中で、５,０００円分については、中小店舗両方で使える。専用券という形で７,５００円、この部分は必ず中小店舗で使っていただくというような制度設計を行ったところです。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"事前の購入申込み状況について伺いたいのですけれども、その余った予算を紙の商品券に振り替えて対応したというお話も伺っております。１０月から販売が始まったデジタル商品券ですけれども、取扱い店舗数は区内全体でどの程度になっているのか、説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"割合にすると９９.７％ということで、ほぼ１００％に近い申込みをいただいて、販売を行っているところです。店舗数ですけれども、若干、日々変動する部分はありますが、区内店舗の中で合計７,３００店舗での取扱いが可能となっています。","id":"exchange-006"},{"speaker":"西村委員","kind":"確認","question":"私も、これまでだったらホームページを見に行って取扱い店舗を探していたのですけれども、アプリでさっと確認できるようになりました。ここまで取扱い店舗数を増やせた理由を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"２３区ですとか、そういった場合に、店舗開拓というのが難しいです。その仕組みに乗った上で品川区のデジタル商品券を使うということについては、大変やりやすいというか、理解が進んだと認識しています。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問・要望","question":"地域交通政策課のヘルメット購入助成時のお渡し、教育委員会で開催している講座等の謝礼など、様々利用されていると伺っております。デジタル商品券の利用を広める中で、行政分野でのほかの施策にも活かしてほしいと求めましたが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"例えば、スマートフォンのアプリを使って、今委員ご提案のような使い方というのもできる可能性が十分あると考えています。庁内各課とも、そういう使い方があるなら多目的利用ができないかというところは、一緒に考えて話をしていきたいと考えています。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問・要望","question":"デジタル商品券の多目的利用のご検討をぜひお願いしたいと思います。今後進められる令和８年度の予算編成におきましても、プレミアム率２０％もご継続いただきたいと考えていますので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３２９ページ、産学連携推進事業、２９９ページ、ＡＥＤ管理費、時間があれば、３０９ページ、そ族昆虫防除対策費からお聞きします。３２９ページ、産学連携推進事業と、それに関連しまして幾つかお伺いいたします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"なかなか連携が取れなかったというところでございまして、こちらには、そちらで代替して対応させていただいたところです。製造業、そういったところは地域経済にとても影響を及ぼすものだと考えておりますので、継続してやっていきたいと考えております。","id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問","question":"今おっしゃっていただいた都立産業技術高等専門学校の指導の実施回数が令和６年度はゼロだったということで、どうしたのかと思っておりました。教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区としましては、区で年２回、大学の研究室を訪問する機会を設けております。これは大学の先生と話し合って、ケース・バイ・ケースでやっていることかと思いますので、それについては区では関与しているところではございません。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちらは強く要望いたします。五反田バレー含め、今後の展開と方針を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"今後の産業支援をどのように進めていくかという部分ですけれども、大きく言うと３つ、重点分野はあると考えております。こういった部分を総合的に実施しながら、区としてもいろいろな支援を行いながら、地域経済の活性化に努めてまいりたいと考えています。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして、ＡＥＤについてお伺いします。現在の区の施設やコンビニエンスストア等の設置状況、併せてパッドやバッテリーなどの維持管理について説明するよう求めました。","respondent":"勝亦健康課長","answer":"区内各施設に設置しておりますＡＥＤにつきましては２９４台、それから、コンビニエンスストアに８９台、合計で３８３台がリースで入ってあります。メンテナンス等につきましては、リースの事業者で行っているところです。","id":"exchange-013"},{"speaker":"おぎの委員","kind":"質問・要望","question":"２４時間開いているコンビニエンスストアへの設置、非常に心強く感じます。使い方の周知も含め、また広げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私からは、２９９ページのＡＥＤ管理費についてお伺いします。さらなる設置店舗の拡充についても求めてまいりたいと思いますが、ここについての今後の展開についてお聞きできればと思います。","respondent":"勝亦健康課長","answer":"約１,２００台ほどのＡＥＤが設置されているところですが、それから、２４時間対応できるものが約１８０台ほどになってあります。そういった意味では、２４時間対応できるところへの設置を拡大していく必要があるだろうと考えています。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"現場から片道１分以内の密度でＡＥＤを配置するという考え方に基づき、３００ｍ以内にＡＥＤを設置するという目安も引き続き推奨されています。２０１８年の予算特別委員会の場で求めしていますが、現在、さらに大手１社との協定により設置の拡充を重ねて求めますが。","respondent":"勝亦健康課長","answer":"コンビニエンスストアとの連携ということで、先ほど出てまいりましたローソン、残りファミリーマートというところなのかと思います。共創というところで、そういった連携ができないかということで、積極的に協議をしてまいりたいと考えております。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"大手３社コンビニエンスストア全てに設置している自治体はまだまだ少ない状況です。人命救助の輪をさらに大きく広げていけるものになると考えますが、改めて区の見解をお聞きできればと思います。","respondent":"勝亦健康課長","answer":"地域のインフラとして、コンビニエンスストアは２４時間開いているというところで、非常に貴重な地域の拠点といいますか、インフラだと考えています。そういった意味では、繰り返しになりますけれども、積極的に包括連携協定等々も相談をしていきたいと考えています。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"大手もう１社との包括連携協定の締結等、コンビニエンスストアへのＡＥＤのさらなる拡充を求めていきたいと思います。最後に何かあれば、お聞きできればと思います。","respondent":"勝亦健康課長","answer":"コンビニエンスストアに限らず、様々な主体と連携をして、できるだけ多くのＡＥＤが設置できるように努めてまいりたいと考えています。それから、そういった意識、こういったものを周知啓発していく必要があるかと考えています。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"一昨年の第３回定例会にて、周知と、品川区で管理しているＡＥＤのケースに三角巾の配備と使用方法の説明書を添えることを求めました。","respondent":"勝亦健康課長","answer":"区のホームページでも、衣類がはだけることなく、肩口ですとか脇腹にＡＥＤをつけることで使用できますということで周知を図っているところです。とはいえ、さらに女性に対する、こういったＡＥＤの使用について、意識啓発ですとか、周知を行っていく必要があると考えています。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"どうしても突然の対応で、見知らぬ人、他人の衣服をずらしたりする行為は、プライバシーの観点からも、人命救助のためらいになります。改めてＡＥＤケースに三角巾の配備と使用方法の説明書を添えることを求めたいと思いますが、区の見解をお聞きできればと思います。","respondent":"勝亦健康課長","answer":"幾つかの自治体で、プライバシー保護ですとか、救急救命用に三角巾を入れている自治体が出始めているということも確認をしています。こういった三角巾の導入を検討する中で、それから説明書の封入、事業者とも協議をしていきたいと考えています。","id":"exchange-020"},{"speaker":"ゆきた委員","kind":"確認","question":"ですが、後日確認させていただきましたが、その中にゴム手袋とかはさみといった資器材が一式入っております。そうすることで、１分１秒を争う現場で、改めて区の見解をお聞きできればと思います。","respondent":"勝亦健康課長","answer":"ＡＥＤの中にゴム手袋ですとかはさみ、そういったもの、救急セットが入ってあります。固定に使うような形で様々な使い方ができると考えていますので、それから、周知啓発を考えていきたいと思います。","id":"exchange-021"},{"speaker":"ゆきた委員","kind":"意見","question":"ぜひ進めてほしいと求めました。重ねて、区で管理しているＡＥＤの中に入っているレスキューセットの資器材についても周知できる取組を進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、このデジタル商品券ですが、商店街加盟の店舗においてどの程度使われると考えているのでしょうか。区は、商店街支援の効果をどの程度見込んでいるのか、伺います。","respondent":"小林地域産業振興課長","answer":"デジタル商品券が区内でどれぐらい使えるかですけれども、全体で７,３００店舗です。大型店、品川区商店街連合会加盟の店舗というところでは、８００店舗程度がこれを実際使われていると認識しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"引き続き同様の事業が行われるのであれば、商店街加入店舗に限定した決済手数料の助成をしていただきますよう強く要望しますという声です。伺いますけれども、これを行うような制度設計に改善してほしいと求めましたけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"ですので、今回、紙の商品券、デジタル商品券を合わせて、そういう流れの中で対応もしていかなければいけないです。その中での対応というのもしっかり注視していきたいということと、引き続き品川区商店街連合会加盟の店舗も支援していきたいと考えているところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"あのお店でこういうものを買ったとか、家族とこういう思い出があったとか、そういう大事なインフラだと私は思っているのです。さらに一歩踏み込んで、ぜひ支援を検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"区の商店街支援というところで、日々、こういったところにも東京都の補助金なども使いながら支援をしています。そういった事業をいろいろ進める中で、商店街が地域の中で元気に活動していく、そういう取組を支援していきたいと考えています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ一歩踏み込んでさらに支援してほしいと求めました。次に、公衆浴場なのですが、現在の区内の銭湯の数は幾つあるのか、まず、お伺いしたいと思います。","respondent":"勝亦健康課長","answer":"現在、品川区内に、公衆浴場ですけれども、２０施設という状況になってあります。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ある高齢者の方から要望をいただいたのですが、銭湯券の配布がありまして、品川区では配布していないのでしょうかと。伺いますけれども、パスを発行することによる割引入浴を実施していただきたいのですが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"出会いの湯ですけれども、介護サービスとして実施している部分はあります。その他、他の自治体も参考にしながら、いろいろ研究してまいりたいと考えています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり支援を強めていただきたいと思いまして、年に４日、区民無料開放デーというのを設定しているのです。新たな世代や、これまで銭湯になじみがなかった区民を銭湯に呼び込むような、そういった支援も進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"会員数の状況について伺います。そして、その上で区としてこの動向をどのように捉えているのか、伺います。","respondent":"小林地域産業振興課長","answer":"男性が１,１４２名、女性が９８０名という形で、男性がやや多いと認識しています。我々、お一人当たり大体平均５.５万円分ぐらいお仕事をされているというような、そういうお仕事のされ方をされていると認識しています。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"次に、受注形態について伺います。品川区シルバー人材センターではどのような営業活動を行っているのか、そして、区として今後営業機能をどのように支援していくか、ご見解を伺います。","respondent":"小林地域産業振興課長","answer":"その３つ、こういうお仕事ができますというお知らせなどもしながら、実際にお仕事を出していただいているところがあります。そういうところを含めて、こういう仕事の受注の件数が増えるように、区としても支援をしていきたいと考えています。","id":"exchange-030"},{"speaker":"せらく委員","kind":"確認","question":"シルバー人材センターで新規開拓も積極的にやっていくという方向であること、確認いたしました。例えば、週４０時間までの就労が可能になったとありますが、品川区としてはどのように努めているか、お考えを伺います。","respondent":"小林地域産業振興課長","answer":"就業は大体月１０日程度、あるいは週２０時間程度という形で、区としてもシルバー人材センターのＰＲとしています。そういう中で、安全面も特に配慮しながら、しっかりやっていただけるようにということで引き続き支援をしてまいりたいと考えています。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"最後に、デジタル化への対応について伺いたいと思います。現在、Ｓｍｉｌｅ ｔｏ Ｓｍｉｌｅというシステムを導入していると承知していますが、活用の広がりというところを教えてほしいと求めました。","respondent":"小林地域産業振興課長","answer":"そのやり取りという通信の部分をデジタル化というところで支援しておりますし、無理がある場合には、紙でも引き続きやっているところです。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"本日、シルバー人材センター、品川区の現状についてたくさん質問させていただきましたが、現状を伺うことができました。安全面も寄り添って、今後もよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、健康教育事業についてお伺いいたします。プレ更年期の講座の開催など、更年期障害や更年期症状を和らげるための予防的な支援の強化を要望いたしますが、区のお考えを説明するよう求めました。","respondent":"小林地域産業振興課長、勝亦健康課長","answer":"区として、このような景況感の把握も含めてですけれども、直ちに補正予算、５月、６月と続けて実施しています。講習会を実施するとともに、女性の特性を踏まえた健康支援を、より一層推進していきたいと考えています。４０代からの健康塾ですとか、体力低下の対策に伴う水中散歩、こういったものを実施しています。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"区内中小企業の求めに応じて、社内の人事労務制度改善のための相談対応を行うなど、魅力ある職場づくりを支援していると聞いています。","respondent":"勝亦健康課長","answer":"更年期につきましては、センシティブな部分もありますので、慎重な研究が必要ですけれども、引き続き女性の健康習慣、そういった機会を捉えて、周知啓発に努めていきたいと考えています。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"２年前の一般質問でもご質問いたしましたが、改めて伺います。利用者アンケートにおいて、前回ご質問した際も、景品に対する、商品券やデジタル商品券に対する要望が多かったと記憶しております。","respondent":"勝亦健康課長","answer":"利用者の内訳ですけれども、３０代から５０代の方がボリュームゾーンになってございまして、利用者の約７割がこの年代に入ってあります。","id":"exchange-036"},{"speaker":"山本委員","kind":"確認","question":"利用者は、私の確認している限りですと、６,０００人ぐらいと把握しております。伺いますが、先日の一般質問に対する区からのご答弁で、企画経営部等の関係部と協議をされましたか尋ねました。","respondent":"勝亦健康課長","answer":"委員から昨年、デジタル地域通貨等々について、健康ポイントを含めて、お話はいただいていると認識しています。そういった連携の可能性は、企画部門と意見交換等は行ったところですが、具体的な経費等については検討までは至っておりません。","id":"exchange-037"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、こちらもほかの委員からもご要望がありましたけれども、私からもお願いしたいと考えているところです。１点、私からお聞きしたいのは、手数料減免や無料化ということがしにくいと聞いております。","respondent":"小林地域産業振興課長","answer":"同じ商品を買ったものに対して区が違う決済手数料の支援というのは、財政的な負担というのも今後一つ課題にはなるだろうと考えています。","id":"exchange-038"},{"speaker":"山本委員","kind":"提案","question":"先日の一般質問において、施策効果の最大化などの観点でご提案をさせていただきましたけれども、検証をしたのでしょうか。２年前にも細かく説明しましたけれども、定量的に比較をされていらっしゃいますか尋ねました。","respondent":"横田デジタル推進課長","answer":"地域活動課などと情報共有ですとか意見交換を行うとともに、品川区商店街連合会とも協議しながら、調査研究を進めてまいりました。他自治体の事例も参考しながら、経費や効果などの面で多角的に検証を行ってきたところです。","id":"exchange-039"},{"speaker":"山本委員","kind":"質問","question":"今お聞きしていると、来年度予算では難しいとの感触ですけれども、再来年度以降、ぜひ改めて検討してほしいと考えております。ご見解をお願いします。","respondent":"横田デジタル推進課長","answer":"先日からデジタル商品券を開始したところでありまして、現時点でデジタル地域通貨の導入をする予定はございません。","id":"exchange-040"},{"speaker":"山本委員","kind":"提案","question":"今回あえてご答弁は求めませんけれども、今後、デジタル地域通貨の導入を要望していきたいと思います。この７月、会派でスタートアップ支援について、福岡市へ視察に伺いましたとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"品川区としましても、福岡市といろいろ施策を進めておりますので、引き続き精進してまいりたいと考えております。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"何とか鎮静薬や鎮痛剤の使用を認めてほしいというお声が届いていることから、区民ニーズがあるということで求めさせていただきたいと考えています。過去の議事録を確認しますと、厚生委員会でこのような要望が上がったという議事録を確認いたしましたが、お伺いをします。","respondent":"勝亦健康課長","answer":"１件、２件、そういったものです。医師会で行います、実施医療機関が参加いたします精度管理委員会では、そちらは検討課題として出ているところではございません。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問・要望","question":"胃がん検診がどうなっているのか確認しましたけれども、１,５００円を区民が負担して、自己負担の下で進められております。受診率の向上につながっていくと考えますが、改めて見解を伺います。","respondent":"勝亦健康課長","answer":"麻酔をしないことを原則といたしまして、細い内視鏡ですとか、鼻からの挿入を進めているというような状況です。実施医療機関全てが参加している精度管理委員会、しっかり実施、選択式の可否の可能性について協議していく必要があると考えています。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"適切な治療、予防につながることから、会派よりかねて要望させていただきました。検討した上で、本格実施を目指していくというご答弁がありますけれども、今時点での検討状況についてお伺いをしたいと思います。","respondent":"勝亦健康課長","answer":"試行実施ということでご紹介いただきましたけれども、実施はこれからになりますけれども、年度内に４回実施する予定になってあります。まだ実際に行っている状況ではございませんけれども、来年度に関しましては、こちらをさらに拡大していきたいと考えています。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問","question":"既に江東区、港区、中央区などでは、４価ワクチンに加えて、助成の対象になっているとお伺いをいたしました。今後の品川区の対応もお伺いをしたいのですが、まず初めに、品川区のＨＰＶワクチンの男性接種について、現状をお伺いします。","respondent":"五十嵐保健予防課長","answer":"品川区では、令和６年から、男性のＨＰＶワクチンの任意予防接種につきまして、全額助成を開始させていただいたところです。昨年度の実績としましては、１回目を接種した方が６８名、２回目が５０名、３回目が３４名というような実績になっているところです。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問","question":"このワクチンにつきまして、東京都でも補助の対象にするということも伺っているのですが、区は東京都の補助を活用していると思われます。","respondent":"五十嵐保健予防課長","answer":"４価ワクチンのみの予算しか取っていないことから、今年度につきましては、９価ワクチンの助成は実施しない予定にしております。４価ワクチンを打った後の９価ワクチンにつきましては、そちらも特に問題なく実施できるかと考えているところです。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３１５ページ、温暖化対策事業、太陽光発電・蓄電池システム設置助成、それと、３１３ページ、感染症予防費についてお伺いをします。最初に、３１５ページ、太陽光発電・蓄電池システム設置助成についてお尋ねをします。","respondent":"中西環境課長","answer":"太陽光発電についてのお尋ねです。ゼロカーボンというものに品川区は取り組んでいる中で、国や東京都においても助成金を出しまして、普及拡大に努めているところです。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"提案","question":"そこで提案なのですけれども、品川区との交流都市がありますよね。あえて飯田市と申し上げますが、再生可能エネルギーで発電した電気を品川区が購入したらどうですかという提案なのですけれども、いかがか尋ねました。","respondent":"中西環境課長","answer":"株式会社エナーバンクという会社と連携協定を締結いたしまして、今、協定の中で進めているところです。それから、地方連携といったようなところの観点ですとか、そういったところから双方のメリットを考えながら整理してまいりたいと考えています。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"再度申し上げますけれども、飯田市で新たに太陽光発電を進める動きというのもあるそうです。ほか自治体の再生可能エネルギーで発電した電気を品川区にぜひ取り入れていただきたいのですけれども、私、その辺についてお尋ねをします。","respondent":"中西環境課長","answer":"それから、最近ですと、いわゆるペロブスカイト太陽電池といったような新しい技術等もあります。今度は、そういったものも含めまして、委員ご指摘の連携都市との連携の中でのお話も含めて検討してまいりたいと考えています。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３１３ページ、感染症予防費についてお尋ねをします。今回の風しん排除認定に対しまして、品川区の風しん対策の総括と、今後の取組についてご説明をお願いいたします。","respondent":"五十嵐保健予防課長","answer":"５類感染症の風しんということで、本当に風しんかどうかということで、ＰＣＲ検査を東京都と協力して実施させていただいているところです。今後妊娠を考えている方と同居している方につきましては、予防接種の実施につきまして、費用の補助をさせていただいているところです。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"提案","question":"特に感染症予防については、しながわこどもぽけっとに掲載するということは、保健所はどのようにお考えでしょうか。お尋ねをしますとの意見を述べました。","respondent":"五十嵐保健予防課長","answer":"現在、区のホームページなどで周知はさせていただいているところですが、なかなか皆さんに届けるところは難しい部分があると考えています。子ども育成課とも協力して、周知方法については考えさせていただきたいと考えています。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"提案","question":"がん検診の無償化は、共産党区議団の予算修正でも、毎年、提案をしているところですけれども、その額は３,６００万円と試算しました。既に９区ががん検診の無償化をしていますので、改めて全てのがん検診無償化を求めますが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"こちら、重要なお声だと考えています。自分にがん検診の必要性を感じていないという方のパーセンテージも非常に多うありますので、こういったところについても啓発が必要だと考えています。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"改めて検診の無償化をぜひ求めたいとお願いしましたが、その点はいかがか尋ねました。","respondent":"勝亦健康課長","answer":"その中で、無償化、費用を少し減らしていく、負担を減らしていく、こういったものも一つの手段かと考えます。受診率の向上施策の中で、様々な手法、無償化も含めて検討してまいりたいと思います。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"荏原医師会からは、喉頭がん検診の継続を求める要望書を頂きました。廃止という評価をやめていただきたい、改めてほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"しかしながら、それぞれの医師会の中で、すぐの廃止については反対というご意見を伺っているのは確かです。今後、それぞれの医師会からもご意見を伺いながら、しっかり検討してまいりたいと思います。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"次に、子どもの健診について伺いたいと思います。集団健診になるというのが２割ぐらいということなので、私は親にとって、そのフォロー体制がどうなっているかについても伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"健診の前にしっかりとこの事業の目的と重要性というのを、対象となるご家庭の方に通知を送らせていただいて、ご説明をまずしています。お電話でお受けしましたが、しっかり保健師が一人一人にご説明をさせていただいて、健診に来ることの重要性をしっかりとお伝えしています。","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この問題は、様々、保健センターだけでなく、全庁的にぜひ取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"えのした委員","kind":"提案","question":"おぎの委員、ゆきた委員からも質問がありましたので、違った視点も踏まえてお伺いします。令和５年度決算特別委員会でも様々質問、提案していますが、内部で様々検討しているとのご答弁をいただきましたとの意見を述べました。","respondent":"勝亦健康課長","answer":"そういったものを設置することによって、緊急蘇生、そういったものが手軽に、しかも迅速にできるようになる。これを進めるために、区としても設置を進めているところです。","id":"exchange-057"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。ＡＥＤの場所もマップ上で分かるような形でリンクを張ったりと、努めているとのご答弁でしたが、その後は何か取り組まれていますか尋ねました。","respondent":"勝亦健康課長","answer":"ＡＥＤは、ホームページで一般財団法人日本救急医療財団の地図にリンクをするような形を取りまして、設置場所が分かりやすくなるようにしています。身近なＡＥＤへの道順を示してくれるようなアプリでございまして、こちらを区のＡＥＤのホームページでも紹介しています。","id":"exchange-058"},{"speaker":"えのした委員","kind":"質問・要望","question":"都内の救急車到着までの平均時間は８分ほどであり、緊急時には、このマップなどは確認している時間と余裕はありませんでした。その後、講習会などの取組は進んでいますか尋ねました。","respondent":"勝亦健康課長","answer":"今、委員にお伝えいただきましたように、実際に行動できる人、その意識と技量を持った人を増やしていくことが大事なことだと考えています。こういった普通救命講習よりもう少しライトな形で心肺蘇生の講習が受けられるような形で実施できないかということで、消防とも、今。","id":"exchange-059"},{"speaker":"えのした委員","kind":"質問・要望","question":"ちゅうちょせずに使用するには、実際に体験する講習会や訓練が重要だと考え、取組の拡充を要望といたします。ぜひ積極的に取り組んでいただけますよう要望いたしますが、区としても何か一言お願いいたします。","respondent":"勝亦健康課長","answer":"コンビニエンスストアを含めて、さらなる休日、夜間も含めてＡＥＤの設置が進むよう、様々、協議を進めてまいりたいと考えています。様々、講習会ですとか、周知啓発に積極的に努めていきたいと考えています。","id":"exchange-060"},{"speaker":"えのした委員","kind":"質問・要望","question":"維持管理として、先ほどのパッドですとかバッテリー、こちらの交換も、実際に使うときに重要になりますので、ぜひこちらも取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"３０６ページ、生活衛生費より、災害時における保健所の対応と、そのための準備、計画について伺いたいと思います。保健所としてどんな準備をするのか、どんな計画を立てていくのか、伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"取組の今の検討状況ですけれども、保健所としまして取り組んでいる内容としまして、区ホームページで周知啓発をしています。支援物資であったりとか、どういった形でやっていくのかにつきまして、防災課と連携して引き続き取り組んでいるです。","id":"exchange-062"},{"speaker":"中塚委員","kind":"提案","question":"例えば、防災訓練の際に配布するなど具体化したらいかがかと思いますけれども、提案させてほしいと求めました。特に栄養バランスについて伺いますけれども、どんな食事上の問題があったのか、認識も伺いたいと思いますとの意見を述べました。","respondent":"赤木生活衛生課長","answer":"極力、保健所からも案内をするというところについては現状も取り組んでおりますが、防災課と引き続き検討してまいりたいと考えています。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、なぜ炭水化物中心になるのか、なぜビタミンやたんぱく質が不足するのか、その原因を保健所としてどのように考えているのか、伺います。それを踏まえて、ぜひここを克服する計画を持ってほしいと求めましたけれども、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"７２時間以降であったりとか、避難所に長期的に避難が必要になってきた場合の栄養バランスに関するご質問について、お答えをします。ただ、例えば、そういうビタミンを含むもので手頃に取れるようなものを徐々に配布できるような体制づくりというのは重要と考えております。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望だけ。７２時間以降のメニューや献立について、訓練の中でこういうことが想定されるというように広げていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"ここで聞きたいのは、この目標頭数でありますが、どのようにして３２０頭としたのでしょうか。本年度では、２００頭とのことですが、その目標頭数について伺います。","respondent":"赤木生活衛生課長","answer":"先ほど、目標頭数を徐々に減らしていっているところにつきましては、事業の一定の効果があらわれている証拠だと我々としては認識しています。","id":"exchange-066"},{"speaker":"松永委員","kind":"質問","question":"より安心して生活できる環境を整えるために質問いたしますが、令和６年度の実績において、苦情は主にどのような地域から寄せられたのでしょうか。苦情件数の中には、同一の方から繰り返し寄せられるケースも含まれているのか伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"苦情についての地域の偏りがあるかというお話をいただいたかと思いますが、特段、地域によって差があるとは区としては認識しておりません。基本的にはそれぞれ相談いただいた方につきまして、その都度、職員が対応しているというところが現状です。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"こうした場合、本区として力になってくれる事業はあるのでしょうか。どのような対応をすればよいのか、アドバイスを伺えたらと思います。","respondent":"赤木生活衛生課長","answer":"何らかの薬物等により猫の不審死が起きているという事実につきましては認識しておりまして、何かそういう健康被害といいますか、最悪の場合。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"続きまして、３１７ページのアスベスト対策事業、調査助成と除却助成について、いわゆる現状、実施状況について伺いたいと思います。","respondent":"中西環境課長","answer":"昨年度、令和６年度の実績ですが、分析調査が６件、除却助成が１件となっています。一昨年度の令和５年度が、分析調査が４件、除却助成が１件、もう一つ遡りますと、令和４年度で、分析調査が４件、除却助成が２件となっています。","id":"exchange-069"},{"speaker":"松永委員","kind":"意見","question":"工務店とか、いろいろお声を聞くと、もう終わってしまったというお話を聞いてはおります。なぜ終わったのか、それぞれ理由があると思うのですが、そうしたところをお知らせほしいと求めました。","respondent":"中西環境課長","answer":"一応、分析調査に関してが先着で６件、それから除却助成が先着で２件となっています。申請の受付を終了したという形ですが、除却助成に関しては１件でしたので、もう１件申請ができるような状況にあったです。","id":"exchange-070"},{"speaker":"松永委員","kind":"質問・要望","question":"やはり１軒しかないのです、ご依頼主が、値段が少し高いということでやめられるケースが多いとお聞きしております。簡単でもいいので、お知らせのようなチラシをつくって配布をしていただきたいと考えていますが、区の見解をお伺いします。","respondent":"中西環境課長","answer":"事業者向け説明会等々の場で、引き続き、多くの方に届くように検討してまいりたいと考えています。ほかの区で高い区があるということは私どもも認識していますが、１件であったりといったところで、少しそこは検討が必要と思ってあります。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"３１３ページ、こころの健康づくり事業で、グリーフケアについて伺っていきたいと思います。そして、品川区の体制も強力にしていただく必要性があるのかなというところで、品川区のグリーフケアの現状を説明するよう求めました。","respondent":"飛田荏原保健センター所長","answer":"地域包括支援センターでの相談内容、各種手続の窓口での丁寧な対応など、個々のニーズに応じた支援を行っているところです。区内の位置づけをしっかり把握しまして、関係機関と連携をとりながら効果的なグリーフケアの事業の検討を引き続き行っていきたいと考えております。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"今後、また来年度の予算に向けて、そうしたところを全体としてどのように拡充させていけるのかということを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"品川区として、若年女性の人工妊娠中絶実施の数について把握しておられますでしょうか。もしくは、把握に努められておられるのか伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"委員ご質問の望まぬ妊娠の統計については、今品川区では把握はしておりません。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしても学校でとなりがちだと思うのですけれども、それから教育委員会が横断的に協力して行うべきと考えますが、見解を伺います。既に実施された施策があれば、それについても伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"知識があることはとても重要なことだということは認識しておりまして、つらい思いをする方もいなくなるということは理解しております。未然に知識を身につけるということから、その後の相談というところまで、関係部署で連携してやっていく必要があると認識しております。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"しっかり相談に乗っていただくということは本当に重要なことと思いますが、私が求めたいのは、それを未然に防ぎたいということです。検討状況があれば伺いたいと思いますし、検討していただきたいと思うのですけれども、その点について伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"区全体の施策になりますが、そちらについては、保健センターのみでというところではありませんので、子ども未来部ですとか、総務課などと調整をして研究してまいります。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう少し分かりやすい情報提供をお願いしたいのですけれども、検討されているでしょうかということと、収入で計上されると思います。歳入のところで伺わなかったのですけれども、どこにあらわれているのか、その２点について伺います。","respondent":"篠田品川区清掃事務所長","answer":"まだ１割強ぐらいの方しかご存じなくて、こちらも３割ぐらいの方がご存じだったという形で、まだまだ伝わっていないなと非常に感じるところです。ですので、こちらに関しては、今後とも、引き続き周知徹底に努めてまいります。","id":"exchange-077"},{"speaker":"澤田委員","kind":"質問","question":"本日は、２９９ページ、健康ポイント等事業、３０５ページ、食からの子育て支援事業についてお伺いします。アプリ自体の対象年齢とボリュームゾーンの割合を説明するよう求めました。","respondent":"勝亦健康課長","answer":"対象年齢につきましては、１８歳以上の方の全世代を対象としています。一番ご登録が多いのは３０代から５０代の方で、こちらで約７割の方にご利用いただいているところです。","id":"exchange-078"},{"speaker":"澤田委員","kind":"質問","question":"新しい取組も行われていて、今後も他課と連携して商品開発を行うということもぜひ進めていただければと考えています。よりニーズを把握することも、より一層の魅力アップへとつなげていけると考えますが、様々なアプローチについてご意見を説明するよう求めました。","respondent":"勝亦健康課長","answer":"高齢者の方には、講座の中などでチラシ等を配布するなど、こういった取組を進めていきたいと考えています。ご提案いただいたように、広くご意見を伺えるように、様々な世代のニーズに合わせたプレゼントとなるように考えていきたいと思います。","id":"exchange-079"},{"speaker":"澤田委員","kind":"質問","question":"様々周知していただいて、やはり今、高齢者の方へのアプローチは大事なのかなということをお伺いしながら改めて思いました。区民の健康の後押しとイベント自体を知っていただくきっかけづくりを推進してほしいと求めましたが、区のお考えを説明するよう求めました。","respondent":"勝亦健康課長","answer":"これを食べた方へのポイント付与ですとか、防災体験館をご利用になった方へのポイント付与、こういったものも予定しています。今後様々なイベントで活用していただけるように、連携、協力を庁内で幅広く働きかけていきたいと考えています。","id":"exchange-080"},{"speaker":"澤田委員","kind":"質問","question":"続きまして、子育てからの支援事業の中の離乳食教室についてお伺いします。とはいえ、離乳食教室はママがメインなのかもしれないと思うのですが、パパの参加は増えているのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"離乳食教室における父親の参加というご質問になります。母親のみの参加が３６.４％、父親のみの参加が２.７％となりまして、パパの参加も近年増えていると実感しているところです。","id":"exchange-081"},{"speaker":"澤田委員","kind":"意見","question":"パパはママと一緒でということではありますが、６割を超える方がパパとママとで参加されるということは大変うれしいと思っています。離乳食づくりをはじめ、育児への父親参加を推進してほしいと求めましたが、お考えを説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"区の考えになりますが、４か月健診、そういったところにも父親が母親と一緒に来所されることもとても多くなったと実感しております。両親学級ですとか離乳食教室、土曜日に実施しているところにつきまして、今後も周知を徹底していきたいと考えております。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、２９９ページ、ＡＥＤ管理費と、３２７ページの中小企業活性化事業費でお願いします。民間企業とも積極的に協議を進めるというお話がありましたが、具体的にどのような企業、業種を想定されていますか尋ねました。","respondent":"勝亦健康課長","answer":"拡大が考えられるというところと、施設、それから事業所の主体があります。区民の方に手が届きやすい場所にうまく設置できるような形で、これから様々考えていきたいと考えているところです。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"提案","question":"様々考えていただけるということで、ぜひご提案したいのは、介護施設への設置の助成です。そうすると、年間３００万円から４００万円ぐらいの経費でいけるのではないかと思うのですけれども、お考えを説明するよう求めました。","respondent":"勝亦健康課長","answer":"運営法人が必要に応じて設置をしていただけるような形になっているかと捉えてありますけれども、区と連携する中で、様々な手法があろうかと思います。その支援の在り方については、今後研究していきたいと思いますので、よろしくお願いします。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私の提案は遠のいたのかなと思いましたけれども、１６７いいねがついておりまして、ぜひ前に進めてほしいと求めました。最後に、何か受け止めがあればお願いしますとの意見を述べました。","respondent":"勝亦健康課長","answer":"休日を含めて、コンビニエンスストア等、そういった身近なところからまず設置を拡大していくことが肝要かなと考えています。利用に関する技術、知識、こういったものを広げていくことも併せて大事だと考えています。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"区として、最低賃金が上がったことに対する支援メニューがもし何かあれば、お伺いしたいです。いかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そして賃金アップにも対応できるような、そういった支援をするということで、そういった支援はしている中でも。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"２０２０年からでも、この５年間で１０％物価が上がっている、こういった状況で本当に悲鳴が上がっております。これは国が施策として１,５００円、２０２９年までということですけれども、そういったお考えはありますか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"米国による相互関税も４月に急に降ってわいてきたところで、急に経済界、激震が走ったと感じております。それから国と、それから世界の動きに注視しながら柔軟に対応していきたい、このように考えているところです。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"意見","question":"なかなか情報をとれない方がいたりとか、申請がなかなか大変だったりするということもあるので、できれば直接支援をお願いしたいと思います。最後に一言何かあればとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区としましては、直接支援というよりも、やはり企業の自助努力、それに補助していく形で支援をしていきたいと考えております。","id":"exchange-088"},{"speaker":"大倉委員","kind":"質問・要望","question":"小児夜間診療事業ですか、目的が救急を求められる小児応急診療に対し、運営とかはどのように変わってきているのかということを教えてください。昨年ですか、この必要性、意義を教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長、高山健康推進部次長、篠田品川区清掃事務所長","answer":"２１社の民間企業にご参画いただいているところでございまして、資金提供ですとか、そういった各種の支援をやっているところではありますけれども。昭和医科大学病院に夜間設置する小児救急でございまして、コロナ前と比較いたしますと、傾向としては回復傾向にあるといった点です。こちらに関しましては、確かに分かりづらいということですので、何らか対応できるかどうか検討する必要があるのかというように感じているところです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３１５ページの温暖化対策事業について伺います。その理由も伺います。","respondent":"中西環境課長","answer":"それからもう１点が、ＣＯ２算定のクラウドサービスの関係です。今年度に関しては、今、数社からご相談は頂戴しておりますので、何とか実績に結びつけてまいりたいと考えているところです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の気候危機対策の取組についての相談窓口をつくっていくことが必要ではないかと思いますけれども、いかがでしょうか。いかがか尋ねました。","respondent":"中西環境課長","answer":"今年度、エコルとごしにおきまして、区がやっている助成事業のパネル展示、それから相談会等を実施しています。来年度以降もできれば続けていきたいと考えておりますし、こういう助成事業、様々検討しながら取り組んでまいりたいと考えています。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"１回だけにとどまらず、ぜひ気軽に相談できる場所をつくっていただきたいと、改めてこれを求めておきたいと思います。品川区でも、これを進めていくためにも助成制度を実施することを求めますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"一つ効果のある手法かと思ってありますので、検討してまいりたいと思ってあります。１点あるところとしては、助成金をもらいました、どういった形が継続的かつ効果的かといったところは考えてまいりたいと思います。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"屋内避難といっても、家が地震で半壊・全壊して避難できる状況ではないということでしたので、ぜひこうしたことは改めていくべきだと思います。原子力発電所の計画撤回を国に求めるべきだと思いますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"国において議論されるべきものと考えています。区といたしましては、ご家庭なり、身近なところでできることについて取り組んでいくといったところを進めてまいりたいと考えています。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"それがやはり身近なところでも影響していきますので、ぜひ身近なところで取り組む自治体として求めてほしいと求めました。区民とともに気候危機対策を前に進めるために、専門の気候区民会議を設けることを求めますが、いかがか尋ねました。","respondent":"中西環境課長","answer":"今年度もこれから区内の大学の学長を座長に据えまして、大学生の方々と様々議論をしてまいりたいと思ってあります。深いところをやっていくのか、広く若い方々の意見を聞きながらやっていくのか、様々な検討をしてまいりたいと考えています。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう２０３０年が迫ってまいりました。５年、４年というところで、前に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問","question":"こういうことが私の地域の中で少し聞こえてきたので、どうなのですか。そして、このようなことがあるのですかということを簡潔に説明するよう求めました。","respondent":"高山健康推進部次長","answer":"今、委員からお尋ねいただいたようなご相談などが区に寄せられたことはございません。それから、ＭＲＩに関する検査料についての一般的な価格についても、こちらでは把握してございません。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"経営改善はされていないと思うのですが、どうなのですか、教えてください。そして、実際何をすれば中小企業の経営は改善できるとお考えなのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"その中でも、やはり企業が中長期的に継続して経営していくには、そういったことを地道に強化していくほかないのかなと考えているところです。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"でも、まず物価が安定しない限り何もできないのではないかと思うのですが、それがあってこその区の支援ではないでしょうか。その辺について、２つ、ご見解を説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ですが、やはりその中でも稼ぐ力というか、やっていく努力は必要なのかと思いますので、そういったところで、私どもは支援をしているところです。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今、日本国民、それから都民、品川区民、みんな何に困っているのですか。これでお話を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問・要望","question":"３２１ページ、それから３３１ページ、対象の拡大を要望させていただきました。ここについての検討はしっかりしていただきたいというところで、対象拡大について、どういった状況になっているのか説明するよう求めました。","respondent":"勝亦健康課長","answer":"言葉が外れたような状況になっておりまして、対象が、がん患者以外にも拡大されている状況です。都の補助の改正も趣旨も踏まえまして、拡充について区でも考えていきたい、このように考えております。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"毎日ごみの収集に当たられている作業員の方たちのお仕事に対する負担というのですか、多分、こういったことをやっている区があると伺いました。","respondent":"篠田品川区清掃事務所長","answer":"熱中症に職員がなったりしたときに対応できるような、そういった保冷パック、こちらを全ての清掃車に配置するというようなことをしてきました。なかなか市販のものは、どうしてもお金もかかることでもありますし、現状では、そういった形での対応。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"いろいろ対策をとっていただいているというところは、今ご説明いただきまして分かりました。今年は特に本当に暑かったので、そういった状況は、今どのような状況か尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"昨年度は、熱中症にかかった者は１人もいなかったです。たまたま１人、１人、通常の方では熱中症の方は出ていないという状況です。","id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"この夏、会派として中小企業の団体の方々と懇談したときにも、外国人の労働者を採用していきたいのだという意向を結構多く伺いました。品川区としては、外国人採用に関わる区の施策の現状を最初にお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"区では、モンゴルの方たち以外も受け入れていらっしゃるということで、ご指摘の外国人採用・定着セミナーという事業を実施しています。モンゴルの方を受け入れた企業を製造業の会社から１社、そういうところを解消するための支援のセミナー、支援を行っているところです。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"仕事そのものは企業の中で教えてもらったりということがあると思うのですけれども、この点について、地域産業振興課としてはどのように考えるか。１０月１８日に多文化共生の職場づくりというものの中で、地域産業振興課として、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"生活習慣に対する理解がきちんとできているか、こういうところが重要といいますか、定着の鍵になると考えています。先ほど申し上げた２件、ベースになると考えていますので、人材定着の取組をしっかりやっていきたいと考えております。","id":"exchange-104"},{"speaker":"塚本委員","kind":"意見","question":"多分、中小企業の皆さんの外国人採用については大きな支援になっていくのではないかなと思います。日本で働く外国人の方々が、よき隣人として品川区で共に生きていくというようなことが進めばと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"これ、一緒ではないですか。集中して効果のある展開をしていかなければいけないと思いますが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"考え得る様々なシミュレーションを行いまして、所内でしっかりと何度も検討を重ねて、このスキームを決定させていただきました。補助金もしっかりと検討した上で、少ない経費で最大のウェルビーイングを皆さんに提供できるようにということで、しっかりと事業を検討しております。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"やはり０歳児のおむつ宅配ですから、いろいろ研修をやっているかと思いますけれども、助産師とか保健師とかが行っているのです。保健師の人数を増やすとか、対象を４か月までではなくて延ばすとか、なぜおむつを抱えて１軒１軒回らなければいけないのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守りおむつ定期便は、１２回まで訪問できる形になりますが、毎月助産師や保健師が訪問するというのは人員確保の面からも難しいと感じております。結果としては、両方とも必要な事業として、しっかりと連携をとって運用していると考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、なぜ急にわざわざおむつを配り歩かなければいけないのか、もっと効果があることができるではないですか。なぜとってつけたように、どうすればもっと効率のいい、これからは検討を見直していただきたいと要求しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"せお委員","kind":"質問","question":"３０５ページ、母子保健指導事業費から、子どもの事故予防と、ＮＩＰＴ（新型出生前診断）について伺います。そして、どの予算で行っているのか、あと、その効果があれば説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"１歳６か月健診、３歳児健診、月齢や年齢に応じて周知を行っているところになります。４か月健診等でこういったチラシを配って、そういった意味では、啓発としての効果はしっかりあらわれているものと感じております。","id":"exchange-109"},{"speaker":"せお委員","kind":"提案","question":"提案の２つ目ですけれども、乳幼児親子が訪れる児童センターに啓発のブースをつくることも一つかと思っています。３点ご提案させていただいたのですけれども、このような啓発方法を含めて、保健所の今後の展開があれば説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"３保健センターで、それを実施できるかどうかというところも踏まえまして、検討をしていきたいと考えているところになります。こういった周知はやっていると認識しておりますので、連携を図って、しっかり事前に防げるような形の周知啓発は努めていきたいと考えております。","id":"exchange-110"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひお願いしたいのですけれども、先週、子どもの転落防止対策を求める要望書をＮＰＯ法人Ｓａｆｅ Ｋｉｄｓ Ｊａｐａｎとともに提出しています。ぜひ、まずは新しい施策などを検討していっていただきたいと思うのですが、見解を伺います。","respondent":"石橋品川保健センター所長","answer":"こちらは、先ほどお話させていただいたとおり、子ども未来部でも、こちらの事故防止という周知はしていると認識しているところです。今後、周知啓発も含めまして、しっかりと未然に防げる対策をやっていきたいと考えております。","id":"exchange-111"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらの通知を受けて、何か対応はされていますでしょうか。通知を受けてではなくても、情報提供など、何か取組がありましたら説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"こちらは、委員もおっしゃられているように、家族の意思決定というところがとても重要になってきます。何か相談を受けたりした際は、こういった通知等を基に、しっかりと相談に乗っていくということを心がけております。","id":"exchange-112"},{"speaker":"せお委員","kind":"質問・要望","question":"情報提供や相談など、ぜひ今後取り組んでいっていただきたいと要望いたします。そのような検討について、もし見解がおありでしたら、。","respondent":"石橋品川保健センター所長","answer":"保健センター、そういったところの関係機関が連携し、カンファレンスを開催しているということも実施しております。すごく難しいところではないかなとは思っているのですけれども、今後しっかりと支援できるような形で体制は整えていきたいとは考えております。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"あえてこの款でお伺いしたいのは、それぞれの料理教室の場所が衛生的に管理されているかどうかということをどのようにチェックされているか。食品衛生協会の方々による衛生管理に対する評価をどのようにされているのか、それぞれお伺いしたいと思います。","respondent":"勝亦健康課長、赤木生活衛生課長","answer":"導入の際に、そういったものを継続的にお伝えしていかないと、知られなければやっていないのと同じというような言葉があります。そういった意味では、強く広く継続的に周知を図ってまいりたいと考えています。実施指導員の方々がご自身のお店やお仲間の飲食店の衛生管理を自主的にしていただいているという趣旨で、実施指導員というのを設置していただいて。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"もし今この場で誰か倒れたときに、それぞれご確認ほしいと求めましたが、ぜひ周知をお願いしたいと思います。老舗のお店であったり、何か特典を与えるような視点での活用ができないかというのをぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"最後の点ですけれども、商店街に加盟しているところだけではなくて、区内店舗に目配せしながら、先ほど申し上げた商店街のデジタル商品券の多目的利用なども含めて、振興を図っていきたいと考えております。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそれぞれお願いしたいと思いますし、併せてお店の支援といった観点でも、今の助成金を活用してほしいと求めました。ぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"先に共通商品券なのですけれども、１０月３日に商品券との交換が始まりました。この点について、どこへ行ったらもらえるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"品川区商店街連合会、あるいは、郵便局でもお配りしております。そういうお話があったということで、配布をもう少し増やすようにということで、品川区商店街連合会にもお願いしてまいります。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"産業経済費のほうで、決算書４１７ページを見ますと、産業経済費の執行率は、令和５年度は８１.５％、令和６年度は９３.３％へと改善されました。令和６年度決算の総括として、今のことも含めて、区としてどのように捉えているかお聞きします。","respondent":"小林地域産業振興課長","answer":"切れ目のない経済支援ということで、令和５年度は執行せずに、令和６年度は執行率がより高くなっているというような事業もあります。例えば中小企業の支援事業の部分ですとか、こういった部分についての予算執行の比率というのが高くなっている１年間だったと考えています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"繰越明許の大きな影響もあったけれども、令和６年度もしっかりと事業を執行していただけたということです。１６０万円になってしまって、令和８年度に関してどのように展開していく予定か、お考えをお伺いします。","respondent":"小林地域産業振興課長","answer":"ただいま商店街の連携事業についてということで、ご指摘の事業につきましては、企業と商店街が組んで事業をするような取組のことだと認識しています。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"理念なき支援ではなく、区としてどういう状態を目指していくのかという結果を見据えた支援を効果的に構築することが私は大事だと思います。ご所見を伺います。","respondent":"小林地域産業振興課長","answer":"地域産業の中で課名の変更というのも、中小企業の事業環境の継続と人材確保の問題、この３つを３本柱で取り組んでいく必要があると考えています。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"産業振興マスタープランや産業振興ビジョン的なものが必要ではないかと思いますが、ご所見を伺います。長期基本計画や総合実施計画にはあるのですが、非常に大きなくくりしかないし、ページ数もすごく少ないので、その辺りはいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"先ほど委員もご指摘いただいたような長期基本計画ですとか総合実施計画の中で、私が先ほど申し上げたような具体的な事業も含めて実施しております。今後の区の考え方というのを考えていくとともに、施策の見直し、再構築もしっかりやっていきたいと考えています。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"現状について下支えをやるということ、あと中長期的な視点も持って、並行して準備をしておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"私からは３０７ページ、不妊治療等支援事業、３０６ページ、生活衛生費について伺います。この点について区の評価を伺います。","respondent":"勝亦健康課長","answer":"委員にご紹介いただいたとおり、１,０００件を予定してございましたけれども、令和６年度、執行が４７９件にとどまりました。年度途中の開始でありましたため、小まめに周知は行ったのですけれども、周知が行き届かなかったのかなという反省点はあります。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問","question":"そうしますと、今年度とか来年度は４７９件ではなくて、今度は目標を５００件に変えてしまったというところがあると思うのです。これは周知不足を解消することによって、より１,０００件に近づけるという考え方のほうがいいのではないかと思いますが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"おっしゃるとおりで、引き続き周知を行いまして、申請件数は月９５件程度に回復してきてあります。今回の定例会の中で、年間１,０００件を超える見込みになりましたので、今回補正予算を編成させていただいた次第です。","id":"exchange-124"},{"speaker":"松本委員","kind":"意見","question":"不妊治療の支援をどう行うかというところなのですけれども、２３区でほかの区を見ると、品川区はかなり特徴的な支援を行っていると思いますとの意見を述べました。","respondent":"勝亦健康課長","answer":"品川区につきましては、保険適用の部分の支援をしています。体外顕微授精といったものへの支援になるのですけれども、負担が１０万円ですとか、保険適用に上乗せの助成金を出している次第です。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問・要望","question":"この辺り、一番今後のよりよい事業になるのかなと思いますので、ぜひ実際に申請されている方にアンケートも行ってほしいと求めました。例えば先進の部分も使えるようにするとか、自由診療についても使えるようにするという考え方もあると思うのですが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"今委員がおっしゃったように、保険適用の部分の上乗せが、ニーズが大きいかなという判断ではありますけれども、医療の状況ですとか、出産に関する考え方はかなり柔軟に変わる部分があろうかと思いますので、ご利用者の声を聞きながら、しっかり検討してまいりたいと思います。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問・要望","question":"ここのところでもう一点、最後に、支援の申請が窓口か郵送かというところになっていて、書式を１回プリントアウトしないといけない。他区でも電子申請が可能なところもあるので、当区もここは電子申請をできるだけ早急に検討してほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"こちらの申請には添付書類が多いということで、電子申請にまだ至っておりませんけれども、デジタル化の流れは当然ありますので、積極的にこういったもののデジタル化も進めていきたいと考えています。","id":"exchange-127"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３０３ページの休日診療委託等について、あと３０９ページの成人歯科健診について伺いたいと思います。この休日診療の委託料の協議というのは、医師会とはどのようにされているのか伺いたいと思います。","respondent":"高山健康推進部次長","answer":"その後コロナが５類に移行いたしまして、その後も増額部分については、今現在も継続させていただいているところです。一時期ほどのお困りの状況ではないかと思いますが、今後も医師会のご要望なども伺いながら、適正な委託料の在り方について検討してまいります。","id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナは５類になり、私たちは普通に暮らしておりますけれども、医療業界、医療分野では、今コロナ感染が拡大しているという状況です。増額への前向きな議論をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"高山健康推進部次長","answer":"お話を伺う中では、来年度は１１年ぶりのシルバーウィークなどもあると伺っております。様々検討していくべき事項があるかと考えておりますので、引き続き医師会とも丁寧に協議を進めてまいります。","id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"歯の健康を守るきっかけとしての健診の拡充を求めてきて、２０１７年頃でしたか、４０歳からの健診が２０歳からに拡大されました。１２年前ぐらいに伺ったときは、１回の健診単価が４,５９０円ということだったのですけれども、１回の健診単価も分かれば説明するよう求めました。","respondent":"勝亦健康課長","answer":"毎年実施ですけれども、歯科健診の適切なタイミングを図るということで、そういったご意見があった旨、歯科医師会と相談してまいりたいと思います。健診費の単価ですけれども、現在委託単価は、クリーニング代を含めまして、７,４８９円ということで実施しています。","id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"受診率は１割弱から１割程度というのがずっと続いているわけですので、さらに早期発見、早期治療へとつなげてほしいと求めました。毎年の健診ということで検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"勝亦健康課長","answer":"歯科健診の受診率向上も、ほかのものと同様に重要です。１０歳刻みで実施の要領が定められていたと思いますけれども、必要性を今後、歯科医師会とともに検討していきたいと思います。","id":"exchange-131"},{"speaker":"こんの委員","kind":"確認","question":"私からは３０５ページ、３歳児健康診査、３２７ページ、中小企業活性化事業費、順不同で伺います。そこでまずお聞きしたいのは、この助成金を活用された事業所は何件ありましたか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"本日の段階で申請件数が６９件、交付決定額が４,４４０万円程度となっております。例えば、支援メニューの手厚いメニューをご案内したりといったところで、よりスムーズにご支援できるような対応を取らせていただいているところです。","id":"exchange-132"},{"speaker":"こんの委員","kind":"確認","question":"そこでお聞きしたいのですが、災害状況の確認に行った際、事業所の保険加入の状況はどんな状況だったでしょうか。加入状況などが分かりましたら、説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今回聞き取りをさせていただいたのは、製造業の中でもそういったところを中心に聞き取りをさせていただきました。実際に浸水の被害があったという会社は２社だったのですけれども、その２社については、保険に入っていますということは伺っているところです。","id":"exchange-133"},{"speaker":"こんの委員","kind":"意見","question":"今回１時間に１２０ミリの豪雨でしたので、今後は中小企業に特化した治水対策、水害対策の整備も必要ではないかと考えるわけですとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"防水板につきましては所管外で、実施しているところ所管と連携を図ってまいりたいと考えております。他自治体が水害に対してどのような施策を取っているのかということもヒアリングしながら、今後の区の施策展開に生かしてまいりたいと考えております。","id":"exchange-134"},{"speaker":"こんの委員","kind":"質問・要望","question":"最近３歳児の歯科健診のときに、歯並びが不安だという相談を受けていると歯科医師会の先生方からお聞きしております。かみ合わせには早くから注目していて、２０１２年から一般質問でも上げてきたわけですが、このことについてご見解を説明するよう求めました。","respondent":"飛田荏原保健センター所長","answer":"現在３歳児健診でも歯の咬合のことも聞いております。管理栄養士もいますので、そちらで食事指導も取り入れて、早いうちから口腔内機能の支援を行いたいと考えております。","id":"exchange-135"},{"speaker":"藤原委員","kind":"質問","question":"今もまだ５０年、ずっと５０年と言って、中央防波堤の処分場がどんどん広がっていってしまっていると考えてよろしいのでしょうか。何年後に聞いても５０年とずっと言い続けるのか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"ちなみに私も小学生のとき、５０年前に習ったときには、あと５０年と言われました。そういった処理も減っているということで、トータルで見ると、５０年という数字がずっと続いているという状況なのだろうと考えているところです。","id":"exchange-136"},{"speaker":"藤原委員","kind":"質問・要望","question":"こうやって資源ごみに協力しているのだという気持ちを区民の方に分かっていただくということが大事だと私は思うのですが、いかがでしょうか。いかがか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"ただいま委員から、ボリューム減量に向けた取組ということで、ご指摘いただいた点は全て重要なポイントだと私どもも認識しています。","id":"exchange-137"},{"speaker":"藤原委員","kind":"意見","question":"環境課長、また私の記憶違いでなければ、花壇に生ごみを入れるとより一層育つというような話でテレビに出ていましたよね。その辺についてちょっと説明していただけますかとの意見を述べました。","respondent":"中西環境課長","answer":"テレビ東京でＳＤＧｓについて１週間特集をするという中で、品川区とエコルとごしを特集していただいて、取材を受けさせていただいたものです。","id":"exchange-138"},{"speaker":"藤原委員","kind":"提案","question":"それで提案なのですけれども、清掃環境部というのをもう独立してつくられたらいかがですか。担当は答えにくいかもしれないのですけれども、どうか前向きな答弁をいただけますかとの意見を述べました。","respondent":"中西環境課長","answer":"環境課と清掃事務所でかなり連携を密にしながら、今もやらせていただいておりますので、まずはこの形で前に進めていければなと考えています。組織改正に関しましては、また全体の中で考えてまいりたいと思います。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問","question":"楽しみにしております。次が２９９ページ、これは毎回健康課長に伺うのですけれども、出会いの湯に行ってくれたことはありますか。","respondent":"勝亦健康課長","answer":"毎週木曜日の午後に行っている事業で、私は出会いの湯のプログラムをやっている場にはまだ行ってございません。ただ、所管の課長ということで、区内の銭湯については、自腹でほとんど回っているところです。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問","question":"いろいろな方のご意見を直接伺えて、銭湯への助成、また行く方への助成金は今５５０円です。私はまだ前期高齢者になっていないから５５０円、でもここはもったいないので、私のテーマとしてまた次に伺っていきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"まつざわ委員","kind":"質問","question":"中小企業事業融資あっせんについて伺います。令和６年の融資実績について、コロナ禍の時期と比較して、件数や金額、そして業種にどのような変化、また傾向が見られたのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"件数が４,６６１件、５７５億円でしたので、額としても約３割に落ち着いてきたといったところです。約２０％を占めておりまして、どれも同じ１０％前後で推移しておりまして、毎年同じような傾向となっているところです。","id":"exchange-142"},{"speaker":"まつざわ委員","kind":"意見","question":"多額の公費が投入されています。そこで本制度を利用した中小企業が、その後実際に経営を維持、また発展させることができたのか、区の見解を説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今、変更は５０件程度になっているところでございまして、この件数を景気動向の一つの指標として注視しています。もう一つ発展しているところという点では、今年度から開始したチャレンジ支援資金は、既に２件のお申込みがございました。","id":"exchange-143"},{"speaker":"まつざわ委員","kind":"意見","question":"新たなチャレンジ支援資金が２件ということですね。この資金というのが、本当に支援を必要とする事業者に届いているのか、その実態について説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"こちらについては、令和５年度、令和６年度と、緊急資金として実施させていただいたところです。令和５年度が３６６件に対して、令和６年度は２０３件と推移しておりましたので、一定のニーズには応えられたものと考えているところです。","id":"exchange-144"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"次に、創業・スタートアップ等支援経費について伺います。この事業の詳細についても説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"これまで区の創業支援では、そういったことを今後も区としては支援、期待していきたいと考えています。全国の５自治体と連携しまして、より広域的にネットワークを形成し、皆様の事業成長につなげていくといったところで実施させていただいたところです。","id":"exchange-145"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"先ほど言いました約１０億円の融資あっせん、約５億円のスタートアップ支援、本来ならこれらは密接に連携するべきだと私は思っています。情報共有、創業者への積極的な融資制度の案内というのが行われているのか説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"品川区の各創業支援施設で区の融資や助成金の説明会を行うとともに。それから、各創業支援センターに金融機関が出向いてくださって、資金繰りのご相談、いわゆる資金調達相談会というものも実施しています。","id":"exchange-146"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"最後に総括的な要望です。企業の事業成長というのが加速すると考えますので、こういった総合的な支援をこれから先も引き続きしっかりやってほしいと求めました。","respondent":"石田（秀）委員長","answer":"以上をもちまして、本日予定の審査は全て終了いたしました。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/239858?Template=document&Id=7257#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":116249,"voices":317}},{"id":"r07-20251007-4","meetingId":"r07-c-settlement","date":"2025年10月7日","dateIso":"2025-10-07","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"私からは、３３５ページの地域交通検討経費と交通安全啓発費、３７１ページの防災訓練経費についてお伺いします。令和５年度の決算特別委員会では、他自治体での取組等について話を伺い、区内でも地域の実情に即した利用者の利便性を高める取組を要望しました。","respondent":"櫻木地域交通政策課長","answer":"件数というよりは割合になりますが、基本的には高齢者のご利用の方が、おおむね６０歳以上で６割から７割を占めております。障害者の方については７から８％程度という状況です。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問・要望","question":"そこでお伺いします。残り６か月を残し、大崎地区へ展開を決定するに至った経緯を説明するよう求めました。","respondent":"櫻木地域交通政策課長","answer":"大崎地区の交通課題の検討につきましては、従前より、コミュニティバスとデマンド等、幅広く検討してきたところです。７月に、荏原地区でのＡＩオンデマンド交通の検討・実施を踏まえまして、大崎地区の実施の検討を進めているところです。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"次に、交通安全啓発費についてお伺いします。２０２６年４月１日施行の改正道路交通法では交通反則通告制度が導入され、警察による自転車の違反取締りが強化されますが、内容を説明するよう求めました。","respondent":"山下交通安全担当課長","answer":"来年４月１日から実施されます交通反則通告制度ですけれども、こちらは、交通事故を減らすための趣旨が前提となっております。基本的には、交通違反の取締りに関する考え方というのは、変更はございません。","id":"exchange-003"},{"speaker":"えのした委員","kind":"確認","question":"「もう、これは何とかならないのですか」と切実です。区の取組もお伺いいたします。","respondent":"山下交通安全担当課長","answer":"昨年、陳情により現場で対応しました、例えば巻き看板や立て看板といったものにつきましては、１００件ほど対応を行っているところです。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問・要望","question":"こちらは多くのご相談とご要望がありましたのが、訪問時にサービス提供中に放置自転車扱いされて撤去されるケースがあると聞いております。区としては実態として苦情や相談などを受けているのかも含めて、ご見解をお伺いします。","respondent":"山下交通安全担当課長","answer":"原則、放置禁止区域内に放置されている自転車につきましては、即時撤去の対象となっておるものです。区におきましても、当日２時間以内であれば無料という制度を行っておりますので、そちらを活用して放置自転車防止に協力していただければと思います。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問・要望","question":"そこでお伺いします。想定外に対応できなかったという事実を示しましたが、区はこの教訓をどのように受け止めているのか、まずご認識をお伺いします。","respondent":"羽鳥防災課長","answer":"私からは、１点目のご質問に回答します。防災ハンドブックなども含めました、ハザードマップの周知とともに、そういった浸水被害についての周知・啓発に努めてまいりたいと考えております。","id":"exchange-006"},{"speaker":"えのした委員","kind":"確認","question":"上階へ避難する垂直避難訓練や、排水溝の状況を確認し、土のうを積むといった具体的な行動訓練を行うことが効果的です。現実の脅威に基づいた訓練こそが、区民の命を守るには有効だと考えますが、区のご見解をお願いします。","respondent":"星災害対策担当課長","answer":"今のご指摘のとおり、水害に対する訓練というのは非常に重要だと考えています。防災課としても前向きに進めていきたいと考えているところです。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"３４１ページ、点字ブロックを活用した音声による移動支援検討についてお伺いいたします。品川区内での設置状況と、令和６年度における取組実績についてお伺いいたします。","respondent":"森道路課長","answer":"令和６年度につきましては、下神明駅から、しながわ中央公園の脇を通りまして、庁舎の中のエレベーターホールといったところを中心に設置しています。令和６年度の末に、詳しく使い方をご説明し、「ここにありますよ」ということで実際に音声も聞いていただきました。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"質問","question":"そういった視覚障害者の方々から寄せられているニーズや課題について、併せてお伺いいたします。ネットを検索しますと、スマートフォンを肩に固定するようなやり方もあるようですが、安全な使用についてはどのようなお考えか、説明するよう求めました。","respondent":"森道路課長","answer":"昔の情景を少し見ていただけるのかなとは思いますけれども、そういったニーズを酌みながら進めていきたいと思っています。こういった体験会をまた行えれば良いと思いますけれども、まずはしっかりと周知させていただきながら、声を聞いて進めていければと考えています。","id":"exchange-009"},{"speaker":"おぎの委員","kind":"確認","question":"災害時には、視覚障害者が避難経路を確認できないことが多く、音声案内の仕組みが非常に役に立つという可能性があります。品川区としても、防災拠点や避難所への誘導に、この音声案内技術を活用する検討といったものがあるのかも併せてお伺いいたします。","respondent":"森道路課長","answer":"防災につきましては、まだ検討段階ではあるのですけれども、実際にメーカーから、災害時モードの話も伺っております。そういったものも区と一緒に支援させていただきながら、整備できていければと考えています。","id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして公園・児童遊園維持管理費から、公園における花火の使用についてお伺いいたします。この取組をなぜ始めたのか、背景をお伺いします。","respondent":"大友公園課長","answer":"昨年度まで公園での花火を禁止していたですけれども、今年度一部の公園で使用可能とした経緯といたしましては、公園で花火ができるようにしてもらいたいという声を多数頂いていたことと、あと子どもたちに花火を楽しんでもらいたいという思いから、試行実施に至ったものです。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問","question":"公園の管理者の有無ということでしたが、実際、公園の管理者の見回り等はあったのでしょうか。行ってみて見えてきた課題と今後の予定を説明するよう求めました。","respondent":"大友公園課長","answer":"実際に試行実施をした際の利用状況と結果なのですけれども、昨年度実施していました、しながわ花海道を除きまして、利用者数を測定したところです。公園における花火の試行実施については、おおむね好評で、反対の意見は少数でした。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３６３ページの住宅・建築物耐震化支援事業に関連して耐震シェルターと、３４５ページの浸水対策事業について伺います。今年度から、また助成金についても６５万円と大幅な増額となり、現在までの相談件数や実績についてお聞きできればと思います。","respondent":"森建築課長","answer":"「品川シェルター」のご質問ですけれども、現在までの実績は、令和４年度に１件、それまで全部、助成開始から含めますと２２件です。相談につきましては、今年度はまだ一件もない状況です。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"助成の金額の増額と所得制限撤廃、大きく増額されていますので、建築士事務所協議会の団体からも要望の声が届いております。改めて今後の見通しについてもお聞きできればと思います。","respondent":"森建築課長","answer":"伸びていただきたいと考えていますけれども、６畳の広さまでが制限であったり、それで伸び悩んでいる状況もあるのかなとは思ってあります。ただ、システムは非常によいものですので、しっかりアピールしてまいりたいと考えております。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"必要性が高く相談しても、最終的に導入するに至っていない現状もお聞きしています。最終的には設置件数の増加に結びつく見せ方について必要かと思われますが、この点について改めてお聞きできればと思います。","respondent":"森建築課長","answer":"委員ご指摘のとおり、皆様にＰＲできるように、様々検討してまいりたいと考えております。","id":"exchange-015"},{"speaker":"ゆきた委員","kind":"質問","question":"木質耐震シェルター７０Ｋも「品川シェルター」と同様に、最短１日で設置可能であり、また費用も「品川シェルター」と同程度の費用です。選択肢の幅を増やす、広げていくということも必要だと思われますが、ここについて区の見解をお聞きできればと思います。","respondent":"森建築課長","answer":"今年度は「品川シェルター」の拡充を行いました。状況によりましては、他の耐震シェルターについて助成対象にするかどうか、しっかり検討してまいりたいと考えております。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"提案","question":"私の前任である、２０１５年度に国や都の補助制度が打ち切られたことにより品川区で助成が終了している耐震ベッドの再実施について提案したところとの意見を述べました。","respondent":"森建築課長","answer":"そのことは認識しています。助成対象にするかどうか、リースでやるという方法もあるようなのですけれども、様々検討してまいりたいと思います。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"続いて、浸水対策事業について伺います。ここ数年の防水板設置工事助成の実績件数と、今回の風水害後の防災板の設置助成の問合せ数や申請数の変化などをお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"９月１１日の豪雨以降につきましては、現時点で５０件を超える問合せが来ているところです。まだ少数ですが、既に申請を頂いた方もいらっしゃるという状況です。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"確認","question":"ここ数年で数件のところから数十件と、問合せ数が大幅に増加しているということを確認させていただきました。迅速な運搬・設置が重労働となる土のうに代わる現実的な水防資機材として早急に普及していくべきと考えますが、区の見解をお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"現在、区では、防水板の設置助成の対象といたしまして、浸水に耐える材質で、取り外し、また移動が可能なものとしています。委員がおっしゃるマグネットタイプのようなものもありますので、そういったところも助成できるのかなと考えています。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"枚数を増やすことで、１０ｍにも距離を延長して設置できますが、１０ｍでもたった１人で５分で設置できる性能の有効性があります。従来の設置工事を伴う防水板設置助成とは別に、緊急で創設すべきと考えますが、区の見解をお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"先ほど委員からもご指摘がありましたように、ＪＩＳ規格で定める一定の止水性能を満たすものでございましたら、現在でも助成対象となっております。こうしたものを含めて、ぜひご相談いただければと考えているところです。","id":"exchange-020"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ、この簡易止水板の周知と助成の創設について検討してほしいと求めました。地下室・半地下構造を持つ住宅、優先的な支援対象として考えるべきと考えますが、区のお考えをお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"委員ご指摘のとおり、今回の豪雨では区内全域で大きな被害が出たということもありますし、ご指摘のような対象の方もいらっしゃいますので、今後、区民の方により使いやすい制度となるよう、検討を進めてまいります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"３点伺いたいのですが、バス停の設置が限られている」という状況ではないと思うのですが、いかがでしょうか。３点目は、どのようにこれを解消するお考えなのか、伺います。","respondent":"櫻木地域交通政策課長","answer":"１点目、その意味で、道路幅も含めて見通しが悪いという状況だと認識しております。上大崎につきましては、交通圏域外という状況ですので、引き続き、どのようなことができるか研究してまいりたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"沿線の住民からは、大崎ルートの早期実施を求める１,１７４人分の署名が公共交通会議宛てに提出され、１０日の会議でも報告されると伺っています。同意状況、仮同意書の数などについても、土地所有者、借地権者、区分所有者、それぞれについて伺います。","respondent":"中道都市開発課長","answer":"現在の状況ですけれども、こちらの地区は平成２６年度に準備組合が設立されて、地域の方でまちづくりの検討が進められてきているです。都市計画決定なのですけれども、今は地域の方々が検討を進めているというところで、今年度の都市計画決定の話は聞いていない状況です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"確認","question":"足しげく準備組合との相談には行っていると伺っていますけれども、二人三脚で進めている再開発事業で、区の考えをお聞きします。こんなことが行われている状況で、品川区が都市計画手続に入ることなど、あり得ないと思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"こちらのまちづくり方針といたしましては、当該地区につきましては、いわゆる後ろにありますＦ南地区の再開発のほうにも移り住むことができると。準備組合から、時期を定めて、選択をどういうふうにするのかといったお答えを頂きたいと聞いております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"隣のマンションに行くというのも、１つの選択肢が増えてよかったみたいな、そういう立場でいいのでしょうか。私は、その方の住み続けたいという居住権をしっかり守っていく立場に立つべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"マンションの高層階の居住者や、低層階住宅にお住まいの場合でも、高層の建物が壁となって聞きにくくなってしまうのでしょうか。そういったことへの対策や対応について、区の取組を伺います。","respondent":"遠藤防災体制整備担当課長","answer":"平成２４年から防災ラジオを導入いたしまして、室内でも防災行政無線の音声を聞くことができるような状況になっているです。防災行政無線と連携しまして、文字情報でも、防災行政無線の情報を提供させていただいているというような状況です。","id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"ホームページやＳＮＳなどによる文字情報というのは私も確認しているところです。既存の仕組みを活かすことで伝達の確実性を高めることにつながると考えますが、防災課としてご所見を伺いたいと思います。","respondent":"羽鳥防災課長","answer":"一方で、そういった緊急情報につきましては、より正確に、迅速に、全ての区民の方に同じ情報を届けるということも重要であると認識しています。区といたしましては、同じ情報を正確に、適時適切にお届けするというところに努めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"災害時はどのようなオペレーションをされるのか、災害協定の内容を伺います。区有地へのポート設置で、敷地使用料の収入はないかということを確認したいと求めました。","respondent":"櫻木地域交通政策課長、羽鳥防災課長","answer":"区有地の例としましては、まずは品川区役所の中にシェアサイクルポートが設置されております。収入につきましては、区の事業ということで、事業者から歳入はございません。事前に事業者専用のＩＣカードというものを、現状、５１枚を配付いただいております。区役所や各地域センター、保健センターなどで、そういったＩＣカードを配備して、災害時に利用できる体制を取ってあります。","id":"exchange-028"},{"speaker":"せらく委員","kind":"確認","question":"敷地使用料のようなかたちで収入が得られるものと認識していますが、区の事業ということで、区には歳入がないということです。公有地にも限らず、ＩＣカードを持っている人が利用できるということなのか、確認したいと求めました。","respondent":"羽鳥防災課長","answer":"災害時の利用についてです。委員がおっしゃられたとおり、民有地につきましても、こちらは区の職員が事業者用のＩＣカードを利用することで、無料で活用できるという状況です。","id":"exchange-029"},{"speaker":"せらく委員","kind":"確認","question":"確認させていただきました。設置場所の選定基準や地域住民との合意形成のプロセスについて、現状の課題認識を伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"委員ご指摘のとおり、非常にバランスが難しいところではあります。近隣の公園等に、地域の方と話し合った上で設置したようなケースもあります。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"促進していただきたいと、やはり放置自転車の対策というところで、地域のお声を聞きながら設置したということです。ただ、規模が小さな公園については、公園内に設置されているポートを再検討していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"具体的なご要望等、ご相談いただければ、状況を見て、最適な手段は取れるかと考えています。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"そこでお伺いいたしますが、復興の主体は誰で、誰のための政策だと、区はお考えでしょうか。区のご見解をお伺いいたします。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"引き続き、区民お一人お一人に寄り添った支援を継続してまいりたいと考えています。区民と事業者、行政が連携して復興に取り組むと認識しています。私からは、２つ目の質問のうち、被災者の意識に関する考え方についてお答えいたします。そうした取組の中で、委員がおっしゃるとおり、被災者が前向きに避難生活を送ることができるよう、引き続き検討を進めてまいります。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"災害関連死のこともお聞きしたかったのですけれども、時間がありませんので次の内容を伺います。私は今年７月、全国若手議員の会で石川県珠洲市を視察しまして、能登半島地震と奥能登豪雨災害の現状についてお話を伺いました。","respondent":"遠藤防災体制整備担当課長","answer":"このほかにアレルギー対応の粉ミルクも同量確保しているほか、ある程度余裕を持った備蓄体制を構築しております。そのため、例えばお盆やお正月といった災害時の想定を超えた避難者となった場合であっても、一定の対応はできるものと考えております。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問","question":"私からは、３７３ページの防災情報配信経費、３７１ページの防災訓練経費、防災普及教育費について伺います。防災情報配信経費に関連して、今年４月から導入した防災ポータルと防災アプリについて伺います。","respondent":"羽鳥防災課長","answer":"現在のダウンロード数ですけれども、２,５００ダウンロードです。目標といたしましては、今年度中に３,０００ダウンロード、令和１０年度までに１万ダウンロードを目標としています。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問・要望","question":"いかがでしょうか。それぞれご見解を伺います。","respondent":"羽鳥防災課長、横田デジタル推進課長","answer":"防災アプリの登録者にポイントを付与するキャンペーンというものが実施されているというところは、他自治体の事例として把握しています。いわゆる総合型アプリ、スーパーアプリにつきましては、技術的課題や費用対効果の観点から慎重に調査・研究をしていく必要があると考えております。","id":"exchange-035"},{"speaker":"山本委員","kind":"確認","question":"今年も９月２８日に西大井広場公園で開催された大井第三地区の総合防災訓練に伺いました。気づかなかったことを反省しているのですけれども、緊急時に必要な情報が提供されていないと困りますので、状況を確認したいと求めました。","respondent":"羽鳥防災課長","answer":"一部のメディアと自動連携はできているものの、現状、防災ポータルアプリとは連携できていないという状況です。現状そういった対応は難しいという状況ではございましたが、今後、事業者と協議を進めてまいりたいと考えています。","id":"exchange-036"},{"speaker":"山本委員","kind":"質問・要望","question":"短時間集中豪雨に耐え得る治水工事計画の推進や、今回の災害データを活かした水害対策・復旧対策のアップデートを要望して、次の質問に進みます。次に、防災普及教育費に関連して、携帯トイレの全戸配布とエレベーター用防災チェアの無料配布について伺います。","respondent":"羽鳥防災課長","answer":"エレベーターの閉じ込め対策を支援するということを通しまして、理事会の方が災害への備えを考えるきっかけづくりとして配布しているものです。評価といたしましては、さらなる周知・啓発が必要であると認識しています。","id":"exchange-037"},{"speaker":"山本委員","kind":"質問・要望","question":"こちらは効果的なフォローアップの実施を要望しておりまして、併せて啓発を行うことができると思いますので、こちらをご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"都議会公明党は、この地域の整備効果を早期に発揮させる工夫を着実に進めていくべきだと、都の対応を求めました。今後、大雨が降った場合に備えて早急の対応が必要と考えますが、見解を伺います。","respondent":"羽鳥防災課長、関根河川下水道課長","answer":"現在も、９月１１日の被害については丁目ごとにまとめているところです。今後、防災地図のリニューアルの際には、その地域をお示しできるような対応を検討してまいりたいと考えています。今後の予定ですが、整備効果を早期に発揮させる工夫を行うことが重要であるという認識の下、東京都下水道局から聞いてあります。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"橋のあるところの跳ね上がり対策についてはどうお考えか、改めてお聞きいたします。これに対応し得る対策が求められておりますので、強化をお願いしたいと思います。","respondent":"関根河川下水道課長","answer":"このため、橋のたもとにおきましては、具体的な設置場所や方法等を検討の上、溢水防止板の高さを上げて設置してまいります。それに対して、やはりインフラ整備だけではなく、先ほど申しましたような自助等も含めた備えをしていただくということが必要かなと認識しています。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"対象の拡大を求めますが、見解を伺います。この防災士の方を集める取組を、品川区が主導してやってほしいと求めましたが、見解を伺います。","respondent":"羽鳥防災課長","answer":"今年度、４月１日から募集を開始いたしまして、途中、追加募集もありましたが、１０名の枠のところ、実績としては６名という状況です。そういった声も踏まえまして、今後、対象の拡大については検討を進めてまいりたいと考えています。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３６３ページ、ゆきた委員からも質問がありましたけれども、「品川シェルター」についてお尋ねします。「品川シェルター」は２件で１００万円ということなのですけれども、決算書には、その辺についてもお尋ねさせてほしいと求めました。","respondent":"森建築課長","answer":"昨年度助成件数はゼロでございましたので、決算がない状態です。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"何というのですか、６畳という決まった中でやっていくというのは、いろいろとご苦労があるかと思うのです。この講習会というのは継続的にやっておられることなのか尋ねました。","respondent":"森建築課長","answer":"ある程度、技術者が増えてまいりましたので、今は継続して行っていないはずです。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"工務店の親方、社長に対してやっていくというのが、一番、施主と密接しているので、これは要望なのですけれども、ぜひやってほしいと求めました。これからの啓発・広報活動について、より強く強化してもらいたいのですけれども、その辺についてお伺いします。","respondent":"森建築課長","answer":"委員ご案内のとおり、様々な機会を捉えまして、「品川シェルター」についてしっかりＰＲしていきたいと考えています。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて、３４５ページ、治水対策推進助成事業についてお伺いします。それで、新たな取組が追加されたということなのですけれども、新たな取組というのを教えてほしいと求めました。","respondent":"関根河川下水道課長","answer":"委員ご指摘のとおり、本年９月に品川区総合治水対策推進計画を改定させていただきました。具体的な内容ですが、公共用地におけるグリーンインフラの整備促進、また機運醸成に向けた広報の充実等を予定しております。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこで、雨水利用タンク設置助成等について、お尋ねします。日本語として「ウスイ」が正しいと私は思うのですけれども、その辺はいかがか尋ねました。","respondent":"関根河川下水道課長","answer":"私ども助成制度のご案内のチラシの中には、振り仮名として「ウスイ」利用タンクと振り仮名を振らせていただいております。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認させていただきました。それで、助成制度の積極的な広報が、この簡略化によってできると思うのですけれども、その辺について尋ねました。","respondent":"関根河川下水道課長","answer":"今後につきましては、例えば動画を活用して、分かりやすく広報していくといったことも検討してまいりたいと考えています。改めて確認いたしまして、必要な書類のみを提出いただくといった形で再度精査したいと考えています。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"助成も分かるのですが、いいことだとは分かっているのですけれども、防水板というのは、なかなか、どうなのかなと私は思っているのです。","respondent":"関根河川下水道課長","answer":"防災板にも様々なタイプがございまして、例えば簡易的なものですと、先ほども少しありましたが、マグネットでぺたっと貼るようなタイプのもの等もありますので、区民の方にご相談いただければ、そういったものを含めてご案内できるかと考えております。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問","question":"伺いたいのですけれども、近隣を軒並み調査するということで伺ったのですけれども、お聞かせください。実態をつかまないと対策にもつながらないと思うので、実態をつかむというところではどうされているのか伺いたいと思います。","respondent":"森道路課長","answer":"９月１１日の雨につきましては、防災課以外の課で構成しております土木部というところで中心になって実態調査等をさせていただきました。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"インフラ・ハード面の治水対策というのが求められると思うのですけれども、これはどういうふうに検討されるのかということを伺いたいと思います。","respondent":"関根河川下水道課長","answer":"考え方といたしましては、東京都豪雨対策基本方針というものがございまして、インフラ整備等を進めていくという考え方になってあります。立会川周辺での下水道工事が進められているところでございまして、現在よりも浸水被害は軽減されていくものと認識しているものです。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区が一番つかんでいるわけですから、ぜひ品川区の実態を伝えながら具体的なところも要望するという形でお願いしたいと思っています。そういう点では、ぜひ見舞金については増額していただきたいということで要望もしたいのですけれども、いかがか尋ねました。","respondent":"関根河川下水道課長、星災害対策担当課長","answer":"私からは、下水の構造を調べる資料提供というところにお答えします。インターネットのどこに載っているかというところは、ご案内できるかと考えております。私からは見舞金についてお答えします。","id":"exchange-051"},{"speaker":"せお委員","kind":"提案","question":"令和４年度の基本実施設計のときに私は気づかず、今後に向けて提案します。検討されたなら、その検討結果はどうだったのか、説明するよう求めました。","respondent":"高梨都市計画課長","answer":"当該施設につきましては、開発環境指導要綱の協議を都市計画課で受け付けておりますので、私から回答します。施設建設所管課で内部への移設について検討させていただいたところ、中には下水道や電気等の引込みの線があって、報告を受けているところです。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問・要望","question":"緑化活動の目的や割合というのはもちろん理解していますし、重要なのですけれども、場所の検討はされたのでしょうか。なければ今後、議論ができる場を構築していただきたいのですが、見解を伺います。","respondent":"高梨都市計画課長","answer":"バス停の前に、植栽をまたいでという部分もあろうかと思いますけれども、そちらを確保するというところで計画していただいているところです。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問・要望","question":"施設整備の観点から、地域課題等がある場合には、ぜひ十分な議論を行ってから進めていただきたいと要望します。次に、住環境改善促進事業から、主に住宅改善工事助成事業ですけれども、令和６年度の実績と推移、増減のところを教えてほしいと求めました。","respondent":"川原住宅課長","answer":"助成額で申し上げますと、助成額は５,５００万円余となっています。〔同日後刻に「昨年度２９７件でございました」と答弁訂正あり〕 今年度の推移としては、金額も含めて、動いているところです。","id":"exchange-054"},{"speaker":"せお委員","kind":"確認","question":"さらに現在、問合せには一般職の方が対応していると伺っています。住宅改善全般を、プロに気軽に電話相談できる仕組みも欲しいのですが、こちらの見解を伺います。","respondent":"川原住宅課長","answer":"電話等もない状態ですが、手法については引き続き検討してまいりたいと思います。そして、パンフレット等については、今後の検討として、各課のパンフレット等も見ていきたいと考えております。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"最後に要望だけします。昨日お話しした、子どもの事故予防のための補助錠は、集合住宅の方にも届くような補助を、各課連携してぜひ検討していただきたいなと要望します。","respondent":"川原住宅課長","answer":"すくすく制度については、住宅課のマンション支援のホームページにも公開しています。住まいの冊子は今、全体にまとめたもののご用意があります。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"実効性を高めるために、事業者とよく協議して、運用計画の作成と訓練の実施を求めますが、いかがでしょうか。この「重要な要素」とは、品川区の認識でよいのか伺います。","respondent":"遠藤防災体制整備担当課長","answer":"平時から連携を深め、運用要領の整備、キッチンカーの防災訓練等への派遣といったことも検討してまいります。委員からご指摘がありましたとおり、区としても、災害時の温かい食事の提供は、避難生活における重要な要素と認識しています。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"重要な要素ということで、実効性を高める様々な計画を進めていきたいということでした。１日何食分の提供を１台のキッチンカーに求めるのか、また１時間の間に何食分のペースということになるのか、現状はいかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"キッチンカー団体と区がニーズを把握して調整し、派遣するといった体制について、現在検討を進めております。区としては、各避難所に対応した安全な食事の供給体制を検討していきながら、災害時に温かくおいしい食事を提供できるように取り組んでまいります。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうメニューにするのか、どういうふうに検討するのか、具体的に協議して決めておいていただきたいと要望したいと思います。給食室の調味料や配膳用品を使うことができるのか、食材や飲料水の搬入はどこの指示で何日目から始まるのか、伺いたいと思います。","respondent":"遠藤防災体制整備担当課長","answer":"国や都、協定先の事業者などと調整しまして、調味料や使い捨ての食器などを調達できるように検討してまいります。水につきましては、区内５０か所の区民避難所に応急給水栓がありますので、こちらは避難所開設後に速やかに活用していただけます。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"基本的なことを伺いましたけれども、７２時間後に学校避難所で炊き出しをするというのは、そのようには進まないと思います。１点、例えば一定の食材を避難所に搬入するということはできないのか、その点を伺いたいと思います。","respondent":"遠藤防災体制整備担当課長","answer":"災害対策本部の中にあります指令情報部の物資調達課が物資を調達して、各区民避難所に輸送するといった指示をしていくことを計画しています。避難所運営組織の中で物資供給部という部門がございまして、こちらの部長がリーダーの代わりとなるということを考えてあります。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問","question":"初めに、３５７ページの公園・児童遊園維持管理費について伺います。以前、利用者や周辺の方々にご意見を伺って決めていくという説明があったのですが、その後の進捗状況について、併せて伺います。","respondent":"大友公園課長","answer":"再開するか、公園課としての必要性を検討していたところではありますけれども、公共の場における喫煙に関する規制が強化されたところです。そのため、区民公園内の喫煙所につきましては、現在、地域活動課と、その必要性について慎重に検討しています。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問・要望","question":"本区内では、公園・児童遊園から喫煙所を撤去した後、今まで喫煙者としてそこをご利用されていた方について伺います。今後、そうした方々に対しての注意というか監視はどのように行われる予定か尋ねました。","respondent":"大友公園課長","answer":"紙巻きたばこも吸えるというところの整備を、地域課題の解決のために実施し、コンテナ型の喫煙所を整備するという予定です。昼休みの時間帯などを指定して声を頂く機会が多いところがありますので、巡回の中で声かけをさせていただいているというところの現状があります。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"続きまして、３５９ページのおもてなしトイレの整備と、３６１ページの公衆便所の整備について伺いたいと思います。初めに、おもてなしトイレから伺いたいと思います。","respondent":"大友公園課長","answer":"対象公園１２９か所を対象といたしまして、令和７年度末になりますけれども、１１５か所を完了予定で進めているところです。こちらは令和６年度の予算の中でお伝えさせていただきました８か所の設計工事を実施したです。","id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"その中で何が言いたいかというと、おもてなしトイレと公衆便所の違いというのは、どういうものなのかということで、質問を持っていきたかったのです。おもてなしトイレと公衆便所の違いはどういったところなのかをお知らせほしいと求めました。","respondent":"大友公園課長","answer":"区内の公衆便所や公園便所、児童遊園の便所を、国内外の観光客や高齢者も安心して使えるようにという目的で洋便器化を図っているものです。公衆便所、全てを洋便器化することで、おもてなしトイレという形で事業を進めているところです。","id":"exchange-064"},{"speaker":"松永委員","kind":"提案","question":"公衆便所という言い方を公衆トイレに変えてはどうかと提案したのですが、もし本区として、品川区版の何か名称をつくってみてはいかがか尋ねました。","respondent":"大友公園課長","answer":"おもてなしトイレの整備におきましては、公衆便所、また、公園便所を全て含んで包括しているものですので、こちらは一緒に事業を分けず、進めていきたいと考えているところです。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"品川区のマンション防災対策の現状と課題について伺います。これらの事業の実施状況と、現時点での区内マンション防災における最も大きな課題というのは、どのようなことだと認識しておられるか尋ねました。","respondent":"羽鳥防災課長","answer":"エレベーター用防災チェアにつきましては、先ほどもご説明いたしましたとおりです。そのため、今年度からは、支援の内容を３段階に分けて実施しているという状況です。","id":"exchange-066"},{"speaker":"つる委員","kind":"提案","question":"３３９ページ、街路樹等維持管理委託、３６３ページ、私道整備事業について伺っていきます。当時、実りの季節は食料にするのだという提案を受けて、畿内７道諸国は駅路の両辺にあまねく果樹を植えるべきことということでとの意見を述べました。","respondent":"森道路課長","answer":"街路樹の桜の本数ですけれども、１,４９１本、割合でいきますと全体の３６.７％が桜です。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"駅から桜が見えるようにしたいということをずっと求めているわけでありますけれども、ぜひ引き続き、桜に限らずですが。憩いなどという視点も含めて、将来伸びたときにそういうふうになっていくのだというような工夫についても、併せて見解を説明するよう求めました。","respondent":"大友公園課長、森道路課長","answer":"こちらは緑の実態調査ということで、５年に１回調査を実施しているところでございまして、ちょうど今年度、実施したところです。おやすみ石の設置については、やはり道路上の必要な幅員を確保できているということが１つの目安です。今年度実施したとお伝えさせていただきましたが、昨年度の実施でございました。訂正します。","id":"exchange-068"},{"speaker":"つる委員","kind":"提案","question":"９月１１日に限らず、これまで品川区を襲った大雨・豪雨等による対応という視点で伺いたいと思います。これについては、２０２４年の予算委員会で塚本委員から要件の緩和などを提案させていただいていますが、改めてここについて伺いたいと思いますとの意見を述べました。","respondent":"森建築課長","answer":"今、私道整備助成といたしましては、舗装や側溝の部分的な補修については対応できない状況になっております。部分的に崩壊した場合等につきましては、基本的には持ち主の方が対応するということになります。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問・要望","question":"各区の状況は特に伺っていないです。ほかがどうだからということではなくて、品川区民の命を守るために、しっかりこの辺の確認については、積極的に検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"３４５ページの雨水利用タンク設置助成等（グリーンインフラ）と、それから３３５ページの交通安全啓発事業、自転車のルールの変更について伺います。","respondent":"関根河川下水道課長","answer":"現在、例えば１０月に実施されております住宅まつりにおいて配布したり、２月にエコルとごしで助成制度の展示を実施したりしておりますので。この３つを記載しています。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"ないようでしたら、ぜひ助成を検討してほしいと求めました。残念ながらそういう視点での啓発は、学校ではあまり見当たらないので、その点についても説明するよう求めました。","respondent":"関根河川下水道課長","answer":"河川下水道課で行っております雨水利用タンクの設置助成につきましては、区内に雨水利用タンクを設置する場合と規定していますので。エコルとごしで連携した展示等も行っておりますので、そうした機会を捉えて、様々な啓発にも取り組んでいきたいと考えています。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にとどめます。道路交通法の改正について非常に大きな改定になると思うので、どのように啓発しようとされているか、お考えを伺います。","respondent":"山下交通安全担当課長","answer":"その他、ＳＮＳや、今後考えていますけれども、広報紙に法の改正についてのご案内をするといったことも検討しています。各警察と連携して各種キャンペーン等も行っておりますので、そちらでしっかり、こちらも啓発は強化してまいりたいと考えるところです。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"一生懸命、あまり車の免許更新みたいに、どうしてもここに行かなくてはいけないというような啓発の場がないことが大変気になっております。ちょっと、款をまたぐかもしれませんけれども、ぜひ連携していただきたいと思うのですけれども、その点についていかがでしょう。","respondent":"山下交通安全担当課長","answer":"１５歳まで義務教育の過程を終えた方は、基本的には一定の自転車ルールを学んだという認識の下、１６歳以上と定めたと聞いているところです。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３７１ページ、防災訓練経費についてお伺いします。このことからも、この取組に効果があったことが分かりますが、区として成果と感じていることがあれば説明するよう求めました。","respondent":"星災害対策担当課長","answer":"ご指摘のとおり、地区総合防災訓練ＰＬＵＳ ＯＮＥ ２０２４につきましては、参加者数が増加し、特に、様々な年代の方に参加いただけたところ、今まで防災訓練に参加してこなかった方が増えたというところで、成果が出ていると感じています。","id":"exchange-075"},{"speaker":"澤田委員","kind":"質問・要望","question":"防災訓練に参加したいという要望を頂いておりまして、その中でも、受入れ態勢がないというようなお声も同時に頂戴しております。区として課題だとお考えのことがありましたら説明するよう求めました。","respondent":"星災害対策担当課長","answer":"ご指摘のとおり、人数は増えておりますけれども、障害をお持ちの方の参加というのは若干少なく、様々な課題があると認識しております。","id":"exchange-076"},{"speaker":"澤田委員","kind":"意見","question":"２年前より手話通訳者の方を防災訓練に派遣し、聴覚障害のある方への防災訓練への参加を促す取組を始められたと認識しております。今後の皆様へのアプローチの方法、防災訓練を行う際の対策など、具体的にあれば説明するよう求めました。","respondent":"星災害対策担当課長","answer":"先月９月２７日、しながわ中央公園で行われました「ふくしまつり」におきまして、初めて福祉部と連携した防災訓練を実施しました。障害をお持ちの方に配慮を含めました防災訓練をつくっていただく、また考えていただく必要があると考えているところです。","id":"exchange-077"},{"speaker":"澤田委員","kind":"質問・要望","question":"１３地域の中には、その中でも、行われている好事例を共有することなども必要であると考えます。環境の整備、周知方法の検討などをさらに進めていただくことを要望いたしますが、見解を説明するよう求めました。","respondent":"星災害対策担当課長","answer":"現在は障害者７団体の会合に訓練参加のお願いをするほか、安心して訓練会場に臨んでいただくために、今後検討していきたいと考えております。継続して皆様のお声を頂いて、また参考となる事例を取り込むなどして、積極的に進めてまいりたいと考えているところです。","id":"exchange-078"},{"speaker":"澤田委員","kind":"質問・要望","question":"「医者です」、「看護師です」、「手話ができます」というようなビブスの導入について要望していたと思います。現在の検討状況と、今後どうされていくかというお考えを説明するよう求めました。","respondent":"遠藤防災体制整備担当課長","answer":"背中に「品川区」と入りました黄色いベストを１０着、あと要配慮者等へ対応する専門員用のビブス２枚を、各５２避難所に配備しています。避難所連絡会議等で、避難所におけるビブスの追加導入についても今後検討してまいりたいと考えています。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"こういった、猛暑・酷暑と災害が重なったらと思うと、非常に想像するだけで恐ろしいわけですけれども、それでお伺いいたします。こういった猛暑に特化したような品川区の備蓄等がもしあればお教えいただきたいのですが、いかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"失礼しました。避難所は冷暖房を完備してございまして、そのほかに備蓄品として扇風機を配備しています。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私から提案したいのは、熱中症対策用のテントです。こういったものをぜひ何基か購入して、区として備蓄していただければと思うのですが、いかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"購入しても、なかなか訓練等で活用する場が少ないということで、なかなか課題が多いと認識しています。現在のところ、区としては、新たなテントの整備は計画してございません。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"現在の２９か所から３２か所まで備蓄倉庫を増やすという計画もありますので、こういったものの備蓄のスペースもご検討ほしいと求めました。いかがか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"区としても計画的な備蓄の検討をしておるのですが、それでも日々様々な、新しく要求されるような備蓄品が増えてあります。こちらも区としては新しくストックしていきたいと考えていますので、また活用について、研究させていただきたいと考えています。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"よろしくお願いします。最新のものはいつ決まって、今の状態なのか、お教えほしいと求めました。","respondent":"星災害対策担当課長","answer":"申し訳ございませんが、１０年前までは追えまして、平成２７年までは同じ金額であることを確認しております。それよりも先のところは、申し訳ございませんが調べ切れず、分かりませんという回答になります。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"いろいろ、２５年ぐらい前に１回変わったというような話も聞いていて、床下浸水に関しては１万円からほぼ変わっていないということでした。","respondent":"星災害対策担当課長","answer":"現在、見舞金は、被害に遭われた方のお気持ちに寄り添うためにお支払いさせていただいているところです。他区の状況等を調べますと、現在、品川区の見舞金の金額は特に低いものと認識はしていないところです。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"最大８０万円で、助成率５分の４ということなのですけれども、後からこういった制度を知ったという方も伺っております。これは要望にとどめておきますけれども、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"大倉委員","kind":"質問・要望","question":"この辺、ぜひ表示の設置を検討していただきたいと思っているのですが、いかがでしょうか。訓練などという視点からも、ぜひこうしたことに取り組んでほしいと求めましたが、いかがか尋ねました。","respondent":"森道路課長、羽鳥防災課長、関根河川下水道課長","answer":"そういった学校とのイベント、周年イベントなどと併せて、何か桜が使えないかということは、引き続き検討していければとは考えています。こちらはマンション防災を進める上でも重要な役割ということを認識してございまして、３階建てかつ１５戸以上と設定させていただいているところです。私からは、防水板の助成制度についてお答えいたします。","id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"一定、こうした緩和をしながら、進めていただきたい。３基はどうするのだみたいな議論は、１基入れば、ぜひ進めていってほしいと求めました。","respondent":"星災害対策担当課長","answer":"私からは、水害に対する訓練についてご説明します。確かに今回の被害を踏まえまして、水害対策訓練というのは非常に重要であると認識しております。","id":"exchange-087"},{"speaker":"大倉委員","kind":"質問・要望","question":"家庭へ逆流した下水が来るので、逆流防止対策というところで、こういった水のうを排水のところに置くなどということも周知しています。こうした周知も併せてぜひ進めていってほしいと求めましたが、最後にお願いします。","respondent":"羽鳥防災課長","answer":"先ほど委員がおっしゃられましたとおり、内水氾濫につきましては、下水管から水が逆流するという現象が起きますので、そういったところも、現状、しながわ防災ハンドブックには記載はしていますが、改めて周知は強化してまいりたいと考えています。","id":"exchange-088"},{"speaker":"大倉委員","kind":"意見","question":"しながわ防災ハンドブックに書いてあるのは分かるのですが、例えば今回も非常に有効的だった、災害が起きたときに迅速な情報発信などというところもありますので、そういうところも含めて検討をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"のだて委員","kind":"確認","question":"平成１５年２月２５日以降の建築確認で、標高５ｍ以上の場所は、なぜこれらは対象外なのでしょうか。伺います。","respondent":"関根河川下水道課長","answer":"１点目、浸水リスクも比較的高いという構造であることを踏まえた上で建築されていると認識しておりますので、現時点で対象外としております。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"２６年前ですか、荏原町駅は標高１９.４ｍですが、この近くでも助成を使って設置したと聞いています。ぜひ現況地盤より掘り下げた建築物や半地下駐車場なども対象にしてほしいと求めましたが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"先ほどと重複する部分もありますが、今回ご指摘のとおり、非常に甚大な被害が、標高にかかわらず発生していますので、委員ご指摘の点も踏まえて、要綱の改正等について検討してまいりたいと思います。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"別のお宅では、防水板のところではなく、別の低いところから入ってきてしまったということも伺いました。メンテナンスの必要性の周知や支援も必要ではないかと思いますが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"委員のご指摘のとおり、一度設置したら終わりというものではなくて、継続的なメンテナンス等も必要なものであるとは認識しております。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"防水板設置を進めて被害を防ぐために、助成割合を引き上げることを求めたいと思いますが、いかがでしょうか。平均的に工事費はどの程度かかるのか、助成額は十分なのかも伺いたいと思います。","respondent":"関根河川下水道課長","answer":"メンテナンスについて、広く周知するといったところについても検討させていただきたいと考えております。個人の方ですと、品川区内に住民登録している個人の方は上限が１００万円という形になっておりますので、満たせているのかなと認識しております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"ほかにも区民ニーズに合わせて活用できるよう、東京都に求めてほしいと求めましたが、いかがでしょうか。現在の買収面積は何平米なのか、分かれば伺いたいと思います。","respondent":"高梨都市計画課長","answer":"引き続き区といたしましては、区民からの要望を受けて、粘り強く東京都には要望してまいりたいと考えているところです。なお、買収済み用地の面積については、区としては把握してございません。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"住民から出ている恒久的な使用というのは、どういう用途なのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"例えばの例になりますけれども、町会で防災倉庫の設置用地として使用したいとか、あと、ごみのステーションとして、買収済み用地を一時的に借りられないかというようなお問合せが来ておりまして、こちらについても都に要望しています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、住民追い出しの特定整備路線は廃止にして、買収地を活用して、公園や福祉施設などの整備を進めていただきたい。緑と福祉のまちづくりに転換していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"私は、３６８ページ、防災費について、その中のエレベーターチェアとトイレトラックについて、また質問します。区内に何台あるか分かりませんが、オーナーや組合に普及啓発をもっと強くするべきだと思いますが、ご見解を説明するよう求めました。","respondent":"羽鳥防災課長","answer":"一定、優先順位が決められておりまして、例えば病院のような公共性の高い建物から順次対応することにはなってあります。まずは対応していくというような体制も取られているところではありますので、エレベーターの復旧については迅速に対応いただきたいと考えています。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問・要望","question":"では、どうしたらいいのですか。その人たちにどうやって対応するのか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"こちらにつきまして、区としても認識しています。災害対策用井戸、民間井戸の活用といったところも活動として進めておりますので、引き続き生活用水の確保についても推進してまいります。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"これは、３４６ページの都市計画費にも関わる質問をしたいと思います。このことについてお伺いいたします。","respondent":"川原住宅課長","answer":"管理不全空家を７件、認定を行いまして、今年度４月から１件ずつ対応を行っているところです。そして、現在の進捗の状況としては、７件のうち５件については、除却の見込みや建て替え予定、あと部分撤去などに向けた修繕が進んでいるところです。","id":"exchange-099"},{"speaker":"塚本委員","kind":"確認","question":"かなり、この指定によって、空き家の改善というのが進んでいるなという状況を確認させていただきました。今後、新しい条例の改正によって、空き家の改善ということは進んでいくのだろうと思いますけれども、一言、今後の見通しについてお伺いいたします。","respondent":"川原住宅課長","answer":"委員にご指摘いただきました、管理不全空家というところを認定することによって、区が所有者と、より強い指導等も含めて対応が可能になりましたので、引き続き区内の空き家の対策というところは強化して行っていきたいと考えています。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"この条例の対象になる地域について、これで伺いたいのは、品川区内で都市計画法第２９条による宅地開発というのが実際どれぐらい行われているのか。そういう電線の引き方というのはどういうふうになってくるのかについてお伺いしたいと思います。","respondent":"川原住宅課長、高梨都市計画課長","answer":"居住の用に供する建築物の建築に伴う土地の区画の変更が、令和６年度に開発許可を行った件数は、２件行ってあります。区政区域内で行われているものとして過去の実施の件数は、令和２年に１件と令和３年に１件、計２件という状況です。開発区域内の電線類の扱いといったところですけれども、開発区域の境のところで地中化していただいて、地中を通って開発区域内の電線確保の協議をするというところを想定しているものです。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"一応、５００平米以上が対象ということになっていますけれども、これは自治体によって広さがそれぞれ違ったりすることもある。そうでないと実質的には電柱ができてしまうみたいなことがあったりするかという懸念からの質問なのですけれども、お伺いしたいと思います。","respondent":"川原住宅課長","answer":"今ご質問いただきました開発行為が必要な区域、５００平米の見直しといったところは、現在のところは区においては予定してございません。","id":"exchange-102"},{"speaker":"塚本委員","kind":"質問・要望","question":"先ほどのトイレトラックの質疑についてお伺いしたいのですけれども、「それはちょっと使えませんね」みたいな答弁だと、あまりにも不十分。どういうときにこれは使えるのかというのを説明してほしいと求めました。","respondent":"遠藤防災体制整備担当課長","answer":"どういう場合にトイレトラックを使えるのかですが、まず道路が閉塞されていないところへ。道路が閉塞されていないということにはなりますが、道路啓開が終わった後に、トイレトラックを移動させるといったところは考えているところです。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問・要望","question":"使うべきフェーズがあると思うのです。それが３日後になって、１０日後になって、これはしっかり認識してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"少し気になるのが、１,３００人ぐらいですか。そうすると、し尿等の処理はどうされることになっているか尋ねました。","respondent":"山下交通安全担当課長、高梨都市計画課長、川原住宅課長、星災害対策担当課長、遠藤防災体制整備担当課長","answer":"これは東京都の規則で１０ｍ先を照らすことが可能なものということで、２００lmから３００lmのものが推奨されているところです。区もこれから新庁舎の工事が始まってまいります。情報を共有して、必要な要請をしてまいりたいと考えています。区営住宅、特に複合施設も含めた建て替えの計画があるかといったご質問です。私からは、防災訓練について説明をします。今年度の訓練が全体的に終わりましたら、人数等々、課題等を分析してまいりたいと考えているところです。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"使えなくなったらどうするのですか。だから、し尿をどうするのですかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"西村委員","kind":"提案","question":"３６７ページ、空き家等対策事業、時間が許せば３４２ページ、河川下水道費から排水力強化について伺ってまいります。令和６年度、空き家専門相談窓口で活用提案をしていただいておりまして、３２件の相談のうち２５件が解決に至ったと成果報告書にありますとの意見を述べました。","respondent":"川原住宅課長","answer":"空き家の有効活用の推進というところで、民間の事業者の窓口を活用して、ワンストップで対応する窓口を設置しています。住宅課で対応している空き家の戸数としては、空き家については２万６,０００戸近く、調査をどのようにしていくか。","id":"exchange-107"},{"speaker":"西村委員","kind":"提案","question":"売却して資産活用しませんかと、踏み込んだ提案ができるのは不動産屋であり、不動産屋が入れば調整が可能なことが多いと考えています。相手が公的機関なら安心という方も多いと思いますので、ご答弁をお願いいたしますとの意見を述べました。","respondent":"川原住宅課長","answer":"様々な空き家に対する所有者等からの相談に対しては、行政としても対応はしっかりと引き続き行っていく必要があると認識しています。不動産の知識を持つ不動産団体など、いろいろな有識者とも連携して、区としてできることを対応してまいりたいと思います。","id":"exchange-108"},{"speaker":"西村委員","kind":"質問","question":"何よりこの事業によりまして、利活用の件数が着実に増加したと伺っている点に大変注目しております。品川区でもプロジェクトを立ち上げまして、踏み込んだ実施をお願いしたいと思いますが、もう一度ご答弁をお願いいたします。","respondent":"川原住宅課長","answer":"確かに２３区でも、今後増える見込みのある空き家に対して、どのように対応を行えるか。民間事業者との連携により広げられるところ、拡充できる部分というところでは、引き続き拡充策については検討してまいりたいと思います。","id":"exchange-109"},{"speaker":"西村委員","kind":"質問・要望","question":"以前、情報共有していることがあるというのを課長からもお伺いしておりまして、品川区の空き家対策を改善させてほしいと求めました。雨水浸透施設に関しましては、現状、４,９１２か所、整備していると伺っておりまして、この数が多いのか、少ないのか。","respondent":"森道路課長","answer":"やはり内水氾濫といいましょうか、下水道管の能力を超えたものが道路のほうにあふれ出してきたと、所管としては認識しております。それから９月に改定いたしました計画の中では、引き続き、雨水浸透施設につきましても加速して設置していければと考えています。","id":"exchange-110"},{"speaker":"西村委員","kind":"質問・要望","question":"最後になのですけれども、こういったことを、推奨ではなくて、５００平米以上の場合、設置の義務づけをお考えいただきたいと考えています。品川区には指導要綱はありますけれども、任意寄りではないかと思いますが、いかがか尋ねました。","respondent":"関根河川下水道課長、羽鳥防災課長","answer":"私からは、浸透施設を義務化すべきといったご質問にお答えします。現状、多くの方に協力を頂いておりますので、義務化は考えてございません。掲示板での情報発信についてです。今回、様々な情報発信媒体を活用して発信してまいりましたが、紙媒体での情報発信についても強化してまいりたいと考えています。","id":"exchange-111"},{"speaker":"田中委員","kind":"確認","question":"区としては合計８か所での説明会を行いましたが、周知の実績を確認したいと思います。８回開催されて、何人ぐらい参加されたのか、また説明会以外にも周知はどのようにやっているのか、お伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"地域で説明会をさせていただきまして、総参加者数は４４名ということで、ご高齢の方がほとんどであったという状況です。そのほかの周知につきましては、開始時に、対象地域を含めてエリア周辺に全戸ポスティングをしています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"これはなぜかというのを確認したいのと、その他、旗の台の駅など、多くの方が利用するような施設にも乗降場所がないのです。乗降場所の増加は考えるというお話でありましたが、その点について、今の状況をお聞かせほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"周辺を見回しまして、皆様が興味を持つような施設については併記するような形等、工夫を凝らしてまいりたいと考えています。先ほど委員からありましたように、地域の皆様のお声を頂きながら、できるだけ増やす方向で調整はしていきたいと考えています。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"お伺いしたいのですが、特に一番多かった声として、料金のことを強く言われました。それらについて、お聞かせほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"これも予算編成過程の中で検討はしてまいりますが、できるだけ利用状況を踏まえながら、利用者に寄り添った対応ができたらと考えています。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問","question":"これは、利用者からすると、１３地区を超えていろいろな地域に行きたいという声のほうが多分多いと思います。もっと需要という視点で検討し直すというか、検討していくべきだと思いますが、そこはいかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"先ほど申し上げたとおり、あとは既存の交通事業者との関係で様々調整が必要であるとか、そのような観点からエリアを設定しているものです。私どものほうにも、目黒区に行きたいという声も頂いたりしておりますが、いろいろと研究させていただければと思います。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて浸水対策について伺いますが、先ほど鈴木ひろ子委員からもお話がありましたが、平成１２年に、我々１期生の頃に大水害が発生いたしました。でも、そこには確実に平成１２年からの対策が、そこはどのように受け止めていらっしゃるのかをお聞かせほしいと求めました。","respondent":"関根河川下水道課長","answer":"非常に大きな被害が出ておりまして、例えば平成１１年８月には、１時間最大７７mmの雨に対して約２,８００棟の浸水被害が発生したという状況です。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"これまでのやり取りを聞いて、１点だけ確認したいのですけれども、土のうは重たいからこそ効果があるのだと思います。そこはどうか尋ねました。","respondent":"森道路課長","answer":"青いビニールシートでくるんで、それで土のうの代わりにするというような使い方であれば、一定程度の効果はあるのかなと考えています。今おっしゃられたとおり、それぞれの違いが分かるように、広報もしていければと思います。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問","question":"周辺の水害の範囲が広がってしまったということが、前回、平成１１・１２年のときもありましたし、今回も実はあります。周辺の水害に及んでいるという背景がありますので、特に踏切周辺の下水道対策は喫緊の課題だと思いますが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"今、品川区が東京都より受託して進めております第二戸越幹線におきまして、まさに委員からご指摘のありました地点、また、そこより西側のところにおいて、水を取り込むマンホールを造る予定としておりますので、そこから完成すれば大きく水を取り込めるのかなと認識しています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほかの委員の方からも質問がありました、今後について、来年に向けてどのような形で進められていくのでしょうか。この切れている部分に、今回のことを受けて、ぜひ溢水防止板を設置してほしいと求めましたが、いかがか尋ねました。","respondent":"大友公園課長、関根河川下水道課長","answer":"公園での花火の利用は実施してまいりたいと考えているところでございまして、公園の利用促進、魅力向上に努めていきたいと考えているところです。立会川に設置されている溢水防止板につきましては、護岸の構造や建築物との関係上、これまで未設置の箇所も存在していることは認識しています。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"スラックラインは、そういう整備をしていただけるという方向で検討していただきたいのですが、いかがですか。それから溢水防止板については、今お話があったように、ぜひ早急に、設置していないところにお願いします。","respondent":"大友公園課長","answer":"整備についてですけれども、公園の改修時などに検討する形にはなるかと思うのですけれども、地域、利用者の声などを幅広く聞きながら、その必要性等も含めて検討してまいりたいと考えています。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"総務費のときにもお尋ねしたのですが、審査意見書の総括意見の９２ページ、ブランディング推進事業については総務費でお尋ねしました。包括連携協定も置いておいて、それ以外に監査から指摘があった、協定と事業の関係というのはあったのか尋ねました。","respondent":"黒田監査委員事務局長","answer":"令和６年度の決算審査に当たりましては、各所管に対するヒアリングを行いまして、各事業について執行状況などの質疑を行っているところです。相手方を優遇するというものではありませんが、包括連携協定の相手方が今後、「等」というような表現をしたものです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"その後の、キッチンカー活用事業についての流れというのが、これは災害時の協力体制の構築という観点でお尋ねします。そして、監査の指摘は、このキッチンカーの出店に関する指摘ではないのか尋ねました。","respondent":"黒田監査委員事務局長","answer":"こちらの決算意見書にあります意見につきましては、いわゆる地方公共団体における契約の在り方について、包括連携協定の際に質疑があったというものを取りまとめたものでございまして、特定の事業を指しているものではございません。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"意見","question":"その観点の上でお尋ねするのですけれども、それから地所賃貸料の１４万６,０００円の算出方法はどのようになっているのかということの意見を述べました。","respondent":"佐藤経理課長、遠藤防災体制整備担当課長","answer":"今、委員がお尋ねになったのは、令和７年度、本年度からプラッツァでやっているキッチンカーの事業だと思われますので、それについてお答えします。今回、協定を締結させていただいて、株式会社シンクロ・フードのキッチンカーの事業に併せまして展開していくといったものになります。","id":"exchange-123"},{"speaker":"松本委員","kind":"確認","question":"私からは、３５４ページ、公園管理費と、３３７ページ、屋外広告物取締事務について伺います。こうした問題というのは、当区にも大きな屋外広告がありますので、当区の場合の確認状況について伺っておきたいと思います。","respondent":"川崎土木管理課長、森建築課長","answer":"ステンレス、アクリル板、プラスチックといったものを使っているという形で認識しております。基準不適合物件および公衆に危害を及ぼす可能性のある物件を把握した場合は是正指導を行う実態調査というものを委託で行っております。委員ご指摘のとおり、建築基準法では、防火地域内にある広告板・広告塔等は、高さ３メートルを超える場合、その主要な部分を不燃材で作り、また覆わなければならないとされております。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問","question":"次に公園管理なのですけれども、今日は私は公園での撮影について伺っていきたいと思います。そこで伺いたいのが、業としての撮影の場合、申請の手続と費用についてお願いいたします。","respondent":"大友公園課長、川崎土木管理課長","answer":"撮影日の１週間前までに、品川区電子申請サービスにより公園撮影の申請を行っていただくという形になります。写真撮影につきましては、単価としては１,９９７円、そしてロケーションについては１万７,６２５円ということで、こちらは令和７年度に改定した価格にはなるのですけれども、そのような形で徴収しております。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"先ほどのコスプレーヤーの事例で、アマチュアのコスプレーヤーが個人のＳＮＳに投稿する目的で撮影する場合は、業としての撮影と言えるのでしょうか。解釈を伺えればと思います。","respondent":"大友公園課長","answer":"公園条例におきまして、業としての写真撮影、または映画を撮影する際は許可を受けなければならないとしています。そのため、個人のＳＮＳサイトの掲載の目的であれば、商業目的でないと判断されるかと思います。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"例えばＸなどは、ブルーバッジをつけていると、インプレッションが上がればＸからお金が払われるというようなこともあるかと思います。","respondent":"大友公園課長","answer":"収益を得ることを目的としたＳＮＳサイトに掲載する場合については、申請許可が必要と考えているところです。個人のＳＮＳサイトの掲載であっても、業としての写真または映画を撮影することに該当するため、申請許可が必要になると考えているところです。","id":"exchange-127"},{"speaker":"松本委員","kind":"質問","question":"例えば個人のプロモーションの撮影、動画の撮影でも、一般論としては「業として」というものに含まれ得るという解釈でいいのか尋ねました。","respondent":"大友公園課長","answer":"通常、個人的な写真やビデオの撮影は申請不要でありますけれども、個人的な撮影であっても、ＣＭや映画のように外部に広く公開する目的であれば、ロケーションの撮影に該当することもあるというところで、状況により申請が必要となる場合もあると考えています。","id":"exchange-128"},{"speaker":"松本委員","kind":"意見","question":"ただ、もともとなぜこういう規定があるかといったら、それで普通の区民が使えなくなるということを防ぐというところがあると思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３７１ページの避難行動要支援者支援事業に関連して、障害者の避難訓練の実施を求めて質問したいと思います。そして、その中で障害者を対象にした避難訓練などが議論になっているのかも説明するよう求めました。","respondent":"羽鳥防災課長","answer":"今年度は２回の開催だったと認識しています。その中で話題として、避難行動要支援者の方への避難訓練というところは、今まで具体的にテーマとしては上がっていなかったという認識です。","id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"様々要望を聞かせていただいた中では、防災に関する要望がありまして、障害者を対象とした避難訓練の実施を求める声も多くありました。これは当事者も望んでいることですので、求めたいと思うのですけれども、いかがか尋ねました。","respondent":"星災害対策担当課長","answer":"ご質問につきまして、お答えします。どういうものができるか等々、検討して進めてまいるよう、障害者団体の皆様とも連携を取っていくというふうに考えているところです。","id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ずっと出されてきた要望だと思います。当事者の声を取り入れた訓練を実施していただきたい、検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"羽鳥防災課長、星災害対策担当課長","answer":"こちらは地域連携コースという枠組みの中で実施してまいりましたが、独立した支援のメニューといたしまして実施すると。計３回行う予定で、現在、計画しています。防災訓練の実施についてということですけれども、また慌てないでしっかりと効果が出るような訓練というところをお話をし合いまして、実現に向けて進めてまいりたいと考えているところです。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いずれにしても、当事者の皆さんの声を聞いて進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問","question":"３７３ページ、時間があれば３５７ページ、公園・児童遊園整備費からお聞きしたいと思います。既存の止水板の高さを上げるというような、さらなる護岸の治水対策の強化が必要と考えますが、ご見解を説明するよう求めました。","respondent":"関根河川下水道課長","answer":"委員がおっしゃるとおり、いまだ未設置の箇所や、設置していても跳ね返り等によって溢水してしまった箇所があるということは認識しております。","id":"exchange-134"},{"speaker":"こんの委員","kind":"質問・要望","question":"被害の状況も見ていただきながら進めてほしいと求めました。治水対策を進めるよう、今後考えていったらいいのではないかと考えますが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"条件を緩和して、より使いやすくする、拡大するという方向で考えていきたいと考えています。一方で、場所場所に応じた重点という視点もあろうかと思いますので、そちらについては今後、調査等をさせていただければと考えております。","id":"exchange-135"},{"speaker":"こんの委員","kind":"質問・要望","question":"防災区民組織の育成費に関連して、町会・自治会に貸与されている防災服についてお聞きしたいと思います。現在の防災服は相当前から、これまで更新されることなく現在に至っていると認識しているのですが、現在の防災服について、現状をまず説明するよう求めました。","respondent":"星災害対策担当課長","answer":"今ご質問の、いつ頃からというところなのですけれども、平成１６年までは遡ることができたのですけれども、それよりも前、いつ配布が始まったか等々は確認できない状態です。","id":"exchange-136","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"確認","question":"どうか、区民組織の方々の着る防災服に関しても、見直しをお願いしたいと思います。対象になっている建物の構想をいわゆる木造住宅に限定しているわけなのですけれども、限定していることについてのお考えを、まず確認したいと求めました。","respondent":"遠藤防災体制整備担当課長","answer":"は感震ブレーカーを木造住宅につきまして優先して整備していくと。それによって木造住宅の延焼火災を抑制していくといったところが目的になってあります。","id":"exchange-137"},{"speaker":"こんの委員","kind":"提案","question":"２３区内で、荒川区、足立区です。最近、こうした住宅も併せた全ての建物の構造を対象にすることを提案したいと思いますが、ご見解を説明するよう求めました。","respondent":"遠藤防災体制整備担当課長","answer":"区としても、マンションの防災力を高めて在宅避難を確保するといった観点でも、感震ブレーカーの設置の必要性といったところは認識しています。","id":"exchange-138"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうか今おっしゃってくださったように、そこから火災を出さないといった観点からも、ぜひ進めてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問・要望","question":"３３９ページ、品川区も調査等していると思うのですけれども、現状はどうでしょうか。最後に３４６ページ、都市計画費で、私の政治のテーマである西大井について伺いますけれども、本当に西大井駅というのはいいのです。","respondent":"山下交通安全担当課長、森道路課長、小川木密整備推進課長、中道都市開発課長、関根河川下水道課長、森建築課長、高梨都市計画課長、櫻木地域交通政策課長","answer":"実施設計に入っておりまして、来年度、改修工事が行われる予定となっております。落ち葉で詰まる可能性の高いところを中心に、年に１回、１万４,０００か所程度を、順繰りに掃除をしているという形になっております。不燃化特区支援制度ですが、実施地区および助成支援内容については、都にて検討されているところです。当該地区は住宅街というところで、様々、どういった用途が足りているのか、足りていないのかというのも調査していると聞いてあります。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川区は土地が高いですから、やはりその辺の気持ちを考えたら、きちんとセットバックをしてほしいと求めました。これはどうしても実現していただきたいと考えていますので、また引き続き、私が議員でいる間は質問させていただきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"まつざわ委員","kind":"質問","question":"区の緑の現状についてお伺いします。枝を広げるというのですか、枝葉の広がりが、この緑の立体的な量というものだそうです。","respondent":"森道路課長、大友公園課長","answer":"令和６年度から街路樹の樹木診断を行いまして、幹の周りが６０cm以上などの比較的大きな街路樹について、樹木診断を実施しております。これを踏まえて、適正な管理も今後進めていきたいと考えております。季節ごとの夏期剪定・冬期剪定などの計画的な実施を行うとともに、日々の管理を実施いたしまして、適切な維持管理に努めているところです。","id":"exchange-142"},{"speaker":"まつざわ委員","kind":"質問","question":"緑に関するこういった施策というのは、公園課、また道路課、都市計画課など、複数の部署にまたがっています。区全体としてどのような方針に基づいて、緑はどれだけ増えてきたのか、説明するよう求めました。","respondent":"大友公園課長","answer":"みどりの条例や、区の緑の計画である水とみどりの基本計画・行動計画の方針に基づき、緑に関する取組を進めているところです。区内の緑は、令和６年度に実施した緑の実態調査において、みどり率が２１.５％、面積でいきますと５０４.４ha。","id":"exchange-143"},{"speaker":"まつざわ委員","kind":"提案","question":"そこでお聞きします。当該区域においても木陰の消失など、熱中症対策を一つの方針として打ち立てて、取組を進めることをご提案しますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"委員のご提案がございました木陰づくりというのも、今、都市部での非常に暑い中での心地よいまちづくりの１つの方針と考えています。こうした心地よい空間というものを、木陰の取組というのも併せて、ウォーカブルなまちづくりというのを進めていきたいと考えています。","id":"exchange-144"},{"speaker":"まつざわ委員","kind":"質問","question":"木陰をつくって、熱中症を防ぐための視線を加えて計画を設定していくのが大事だと思っています。品川区として方針をしっかりと示して、計画的に進めていく必要があると思いますが、ご見解をお願いします。","respondent":"大友公園課長、高梨都市計画課長","answer":"暑い中でも快適に過ごせる環境として、緑の創出は必要かと考えております。令和１３年度の本改定を見据えまして、緑の創出の視点も踏まえた、計画の中間見直しというところも検討してまいりたいと考えているところです。歩きやすいまちづくりのために、我々まちづくり部隊としてどういったことができるのかといったところにつきましては、今後検討してまいりたいと考えています。","id":"exchange-145"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"新たな格納庫の設置の要望があると思いますが、また現在、本区に存在しているのか。これまでに公園用地を活用して格納庫を設置した実績があれば、その数と経緯について説明するよう求めました。","respondent":"星災害対策担当課長","answer":"品川区では、こういった検討プロセス、基準等はございません。こちらも、先ほどの説明の流れの中で、消防団が設置したい場所に公園があった場合、設置可能な格納庫というところを設置しているという現状です。","id":"exchange-146"},{"speaker":"まつざわ委員","kind":"質問","question":"現状を見ますと１２個、公園の中にあるというお話ですけれども、しっかりとした基準というのですか、明確なルールがないということです。","respondent":"大友公園課長","answer":"東京消防庁の防災資機材倉庫につきましては、本来は東京消防庁が設置場所をほかに確保する必要があるものと考えているところではあります。公園に設置するための基準であったりというところにつきましては、要綱とするのか、明文化する必要性はあるものと考えているところです。","id":"exchange-147","title":"町会・自治会支援"},{"speaker":"まつざわ委員","kind":"提案","question":"そこで、具体的な提案をしたいと思います。そうしないと、格納庫は絶対に増やすことができないと思っていますので、ぜひ区の前向きなご答弁をお伺いしますとの意見を述べました。","respondent":"大友公園課長","answer":"ほかにその他、設置場所の用地が確保できない場合というところを前提に、具体的基準等を検討してまいるものと考えているところです。具体的な基準を、また公有地全体につきましても、計画の中で考えていきたいと考えています。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/239858?Template=document&Id=7259#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":112160,"voices":356}},{"id":"r07-20251015-4","meetingId":"r07-c-settlement","date":"2025年10月15日","dateIso":"2025-10-15","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和６年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"せお委員","kind":"質問","question":"３９５ページ、補助教材費保護者負担軽減事業、３９７ページ、学校図書館経費について伺います。そして、１年やってみて課題はどのようなことがありますか尋ねました。","respondent":"石井学務課長","answer":"かなり保護者の負担が大きいというところで、子育てをしやすい環境を整えていくということで、事業を実施しています。令和７年度の予算の策定のときには、こういった学年ごとの単価のばらつきも含めて単価の見直しを行ったところです。","id":"exchange-001"},{"speaker":"せお委員","kind":"提案","question":"お忙しいとは承知しているのですけれども、備品化を今後の研究課題としていただきたいのですが、こちらの見解を伺います。学用品など、標準服のようにリユースできる仕組みを区で整えることも検討いただきたいですが、こちらも見解を伺いますとの意見を述べました。","respondent":"石井学務課長","answer":"各種無償化施策につきましては、やはり例えば教育に関していうと、一義的には国の責任において実施するものだと。いろいろな道具があり、そういったものを大切にしていく心を育むための取組が必要だと考えていますので、しっかりと研究していきたいと考えています。","id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"それこそ、学用品等の備品化で捻出できた財源を給食へ使えないかとも思うので、これは要望だけしておきます。令和６年度から、令和７年度でもいいのですけれども、簡単に「このような状況です」というのをお知らせほしいと求めました。","respondent":"石井学務課長","answer":"小学校が２紙、例えば２紙取っているところは２１校、多いところでは５紙取っているところもあります。４紙が２校、５紙が１校という形で、それぞれ各学校の裁量で購入しています。","id":"exchange-003"},{"speaker":"せお委員","kind":"提案","question":"そちらは見解を伺います。探求学習といったところを、今ご提案させていただいたのですけれども、それぞれ今後の取組について見解をお聞かせほしいと求めました。","respondent":"石井学務課長、丸谷教育総合支援センター長","answer":"学校図書館図書整備等５か年計画、令和４年度から令和８年度が出されたタイミングで、各校が新聞を配備できる十分な予算は確保しています。区立学校における朝読書の実施状況ですけれども、おおむね３分の２程度の学校で、朝読書が今、行われているところです。そこでの新聞の活用については、各校への周知とともに活用を促してまいりたいと考えております。","id":"exchange-004"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったところを、子どもも大人も皆さん目につくような場所に置くなどといった工夫もあればいいなと、その辺は要望させてほしいと求めました。そういったところも続けてやっているところもあると聞いているので、そういったところの充実もぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"９月１０日の日経新聞の記事では、３年後をめどに部活動の受託事業を売上げの半分まで伸ばす計画と、まさに需要と供給といったところか尋ねました。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"令和５年度に実施した簡易型プロポーザルにおいて、複数事業者の中から選定いたしました。理由としましては、事業実施に係る組織体制、指導者の確保方法および研修体制の項目等が充実していたことを評価しております。こちらは、教育委員会で募集をかけるとともに学校でも人材を探しております。もともと外部指導員として関わっていた方、また地域の人材ということで、様々な属性の方がいらっしゃるところです。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"確認","question":"それぞれの中で、続きまして教育的な質の確保と安全管理についてお伺いいたします。万が一の保険制度や報告体制についてお伺いいたします。","respondent":"酒川指導課長","answer":"安全管理等についてですが、安全管理やハラスメント防止などに関する研修は、これも委託事業者で実施しております。トラブル対応を含めて、それから事業者が、報・連・相を徹底して対応しています。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"部活動の地域移行を進めるに当たって、教育基本法に基づくこういった教育理念との整合性をどのように位置づけているのか、見解をお伺いいたします。","respondent":"酒川指導課長","answer":"教育的意義については……。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"３９７ページの学校システム運営費と、３８５ページの市民科・各教科充実経費に関連して、また防災教育について伺いたいと思います。３点目にもう一つお聞きしたいのが、以上、３点お聞きしたいと思います。","respondent":"石井学務課長","answer":"去る９月１１日の大雨の際、下校時間を変更する等については、学校より保護者に連絡せねばならないというような状況でございました。統一的なところでこういったときにはこういう対応をするというようなことではなく、各学校のメールの連絡というものが１つの対応であると。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"もう一点ですが、こういった影響で人的被害などはなかったのかについてもお聞きしたいと思います。","respondent":"石井学務課長","answer":"メールの遅延によって人的被害が生じたなどといった報告は聞いておりません。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ここについての対策はどのように取られているのか、現状の分析、原因についてお聞きできればと思います。","respondent":"石井学務課長","answer":"近年、これがいわゆる迷惑メールと認識されてしまうようなことや、各時間当たりに決められたメールの通信数を設定するような形になっております。令和９年度に校務システムの更改を予定しております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"事前確認で、不具合はなかったことも伺っていますが、様々な緊急連絡手段の中の一つだと思われます。学校によっては、一人一人の児童の保護者に、先ほどもありましたが電話での緊急連絡をされた学校もあることも伺っております。","respondent":"石井学務課長","answer":"ここと、ここと、ここを見てくださいというふうなことをご説明するといったことも考えられるのではないかと思います。なので、思い込みで、例えばメールを送ったから大丈夫だろうなどということを思わないことが、一番の危機管理になるのではないかと考えております。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"続けて、非常時の学校側の対応、また防災教育についてお聞きしたいと思います。こちらについてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"各学校におけるマニュアルですが、学校の危機管理マニュアルというものを、国の手引を参考にしながら作成しています。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"確認","question":"危機管理マニュアルを各学校で策定されていると確認させていただきました。こちらについてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒保護者への周知ですけれども、４月の段階で、学校より通知を発出しています。基本的に、大きな地震や今回のような大雨で、特別警報・暴風警報が出た際には学校に留め置くことや、臨時休業についてアナウンスをしています。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"今回のような局地的集中豪雨で、保護者が迎えに行ける場合もあれば、迎えに行けない、帰宅困難者の場合といった対策というのも、事前に周知する必要があると思いますが、この辺についての区の発信の仕方や防災教育についての観点からお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"学校において留め置きとなった場合は、保護者または親族、あらかじめ決められた方が迎えに来るまでしっかりと留め置いて、子どもの安全を確保するということで進めております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元の声に応え、建て替えの検討に着手するよう求めて質問いたします。結果はいつ出て公表はいつ頃になるのか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"令和７年度は、引き続き西側の校舎で屋上防水・外壁改修を実施しております。もう一点、検討の内容ですが、１点目の工事期間の検証というところにつきましては、現在、検証を続けているところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"この２つの報告書に目を通したのですが、学校教育関係者にも読んでいただいて、意見も伺いました。子どもたち一人一人への学習というのを強めるということが、今後のいじめ防止においても大切かと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"これは、法に基づいて適切に認定しているということで、決して子どもたちの中で解決できない問題が増えたとは捉えておりません。子どもの権利条約も含めまして、子どもたちが安心で安全に学校に通えるという環境づくりについて、研修等、また授業等で尽力しています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですけれども、毎年の学力テストの実施というのが、そういうふうには思わないのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"学力定着度調査は、国のもの、区のものを行っていますけれども、子どもを比較するためのものではなく、教師の指導方法の工夫改善に活かすものと捉えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"１断面で、しかも学力のみ、点数のみで評価しているということにつながるのです。子どもたちが自分もそう思うし、学力テストは抜本的に見直すべきだと、この点からも私は申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"区に発行されたアカウント数と、実際に利用している児童・生徒の人数はどれくらいか、伺いたいと思います。そして、導入の効果について、実際に活用してみてどのような成果や変化が見られたか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"アカウントは７６個、平均して５名程度のログイン数ということで、学校に通えるようにはなっています」などといった声も聞いています。は支援員ともコミュニケーションが取れるということで、その中で自己表現ができるということが最大の効果・成果だと考えております。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"様々な幅広い学年の方が使っていて、いろいろ子どもたち同士でもコミュニケーションを取っていることをお聞かせいただきました。終了する見込みだとお伺いしたのですけれども、あるいは別の支援手段を検討しているか、お考えを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"東京都の事業として、令和５年度から令和７年度、今年度いっぱいの事業となっております。令和８年度以降、東京都がどのような形でこの事業を継続するのか、継続できるようにしていきたいと考えております。","id":"exchange-021"},{"speaker":"せらく委員","kind":"質問","question":"豊島区では公立小・中学校に通う外国籍の児童・生徒が１０年で１.８倍に増加して、令和７年度には５８２人に達しています。品川区においての傾向、現在の日本語指導が必要な児童・生徒数と推移を伺います。","respondent":"丸谷教育総合支援センター長","answer":"すぐにはお答えできないのですけれども、令和６年度で、小学生・中学生を合わせて１５１名の児童・生徒が指導を受けているところです。大体、このぐらいの数で推移していると考えています。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問","question":"そういった児童・生徒と保護者の多言語対応について、まず伺っていきたいと思います。教室の実施状況と指導内容というところを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"保護者に対する多言語の対応状況ですけれども、教育総合支援センターではタブレットを活用してやり取りができるような仕組みを整えています。ＪＳＬＩのほうですけれども、日常生活に支障が出ないような形で、イラスト等を使いながら、丁寧に指導しています。","id":"exchange-023"},{"speaker":"せらく委員","kind":"質問・要望","question":"それによって、日本語教室の利用者数も増えたということをお聞きしました。品川区においても、巡回型の日本語指導というところや、その後の定着支援についても、方向性・方針をお聞きしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"保護者への連絡ツールにつきましては、様々、比較検討しながらアプリを決定できればと考えます。現在２校に全域から集まって指導を行っていますけれども、中には通室が難しいということで、オンラインでの対応も行っているところです。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"それらをいかに捻出するかを、来年度の予算編成に際しても、組織的かつ意識的に念頭に置いていただきたいと強く要望いたします。１点目に、学校環境整備費についてお伺いいたします。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"令和６年度につきましては、耐用年数を迎えた空調機の更新を実施しています。令和７年度も引き続き、範囲を変えて空調機改修を実施しています。１９６０年代頃起こりました水難事故や、東京オリンピックを契機として、水泳授業が体育の項目として盛り込まれたと認識しております。","id":"exchange-025"},{"speaker":"横山委員","kind":"提案","question":"１つでも強化していただくことは、地域の命と財産を守ることに直結すると私は考えますが、区教育委員会のご見解をお伺いいたします。貸出し業務に充てていた時間を、段階的に自動貸出し機を導入していただくことを要望いたしますが、区のご見解をお伺いいたしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長、荒木学校施設担当課長、三ツ橋品川図書館長","answer":"現在、区立学校、特に小学校の高学年においては、着衣泳を実施する学校もあります。そういった抜本的な対策が難しい部分はありますので、短期的には校舎内への止水対策というところを重点的に整備してまいりたいと考えています。できること、できないことを含めて、関連部署と調整していきながら検討してまいりたいと思います。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"防災のほうなのですけれども、地域や防災部門と連携して進めてほしいと求めましたので、よろしくお願いいたします。数字にならない業務こそ、子どもたちのための重要な仕事であり、当たり前を守るための地道な価値ある業務を担う全ての方々に敬意を表します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"４０１ページの給食運営費、４０３ページの学校改築推進経費について、順不同にて伺います。学校改築推進経費について伺います。","respondent":"荒木学校施設担当課長","answer":"最新の学校改築における単価ですが、既存校解体や新校舎建設、外構整備と、様々な一連の工事がありますが、純粋に新校舎建設だけを捉えてみれば、平米単価７０万円台後半ぐらいということで今想定しています。","id":"exchange-028"},{"speaker":"山本委員","kind":"確認","question":"見解を伺います。ご見解を伺います。","respondent":"荒木学校施設担当課長、加島財政課長","answer":"この数値だけ見れば、周辺自治体と比較しても、非常に先進的に取り組んでいるのだろうという認識です。国の補助金、それから起債等を活用して、改築の規模に応じた財源の確保を図っているところです。現在、この中で教育部門と協力しながら、学校改築推進経費の見通しを立てていければと考えております。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問・要望","question":"品川区の教育施策の１つとして実施している職業紹介の授業で、様々な職業の方のお話を直接伺うことで、とてもよいと感じております。予算については全校分確保されているのか、確認したいと求めました。","respondent":"酒川指導課長","answer":"子どもたちが地域の職業人から学ぶ「しながわドリームジョブ」の令和６年度の実施状況ですが、義務教育学校６校の計３３校で実施しております。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"見解を改めて伺いたいと思います。続けて、関連して土曜授業について伺います。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"しながわドリームジョブにつきまして、成果・効果の共有を、校長連絡会等を通じて諮った上で、拡充を図ってまいります。区立学校における土曜授業の開催状況ですが、振替なしの土曜授業につきまして、４回実施している学校が１６校、３回実施している学校が１１校、２回の学校が１８校、１回の学校が１校という開催状況です。","id":"exchange-031"},{"speaker":"山本委員","kind":"確認","question":"４回のところと１回のところでは、全校でできるだけ土曜授業が開催できるように、こちらもフォローアップしてほしいと考えています。ご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"土曜授業が１日の学校であっても、行事を含めると年間に６回の土曜日を、決して全体として少ないとは捉えておりません。学校選択の観点からも、多くの方に見ていただくという視点は持っていただくように、学校には働きかけてまいります。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"今年度、新たに進めている有機野菜の導入については、別の日のほかの委員の方からの質問の答弁によって、現在の状況については確認いたしました。教育委員会、区全体、それぞれでご見解を伺います。","respondent":"石井学務課長、崎村企画課長","answer":"新規施策の立案におきましては、十分な調査を、いろいろな施策の背景等をしっかり踏まえた上で実施する必要があると思います。こういったことから職員の負担軽減に取り組んでまいりたいと考えております。新規施策に取り組む際の区の方針というご質問かと思うのですけれども、例えば事業の拡充や実施に当たっては、また。そういったときには、事業実施に当たっては丁寧かつ柔軟に、引き続き行政運営に努めていければと考えております。","id":"exchange-033"},{"speaker":"山本委員","kind":"提案","question":"当初予算において、ある程度、１年間の物価上昇を見込んだ予算編成を検討するということもあるのではないかと考えております。それぞれ見解を伺いますとの意見を述べました。","respondent":"石井学務課長","answer":"ただ、そういった中では、いろんな指標を用いて、きちんと適正に見積もることをミッションに掲げていきたいと考えています。味の感じ方の変化につながるのではないかといったことも考えておりますので、いろいろと魅力ある学校給食の運営を進めてまいりたいと考えております。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、区が把握されている、インターナショナルスクールに通っている人数を確認させていただきたいと考えています。そして、その算出の根拠もお伺いいたします。","respondent":"石井学務課長","answer":"今年の８月時点で学務課がインターナショナルスクールに通っている児童を集計したところ、３１４名という数です。通っていることを届けている方もいらっしゃるので、そういったものを推計した結果、出た数字です。","id":"exchange-035"},{"speaker":"新妻委員","kind":"確認","question":"次に、インターナショナルスクールに通う子どもたちについて、卒業したことを認めているかどうかについて伺ってまいります。いまだ学籍が置かれていないのはなぜか、またどのような課題があったのか、また今後の区の考え方をお伺いいたします。","respondent":"石井学務課長","answer":"委員がおっしゃるような問題点についても区としては認識しておりまして、この間、検討を進めてまいりました。一件、二件でしたら個別の対応というものも考えられるのでしょうけれども、例えば学校に定期的に通う見込みがなくて。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、少し人数が増えたということを確認できましたので、今後の動向を、区としてはどう捉えているのか。公教育ではなくインターナショナルスクールを選んでいく子たちが増えていくことに対して、区はどのように受け止めているのか、お伺いいたします。","respondent":"石井学務課長","answer":"学校の設置者として、より高質な教育をきちんと進めていくということ、品川区立学校としては考えていかねばならないと思います。ただし、教育というものが何を生徒に身につけさせるのかといったことは、考えていかねばならない問題であると考えております。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問","question":"中央教育審議会が９月の末に、デジタル教科書を正式な教科書とするということを、審議をまとめて了承されたということが公表されました。２０３０年度にも、品川区のよかった点、または課題点についてお伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"現在、区立学校では、英語と算数・数学について、学習者用のデジタル教科書が配備されておりますが、拡大や書き込み、保存、音声の読み上げ、背景・文字の変更・反転等、またルビ振り等もありまして、そういったことが有効に活用されております。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３７９ページの校外授業費についてお伺いします。熊のことについては教育委員会としては、子どもの安全を考えて、これまで議論されてきたことはあるのか尋ねました。","respondent":"石井学務課長","answer":"移動教室、林間学園は日光市に行きまして、７年生につきましては磐梯町にも行くような形になります。例えば７年生につきましてはガイドを設けたり、あとは６年生・５年生に関しては、議論を進めているところです。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"「品川区区民保養所のあり方検討会」が２回あって、３名、委員として参加しています。話はしていると私は認識しているのですけれども、内容等々、どういうことがやり取りされたのかというのをお尋ねしたいと思います。","respondent":"石井学務課長","answer":"「品川区区民保養所のあり方検討会」につきましては、その結果も含めて、まず「検討会で議論されたことはこういうことです」というのを。ぜひこういった日光市での移動教室を引き続きやっていただきたいという意見がとても多かったと考えています。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはり日光市というのはそれぞれ、他区でもいろいろ、林間学校等々をやっているわけではないですか。当然これは所管が違う部分もありますが、教育委員会として、これからどういう方向性でいくのかというのを聞きたいと思います。","respondent":"石井学務課長","answer":"移動教室の目的というところを考えたときに、代替地として、例えば他区の施設や民間の宿泊なども検討する必要が出てくるだろうと。今後の趨勢を見守っていかなければならない部分はありますけれども、１つの想定としては、幾つか検討していたところはあります。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望なのですけれども、光林荘は、教育の現場として、施設として、ぜひ残していただきたいと私は思います。土壌汚染対策法では未届けが１２件、都条例での未届けが４１件となっておりますが、今現在の進捗状況をお知らせ願いたいと思います。","respondent":"荒木学校施設担当課長","answer":"未届け状況につきましては、現在、この数で確定させまして、本年度中に、未届けであった学校の敷地内の地籍調査を実施しようと考えています。引き続き、敷地内でしっかりと調査をして、汚染土の状況を確認した上で必要な対策を行っていくというふうに考えてあります。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこの部分はしっかりとチェック機能を、確実に体制を整備していただきたいと思うのですが、このチェック体制というのはきちんと今なされているということでよろしいのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"全て研修を実施して、施工者と共に事業を進めてまいりますので、確実にチェック体制は築いていきたいと思います。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３８０ページ、３９４ページ、学校に冷水機の設置を求めて質問したいと思います。区教育委員会としてはどのように今後取り組まれていくのか、新たな取組などはされるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"正式なものが出されるですけれども、こちらの計画に基づいて、区立学校でも取組は進めてまいります。は教員の意識を高めながら、児童・生徒への学習指導にも活かしていきたいと考えております。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"一般質問でも、特にＬＧＢＴＱプラスについての研修を全教職員にと求めたのですけれども、電子データにより全教職員に周知していると。これらがどれぐらい活用されているのかというのは、把握はされているか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"こちらの行動指針の活用状況は、細かくは学校からはデータを取っておりませんけれども、大切な視点として訴えをしております。こちらの行動指針を用いた研修会を行っておりまして、参加者のみならず、学校に帰ってからの還元ができるような取組を進めているところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いかがでしょうかということと、今ご紹介した認定ＮＰＯ法人ＲｅＢｉｔの方が会議のメンバーにいます。団体の力を借りて、教員研修や子どもたちへの授業などを行ってほしいと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"ＮＰＯ法人ピルコンを講師に招いたものですけれども、今週金曜日、１０月１７日に、養護教諭向けに研修を開く予定です。こちらは学校にまた持ち帰っていただいて、学校での活用についても幅広く活用できればと考えております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、学校に冷水機があるといいという声を教員の方から伺いました。設置してはどうかと、私もその声を聞いて思ったのですけれども、いかがか尋ねました。","respondent":"石井学務課長","answer":"熱中症対策として、適宜適切に水分補給をすることはすごく大切なことだと考えております。なお、一部学校でも設置しているところはあるというのは聞き及んでおりまして、今後も適宜適切に水分補給を促していきたいと考えているところです。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"３７９ページ、校外授業費から、林間学園、修学旅行、光林荘について伺ってまいります。は令和６年度の決算を踏まえまして、宿泊料やバス代の高騰が、修学旅行や林間学園の実施にどのような影響を与えたのかを伺います。","respondent":"石井学務課長","answer":"バス代につきましては、かなり物価高騰のあおりを受けているところで、なかなか確保が難しいような現状であります。きちんとした休憩時間を設けるなどといった中では、バスの台数の増加や１件当たりの単価の増というものは、１つの課題として生じております。","id":"exchange-048"},{"speaker":"西村委員","kind":"提案","question":"先ほど高橋伸明委員から熊の質問がありましたけれども、全国的な課題になっている修学旅行のオーバーツーリズムを伺ってまいりたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"現在、９年生で実施している修学旅行の行き先ですが、７年生の間に旅行先を決めているという現状があります。行き先が選べないような学校がありましたら、そういったものは校長会とも連携・共有しながら、情報提供はできるようにはしたいと考えています。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問・要望","question":"７年生ですから、２年前に決めなければいけないということではありますけれども、ぜひ検討をお願いしたいと思います。ある学校の修学旅行では、７年生のタイミングで子どもたちにアンケートを取っているというお話を校長先生から伺いました。","respondent":"丸谷教育総合支援センター長","answer":"区にゆかりのある都市への修学旅行ということも視野に入れられるように、校長会にも情報提供はしていきたいと考えております。各学校で適切な旅行会社を選ぶように、こちらからも働きかけはしていくところです。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問・要望","question":"林間学園に関しましては、１校が山梨県に行っているというのを聞いておりまして、以前にはスキーに行った学校もあると聞いております。日光市もオーバーツーリズム気味だと伺っておりまして、各学校が行き先の変更をしやすくしてほしいと求めましたが答えるよう求めました。","respondent":"石井学務課長","answer":"かつては当然、日光市以外の場所に行っていたこともありますので、そういった創意工夫というのは１つ、促していく必要もあるかなと考えています。生徒の負担なども考えた上で、今後、校外授業の在り方については考えていきたいと考えています。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"無償化を機に様々お考えほしいと求めましたので、どうぞよろしくお願いいたします。トコジラミの体長が四、五mmということで、事前清掃でも見逃す可能性が高いと伺いました。","respondent":"石井学務課長","answer":"今回学びましたのは、トコジラミを完全にゼロにすることが必要なのではなく、発生したときにどのような対応を取るのかなのではないかと考えています。そのときには、林間学園・移動教室実施時のトコジラミ対応についてというようなマニュアルをつくった上で。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"で児童の対応については、また別の問題として考えるべきだと感じておりまして、お考えほしいと求めました。虫が苦手な児童や、虫に慣れていない児童も多数おりますので、判断する支援のための対策を説明するよう求めました。","respondent":"石井学務課長","answer":"今回、トコジラミが発生したことによって、トコジラミを発見した場合の対応についても記載しています。こういう対応がベストということはないのですけれども、やはり子どもの声を丁寧に聞くということはすごく大事だと思っているところです。","id":"exchange-053"},{"speaker":"西村委員","kind":"質問・要望","question":"様々難しいと思いますが、ぜひ今回のことをきっかけに、改めてお考えほしいと求めました。子どもたちの安全と学びの機会を守る観点から、学校教育には保護者にも寛容さと協力が求められていると感じますけれども、ご答弁をお願いいたします。","respondent":"石井学務課長","answer":"そのときには、いろいろなことが考えられ得るということは、改めて当然、保護者の皆様にもご理解いただきたいと考えております。ここにスポットを当てて、地域一丸となって、お子さんに向き合っていきたいと考えております。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問・要望","question":"そういった保護者の方々にも、一緒に子どもを育てているのだ、みんなで地域で育てていくのだという認識も持っていただきたいと考えています。","respondent":"石井学務課長","answer":"新規事業もそうですけれども、今回、トコジラミの対応を、現場の職員は物すごくよく頑張ってくれています。今もまだ対応が続いております。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ協力してほしいと求めましたが、いかがでしょうか。この力を災害時にも発揮していただきたい、ご協力ほしいと求めましたが、いかがか尋ねました。","respondent":"石井学務課長","answer":"給食調理現場は今、調理代行で実施しておりますけれども、学校給食を安全に提供するための大量調理は非常に高い技術を持っていると考えております。災害時につきましては、仕様書上については、自然災害発生時の対応についてというようなところは書いております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは、災害時の炊き出しについて調理員の方はご協力いただけるということなのか、できる限り協力したいという事業者の話だけれども、契約上のことではないということになると、一ボランティアとして参加するということなのか、もう少しご説明いただきたいです。","respondent":"石井学務課長","answer":"総合評価落札方式のときに回答した部分につきましては、例えば何か必要があったときには区からそういったお願いをするということはあると思います。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時の学校避難所における食事の提供について、調理員の方の参加・協力を、仕組みとして位置づけてほしいと求めました。そういうふうに仕組みとして整えてほしいと求めましたが、いかがか尋ねました。","respondent":"石井学務課長","answer":"防災部局と協議しながら進めていくような形になるかとは思っておりますけれども、学校は教育の場ですので、学校をいち早く再開すること。我々は教育委員会ですので、そこは忘れてはならないかなと考えています。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、停電時の熱中症対策としても、クーラーを動かすために外部電源の確保を緊急対策として進めてほしいと求めましたが、いかがでしょうか。事前に準備ができることだと思いますので、直ちに進めてほしいと求めましたが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"その際の対応ですが、災害時に災害対策本部室のある管理諸室、あとは体育館の最低限のコンセントや照明に充てているものです。今後、防災課などと連携しながら、あとは通常のガス式空調機の室外機に接続するための準備というものをしっかりと検討していきたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、改築校から導入してほしいと求めましたが、いかがでしょうか。現状の学校についても、様々改修を早めてほしいと求めましたが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"一方で、やはりガスタンクを学校内に貯蔵することになりますので、安全管理やスペースの問題があると感じております。いずれにしても、ガスタンク付きのＧＨＰの導入を含めて、最適な空調機の構成についてはしっかりと研究していきたいと考えています。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問","question":"初めに３７７ページの文化財保存活用事業について伺います。文化財の一般公開を３日間、子ども文化財企画を１回実施されたとのことですが、これらの保存活用事業の参加者の反応はいかがでしたか尋ねました。","respondent":"舩木庶務課長","answer":"いろいろ理解を深めることができた、実際に足を運ぶことで歴史や文化を学ぶよい機会になった、そして歴史を感じることができたというような意見をお預かりしております。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問・要望","question":"併せて伺いたいと思うのですが、文化財の保護や保存を行う上での例えばツアーや、ＳＮＳなどを活用した周知などは行っているのでしょうか。子どもたちはどのくらい参加されているのかといった年齢層が分かりましたら教えてほしいと求めました。","respondent":"舩木庶務課長","answer":"そういった部分に関しては、子どもたちの参加も一定程度、頂いているという状況です。周知につきましては、学校を通じたり、いろいろな広報等の媒体を通じて、広く周知を可能な限り行っているところです。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"「しながわくの魅力発見ツアー」についてなのですけれども、こちらはどういったところを回られて、企画をされているのでしょうか。併せて伺いたいと思います。","respondent":"舩木庶務課長","answer":"応募が６０名あったところを３５名の方に参加いただいているということもありますので、その辺りは、引き続き検討してまいりたいと考えています。参加者の層を広げることで、品川区の魅力を発信、受け止めていただくといった試みの事業としております。","id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"次の質問なのですが、３８５ページの、地域の歴史・文化学習について伺いたいと思います。そこで、大森貝塚の歴史的意義を、区民、特に子どもたちに伝えるため、現在どのような取組を行っているのか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"「貝塚博士になろう」という単元で、貝塚に関して課題を持って情報を収集したり、地域の方々などからお話を伺ったりしながら学習を進めております。品川歴史館からもそうした情報を得ておりますので、今後も活用は注視してまいります。","id":"exchange-064"},{"speaker":"松永委員","kind":"質問","question":"次に、文化財保護をより実効性のあるものとするための地域との連携や取組についてお伺いしますが、どのように進められているのでしょうか。示すよう求めました。","respondent":"舩木庶務課長","answer":"ただ、その後の調査で当時の歴史をひもときますと、最初にモースが発掘したのはやはり品川区だったということが、歴史的な書籍で確認が取れています。","id":"exchange-065"},{"speaker":"松永委員","kind":"提案","question":"１４８周年の記念式典に参加させていただいたのですけれども、品川区と連携して１５０周年事業に取り組みたいという発言がありました。ぜひ私からも１つ提案があるのですが、ぜひご検討ほしいと求めましたので、これは要望にしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"３９１ページ、図書館運営費、３９１ページ、学校地域連携推進経費、３７９ページ、校外授業費について伺っていきたいと思います。島ですから、３０分もすれば山にも行けるし、ジェットフォイルで１時間４５分で行けます。","respondent":"三ツ橋品川図書館長","answer":"知識の宝庫として図書館を利用していただく、またレファレンス機能なども司書から学んでいくというようなことを目指しております。そして、今後はデジタル機能も活用していただくということも必要だと考えています。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな機能として図書館が求められている部分もあって、１１館といいますか、もうずっと音楽が鳴っている図書館とか。ここならいたいなと思えるようなスペースというのでしょうか、ソファーにゆったりするとか、そういった場所も必要なのかなと思ったりします。","respondent":"三ツ橋品川図書館長","answer":"新たな図書館につきましても、新たな考え方でのスペースの有効性、くつろいでいただく場所というのも必要だと思っているところです。子どもたちも楽しく遊べるところもあるといいなと考えています。","id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、こういったビデオテープやカセットテープのデジタル保存について、現状どうなのか伺いたいと思います。いろいろな確認ができるかなと思いますし、この辺りも含めて、デジタルへの保存について品川区の取組状況を説明するよう求めました。","respondent":"三ツ橋品川図書館長","answer":"図書館においては、ホームページ上で実施しているものがあるのですけれども、図書館が所蔵している地域資料を中心にデジタルになっているところです。関連部署といろいろ検討しながら、なかなか難しいかもしれませんけれども、検討していきたいと思います。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問・要望","question":"２０２０年ぐらいまでのコロナ前は、一緒の踊りで一体化できるというのは、必要なことなのかなと思います。ちょうど今ぐらいの季節にやっている地域のお祭りとも連携しながらというのが出てくると思うので、品川音頭の取組について今の状況を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"２０１９年度までは、任せているというところになりますが、現在小学校で９校については毎年行っているということです。品川区の歴史を子どもたちが学ぶことの意義というものは非常に大切だと考えておりますので、こうした取組が、働きかけはしていきたいと考えます。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問・要望","question":"１つの、ツールといいましょうか、ぜひ品川音頭については学校現場でも積極的な検討をお願いしたいと思います。日頃からの交流先として、離島の伊豆大島との交流も、ぜひ大きい視野で検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問","question":"私も、教員に対する周知や積極的な活用の促しは、どのように行っているのか伺いたいと思います。それで、相談の実績はどれくらいか、把握されていたら伺いたいと思います。","respondent":"舩木庶務課長","answer":"速やかに対応できるようなことについて、１つ、手厚く支援を行っていると理解しております。長時間労働者を含む産業医の面接指導ということになりますと、令和６年は１２５名という実績があります。","id":"exchange-072"},{"speaker":"吉田委員","kind":"確認","question":"相談の実績は、今、数字でおっしゃったところしか把握できていないということでしょうか。確認したいと求めました。","respondent":"舩木庶務課長","answer":"例えば健康診断の未受診者等に対してもそうですけれども、これは単発の周知に終わることなく、定期的に周知を行っているところです。健康相談の実績につきましては、先ほど答弁させていただいた実績と認識しております。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"メンタル面での相談の実績がどれぐらいだったかというつもりで数を伺ったのですけれども、もし把握されておられたら伺いたいと思います。やはり感じ方として、例えば同僚や学校長に知られずに相談できる仕組みは確立されているのか、伺いたいと思います。","respondent":"舩木庶務課長","answer":"そこのところは内訳が不明なところです。これはオンラインでも対応しておりますし、もちろん対面でもということですので、その方々の状況に応じた体制をしっかりと整えているです。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"お話をした教員の方もおっしゃっていたので、その辺について教育委員会としてはどのように工夫されているか、伺いたいと思います。教育委員会として、学校長をはじめ教員の皆さんへの促しなど、どのようにされているのか伺いたいと思います。","respondent":"舩木庶務課長","answer":"取扱いを否定するものでなければ時間内の対応をいたしますし、そのことすらも、時間外の活用などというところを含めて対応しています。前年は９５、そして令和７年６月に実施した調査では８２というところまで下がっておりますので、個別に働きかけを行っているといった状況です。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"私がお話を伺った方も、品川区は仕組みはすごくしっかりしているというのはすごく高く評価していて、そこにやはり教員ですから異動がありますよね。","respondent":"酒川指導課長","answer":"品川区立学校のガイドラインというものではないのですけれども、区のガイドライン等を踏まえて、同様の対応をしていくというものだと認識しております。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、その点はさらに力を入れて、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３９５ページの学校ＩＣＴ活用経費についてお伺いします。改めて、この事業の目的を説明するよう求めました。","respondent":"石井学務課長","answer":"この事業につきましては、１人１台端末を各生徒に配布することによって、多様な学びを促進するものを進めているということで、目的として設定しております。","id":"exchange-078"},{"speaker":"えのした委員","kind":"質問","question":"読売新聞の８月の記事には、紙とデジタルを教育現場でどう活用すべきか。そして紙とデジタルのハイブリッドというのですか、３つの形態から選ぶとしてありますが、ご見解を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"次期学習指導要領の開始に合わせた教科書採択ということになろうかと思います。デジタル、それぞれ採択の際にこちらで検証いたしまして、品川区の児童・生徒にとって使いやすい教科書を採択できるようにしたいと考えています。","id":"exchange-079"},{"speaker":"えのした委員","kind":"提案","question":"欧州の小児科学会の連合組織は今年の６月、拾い読みですか、あと流し込みといった浅い読みになりやすいと指摘しています。ご見解をお伺いしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"ＰＩＳＡの結果につきまして、２０２２年度の調査については、日本はトップクラスであったというようなことは認識しています。デジタルがいいといった２項対立的な考え方ではなくて、我々日本、品川区の教育を進めることが大切だろうと考えております。","id":"exchange-080"},{"speaker":"えのした委員","kind":"質問・要望","question":"お隣の韓国では今年２０２５年、３月からＡＩを使ったデジタル教科書を導入していますけれども、８月に撤回したとされております。区として紙とデジタルのメリット、デメリットを十分に検討を進めていってほしいと求めましたが、最後に一言お願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"ご提案いただいたとおり進めてまいります。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"近年、バスの予約がなかなかしにくくなっているという声を聞くのですが、区教育委員会としてこの件を把握されていますでしょうか。いかがか尋ねました。","respondent":"石井学務課長","answer":"２０２４年４月から適用されたバスの働き方改革による時間外労働の上限規制などといった課題から、そういった意味では、教育旅行に関するバスの確保も同様に難しくなっているというところについては把握しています。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"というのは、やはり１年の計画、翌年の計画というのは、多分２月とか３月ぐらいに話し合って決めます。そういった今の現状に対して、支援やバス会社との連携みたいなことをお願いできたらと思うのですが、お考えなどを含めていかがでしょうとの意見を述べました。","respondent":"石井学務課長","answer":"こういったところは、民間事業者よりも地方公共団体のほうが制約が大きいのではないかと考えております。今回、その好事例をきちんと展開するなどといった方法も考えた上で、各学校の取組を促していくということも１つ考えられるかなと考えています。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"時期はずらせないということになってしまうので、こういった課題はぜひ共有していただければということで要望します。外国籍由来の方たちとの共栄といいますか、差別をなくすような取組をされているか、お伺いします。","respondent":"唐澤教育施策推進担当課長","answer":"児童・生徒の発達の段階に応じて進めておりますが、特に市民科では、各学年ごとに系統的な学習を進められるように単元を配置しております。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そこで、やはりさらなる取組をお願いしたいと要望いたします。取組を今されていると思いますけれども、さらなる取組をお願いしたいのですが、いかがでしょう。","respondent":"唐澤教育施策推進担当課長","answer":"子どもたちを取り巻く環境というのは様々絶えず変化しておりますので、こうした人権課題についても絶えず変化しているものだと捉えております。様々な人権課題が示されておりますので、こうした教育が充実していきますように、引き続き努めていければと考えています。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり、子どものときにそういった教育を受けるということで、差別やヘイトなどといった気持ちを持たないような人間に育っていくと思いますので、ぜひ充実をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"リースが５年ということで伺ったので、リース５年で保証期間があるのかなと思っているのですが、保証の状況などを教えてほしいと求めました。","respondent":"石井学務課長、酒川指導課長、丸谷教育総合支援センター長","answer":"いわゆる充電ポートという形で配備することを今検討しているところですけれども、それで学びを止めないということについては考えているところです。現在、品川地域未来塾は全校で実施しております。学校のニーズと、実際に指導してくださる人材とのマッチングというところで、そこが課題と申しますか、そういったところはあるかなと考えております。","id":"exchange-087"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは要望です。これも要望です。","respondent":"酒川指導課長、石井学務課長","answer":"区でリスト化しております、区費の講師や指導助手といったものを活用しながら、指導員の確保に努めていきたいと思います。報償費の改善のお話がございましたが、人材確保の方法と併せて総合的に検討していくものと捉えております。物価高騰対応につきましては、学校行事のみならず様々なところで影響が出ているところだと思います。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"５歳児健診が行われることを受けて、それから保育などとの連携について、どう取り組んでいくのか伺いたいと思います。小・中学校の教職員への研修というのがどうなっているのかについて伺いたいと思います。","respondent":"新井特別支援教育担当課長","answer":"特に就学という側面では、就学相談を実施する前に保護者の方向けに、就学相談というのはこういうものなのだというような事前説明会を行っております。そういった中で、発達障害等の特性や学習障害の疑似体験といった、より専門的な内容が学べるような研修を実施しています。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"提案","question":"それから、特別支援教育を推進するに当たり、区として課題として何があるのかについて伺いたいと思います。その点についても伺いたいと思いますし、品川区では、これからどういうふうに進めようとしているのかについても伺いたいと思いますとの意見を述べました。","respondent":"新井特別支援教育担当課長","answer":"やはり、いわゆる特別支援学級や支援教室に通っているお子さんだけではなくて、そのような違いというのをきちんと認識した上で。やはり教育振興基本計画を今年３月に策定したこと、中長期の観点から特別支援教育を進めていく必要がある、策定が必要ではないかと検討しています。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"今まで職場環境や人間関係や教員の質などのアンケート調査はしていたのですか。教員の声は聞いていなかったのか尋ねました。","respondent":"酒川指導課長","answer":"全校全教職員を対象にストレスチェックというのを毎年実施しておりまして、この結果、高ストレスの教員に対しては産業医による面談を実施し。特段実施しておりませんけれども、教育委員会として、その際は相談に乗ったり解決策を提案したりすることは行っております。","id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"それがまた、保護者、そして児童・生徒の皆さんにも、学校の教育方針や教員に対してのアンケート調査をやはりするべきではないですか。やはり私は、そういうことを考えて、しっかりやってほしいと思いますが、ご見解を説明するよう求めました。","respondent":"酒川指導課長","answer":"校長に対する研修といったものも、今、検討しています。これは品川区だけに限ったお話ではないと認識しておりますけれども、授業改善等を充実していくように努めてまいりたいと思います。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"こんな学校教育があるのですか。こんなことをいつまでもやっていていいのか尋ねました。","respondent":"酒川指導課長","answer":"校長へのヒアリングも行っております。学校訪問等も適宜行っておりますので、ご理解いただければと思います。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"改めてお伺いしますが、令和５年度から令和７年度が部活動地域移行推進期間ということで、原則１校で３つの部活を民間移行すると。推進校については２校ぐらいあるのですか、令和７年度も残り半年を切りまして、どれぐらい目標に対して進んでいるのかを示すよう求めました。","respondent":"酒川指導課長","answer":"令和６年度に１校当たり２部活動、それから令和６年度に少し拡充しまして、令和７年度は１校当たり３部活動を今現在、実施しております。こうした成果を踏まえ、令和８年度以降もさらに拡充していきたいと考えております。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"約６割は業務委託をしたいと考えているというところで、そういう意味では、令和８年度以降の拡大ということも必要だということは十分理解いたします。令和８年度以降、部活動の移行というのですか、お伺いしたいと思います。","respondent":"酒川指導課長","answer":"約３０％の教員が自ら指導に携わりたいという考えを持っているということを把握しておりますので、令和８年度以降、考えているところです。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"３９９ページの学校維持管理費でいいかと思うのですけれども、先ほども少しほかの委員からありました、学校での給水についてお伺いしたいと思います。水分補給を、どういった形で児童はされているのか、お伺いします。","respondent":"石井学務課長","answer":"学校での水分補給につきましては、水筒を持参して、ご自宅から当然、飲料を入れて持ってくる方もいらっしゃいますし、学校で補充する方もいるとは承知しております。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"議会棟の４階にもありますけれども、ウォーターサーバーというのですか、やはり今後は必要になってくるのではないか。児童が給水できるような環境を整えていくということについて、その必要性をどのように見るか、見解をお伺いしたいと思います。","respondent":"石井学務課長","answer":"もちろん我々は大人なので、ペットボトルではなくてマイボトルを普及するという形で、環境の効果はとても高いものであると考えております。当然、そういった意味では、給水スタンドというのは環境にとってはとてもいいものであるのではないのかなとは考えております。","id":"exchange-097"},{"speaker":"塚本委員","kind":"提案","question":"環境という面と、もっと大事なのは、やはり熱中症対策として冷水を適宜給水できるという部分もあるのです。こういったものを設置してもらいたいという要望も出てきているとも伺っておりますので、まずは最初の提案としては、いかがでしょうとの意見を述べました。","respondent":"石井学務課長","answer":"例えば新宿区ですと、報道発表資料ですと、区立学校２９校、中学校１０校、特別支援学校１校にそれぞれ導入しているというところであります。まだまだ導入については至っておりませんけれども、引き続き、他区の事例なども注視していきたいと考えております。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった意味も含めて、試験的な導入というのはぜひ検討してほしいと求めましたので、よろしくお願いしたいと思います。今、どんなものが行われているのか、あらましを教えてほしいと求めました。","respondent":"唐澤教育施策推進担当課長","answer":"主権者教育につきましては、社会科などの教科でも行っておりますが、主に市民科で扱っております。他者と連携・協働しながら社会を生き抜く力や、地域の課題解決を主体的に担う力が身につけられるように、系統的に指導しています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"意見","question":"どのような議論等があるのか、ないのか、現状を説明するよう求めました。","respondent":"唐澤教育施策推進担当課長","answer":"これまでの市民科の振り返りが主な議論になっておりまして、これから子どもたちや教員についても調査を実施していくような形で進めております。具体的なカリキュラムにつきましては、今後、検討委員会の中で、これから検討していくような形となっております。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"きちんとした反対の意見などがなかなか届きにくい。主権者教育の中でも、こういったＳＮＳ等に対するリテラシーみたいなものもぜひ検討していただきたいと思うのですが、最後に一言お願いします。","respondent":"唐澤教育施策推進担当課長","answer":"様々、子どもたちを取り巻く環境は変化しておりますので、検討に努めてまいりたいと思います。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ、学校給食にオーガニック給食を導入するとしたのでしょうか。ぜひ私は区長の思いをここで言ってほしいと求めましたが、いかがか尋ねました。","respondent":"舩木庶務課長、石井学務課長","answer":"すごく難しい、双方の合意ということがもう何よりも前提になるわけですけれども、しっかりと双方の意見を取り入れて調整に努めてまいったところです。２０５０年までに目指す日本の農業の姿として、耕地面積に占める有機農業の取扱い面積を２５％に拡大するというところで、戦略として決定しています。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"なぜ、今開発しましょうと言っている中で、子どもたちに、開発している最中の、しっかりどういうものか分からないものを、危険性を与えるのですか。見直しを図るべきだと思いますが、いかがか尋ねました。","respondent":"舩木庶務課長、石井学務課長","answer":"本来であれば、区の指定天然記念物に何か形状を変更する場合には、現状変更届という所定の手続にのっとった形で進めていくと。例えば２０５０年になって、同じような形で生産者と一緒に対話をしながら、この事業を進めていくということが必要なのではないかなと考えております。","id":"exchange-103"},{"speaker":"西本委員","kind":"確認","question":"ケンポナシの件は所有者に確認を取っていませんから、確認をきちんと取るような形でしっかりとやってください。それから、オーガニック給食は、今の説明では納得がいきません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３９９ページのプール整備についてお伺いします。その理由を説明するよう求めました。","respondent":"荒木学校施設担当課長","answer":"一方の不用額につきましては、予算編成時は過去の実績や簡易的な設計を通して予算を要望してまいります。詳細な設計を進めたところ、より経済的な工事ができるであろうということで、予算を少し縮減して発注したです。","id":"exchange-105"},{"speaker":"澤田委員","kind":"質問","question":"共同利用または民間活用では財政的メリットがどの程度あるのか、試算はしているのでしょうか。現在の課題についても説明するよう求めました。","respondent":"荒木学校施設担当課長","answer":"その結果、各学校で平均して９割を超える授業実施率を達成しています。通常の学校であれば自校のプールを２こま使って実施しているところ、この２こま分に、慎重に検討を進めていきたいと考えています。","id":"exchange-106"},{"speaker":"澤田委員","kind":"質問・要望","question":"誰もが分かりやすい形で公開していただいて、十分に意見交換をする場所というのを設けていただきたいと考えていますので、よろしくお願いいたします。様々それらに伴う予算をつけるなど、しっかりと行っていただきたいと思うのですが、区としてのお考えを説明するよう求めました。","respondent":"荒木学校施設担当課長","answer":"教職員の負担も非常に大きなところを懸念していますので、今後は教育委員会としても、事業面に関してもしっかりと支援していきたいと考えています。","id":"exchange-107"},{"speaker":"澤田委員","kind":"質問・要望","question":"いろいろ話し合っていただきたいのですが、下手したら１年生からずっと工事中という子もいる中で、そして新しい校舎を少しでも利用できるように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問","question":"私は、３９４ページの学校管理費関連と、ページ数はもう全部なので、学校教育に関してお伺いしたいと思います。もう少し具体的にお伺いしたいのですが、被害の状況はどうなっているのか、また現状についてお伺いしたいと思います。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"私から、学校施設、第二延山小学校の被害状況についてご説明いたします。１階部分が体育館を中心に１０センチ弱程度浸水してしまったという状況がございまして、連休中に復旧に向けた対応を様々検討していたという状況です。３連休明けに学校を復帰したということで、今、学校運営を進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"体育館に水が入ったということでありますが、今現在は体育館での体育の授業などが行えるのかも含めてお伺いしたかったのですが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"体育館の浸水はございましたが、現在は乾いておりまして、体育の授業を通常どおり、学校での活動は実施しています。ただ一方で、今後はその部分の張り替えなども検討していこうということで、進めていこうと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"確認","question":"第二延山小学校は平成１８年に完成なので、ハザードマップを見ると、ハザードマップでも当初から水害が出る地域だと示されていました。平成１８年といいましたか、いわゆるハザードマップ周辺の学校建設の在り方について、改めて確認したいと思います。","respondent":"荒木学校施設担当課長","answer":"平成１８年の竣工当時に関しましても、工事を実施し、増やしたりといった対応はしておりました。軽く、保管も容易にできるような止水板を至急設置して、まずは止水対策をしっかりと進めていこうと考えています。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて学校関連の質問なのですけれども、ご案内のとおり、品川区の場合は年間約１５０人前後が区外から転入出されているということも伺っています。品川区において、他区から来た先生に対してどのような研修をされているのか、お伺いしたいと思います。","respondent":"酒川指導課長","answer":"入区の４月の段階で、新任・転任の教員に対する、また管理職に対する研修を実施しています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"もう少し具体的にお伺いしたいのですけれども、教育改革「プラン２１」をはじめ、品川区に来て初めて経験する。教員としての指導に当たっていただかなくてはいけないのですけれども、特に市民科に対する指導をどのように行っているのかお伺いしたいと思います。","respondent":"唐澤教育施策推進担当課長","answer":"そうした中で、校内研修でも実施できる体制を整えているところです。各学校には推進教師がいますので、その推進教師が代表として研修に参加し、各校への還元研修も行っているところです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問","question":"若干うがった目で見ると、教育総合支援センターには指導主事が６人いて、指導課は３人しかいないです。なぜ指導課ではなく教育総合支援センターでやっているかという、その辺の実態といいますか、受け止めはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"市民科の教員への負担感ですけれども、市民科は品川区独自の教科でございまして、２０年を迎えるものになりました。負担感のないように、そうした声も拾いながら、今後も品川区の教育の充実を図ってまいりたいと考えています。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて高校の授業料無償化に関連してお伺いしたいのですが、される中で、私は今年３月の第二延山小学校の卒業式に出ました。今回の高校授業料の無償化による学校教育への影響といいますか、在り方、どういう姿勢で臨もうとされるのかお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"幅広い進路選択ができる、生徒にとってみれば可能性が広がるという意味では、高校の授業料の無償化の意義がそこにあるのかなと考えています。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"小学校に給食施設があるわけですから、それを活用できるわけです。この２園のみ、５歳児に給食提供が行われていないということを、教育委員会事務局として把握していたのか伺います。","respondent":"石田（秀）委員長、酒川指導課長","answer":"学校が一緒だから小学校は分かっていないということなのではないか。分かっていないなら分かっていないと、誰か答えてください。そういった状況があることは、把握はしております。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"次に質問を入れようと思ったのですが、区立幼稚園運営の補助執行先である子ども未来部からの情報提供があったのかと伺おうと思ったのですが。教育委員会が主導して、そして小学校の給食室もあるわけですから、方針を考えるべきだと私は思っています。","respondent":"酒川指導課長","answer":"頂きましたご意見を踏まえて検討してまいりたいと思います。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうだとすれば、なぜ改修が予算計上されないのでしょうか。お尋ねします。","respondent":"荒木学校施設担当課長","answer":"体育館の外壁改修にも別途取り組んでおりますので、そういうところと学校運営の兼ね合いもあって、実施を見送ったところです。検討を進めて、皆様に安心してご利用いただけるよう、整備に努めてまいります。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ令和８年度の予算で強く予算要求して、実現することを要望いたします。頑張った選手たちに、ぜひ励ましの言葉とともに閉会式でご挨拶いただきたかったのですが、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"教育次長や私などが対応するのですけれども、公務等々の事情で出席できなかったということで認識しておりますので、しっかりと対応できるようにしてまいりたいと思います。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"２３区で区の時間講師を導入しているところは、ほとんど月に５万５,０００円までの交通費が出ています。交通費を品川区が支給していない理由と、そして今後、交通費を品川区の区費の時間講師に対して支給する考えはいかがか尋ねました。","respondent":"酒川指導課長","answer":"品川区で働こうと思われる方が減ってしまう可能性というのはあるかと考えておりますので、他区の状況も含めて、品川区でどのような支給ができるかということは考えていく余地があるかなと考えているところです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、十年、十五年の方も、１年の方も同じなのです。まさに令和８年度の予算に入れて要求してほしいと求めましたが、いかがか尋ねました。","respondent":"酒川指導課長","answer":"現在、先ほども申し上げましたように、他区の状況を踏まえて品川区でできることを考えているところです。なるべく前向きに検討していきたいと考えております。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都はありませんので財政調整で入っています。しかし３校が０紙ということですが、この学校へどのような指導を教育委員会としてするか尋ねました。","respondent":"石井学務課長","answer":"当初、国の方針が示された際については、各学校に対して新聞購入についてお願いしておりました。本日の議論等も踏まえまして、特に０紙の学校に関しては、個別のヒアリング等も含めて働きかけていきたいと考えております。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"私からは、３８３ページ、いじめ防止対策費、同じページの教職員研修、３９４ページ、学校管理費について伺います。先に、教職員研修、学校管理費についてで、これは、関連して学校内の盗撮の対策について伺います。","respondent":"酒川指導課長","answer":"７月の文部科学省通知を踏まえた対応です。行っている実態はないかというチェックリストを、これは教員のみならず、あらゆる教職員に対して実施しております。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問・要望","question":"いかに機会的に環境として、密室を予防していくというか、密室をなくしていくのかというところが大切かと思います。こうした犯罪を防ぐために、校内の防犯カメラについて要望しておりましたが、こちらについて検討状況を伺います。","respondent":"酒川指導課長","answer":"理由としましては、導入の検討に当たって、防犯カメラ設置によりまして、教員の指導や児童・生徒の活動の萎縮が生じることが予想されること。そうした課題の洗い出しや対応の整理が必要と考えているところです。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問・要望","question":"実際に被害が生じてしまったら、外部に流出してしまったら、もう児童・生徒の被害は回復・保護できないということはご理解ほしいと求めました。","respondent":"酒川指導課長","answer":"誰がどれほどの規模で実施するのかなどの課題もあります。は先行して実施したり、実施を検討している自治体等の情報の収集に努めていきたいと考えております。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"できない盗撮カメラもあるとも伺っていますので、難しい点かと思いますが、ぜひご検討をお願いいたします。それを中に入れているかどうかというのは客観的に分かるので、厳禁というだけではなくて、ご見解を伺います。","respondent":"酒川指導課長","answer":"決められた保管ボックス等々に入れて鍵をするような状況を想像するわけですが、これについては、今そういったことは行っておりません。教員の人権やプライバシーへの配慮も必要であると考えますし、ここについては慎重に考えなくてはいけないところではないかと考えております。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"テレフォンアポイントメントですか、そういう場合というのは、プライベートであっても保管ボックスにきちんと入れておきましょうと。児童・生徒が撮ったというのを通報するようなアプリもあるやに聞いていますが、この児童・生徒の盗撮について、最後にご見解をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"そのようなアプリを導入している自治体があるということは把握しています。子どもたちが安心・安全に学校生活を送れるような環境づくりが大切だと考えますので、国の方針等も含めて検討してまいります。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"令和６年度の不登校児童・生徒数は何人でしょうか。利用人数を伺いたいのと、利用実態を伺います。","respondent":"丸谷教育総合支援センター長","answer":"昨年度から始まりました校内教育支援センターの利用者数ですけれども、生徒は９１人で、合計２７４人の児童・生徒が利用したことになります。一時的に休憩したり、継続して使用するなど、児童・生徒一人一人に合った環境が提供できていると認識しています。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問・要望","question":"不登校について、校内別室指導支援員に研修を行うべきだと思いますが、いかがでしょうか。その中で、学習が優先されていないかと思ってしまうのですが、休息と回復を保障する場となるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"昨年度分はこの１０月中には出るかと思いますけれども、品川区の対策が効果的なものかどうかを測っていく必要があるかと考えます。校内別室指導支援員が相談に乗ったり話をしたり、この意義というところは全ての学校に、また改めて周知していきたいと考えます。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"相談の窓口など、校内別室指導支援員が紹介できるように周知すべきではないかと思いますが、いかがでしょうか。そして、校内別室指導支援員の専門性の発揮や待遇改善のために、現在１,６００円の時給を引き上げるべきだと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そういったことも大切な視点だと考えますので、校内別室指導支援員に向けての情報提供を行っていきたいと考えております。待遇についてですけれども、国や都の最低賃金等も鑑みながら、報償費は決めていければと考えております。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ家庭の光熱水費や給食代、タブレット教材費などへの支援を求めたいと思いますが、いかがでしょうか。フリースクールへの支援、家賃補助などの実施を求めたいと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"現在、教育総合支援センターでは、フリースクールへ通う家庭に対しての助成金という形での補助がありますけれども、こういった支援につきましては進めていきたいと思います。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３８５ページ、品川学校支援チーム経費、３９９ページ、学校運営費、順不同でお聞きいたします。年々厳しさを増す危険な暑さから児童・生徒の命を守る熱中症対策としての現状と、今後の取組といったことについての方針を、まず説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"現状では、例えば日傘を差す、あと水筒の中身について、登下校中、途中でも立ち止まって飲んでもいいといったことでの対応は進んでいるかと考えます。","id":"exchange-132"},{"speaker":"こんの委員","kind":"確認","question":"今後の考え方も確認させていただきました。生地の素材を見直したり、通気性のよいメッシュにするなど、改善できないのでしょうか」というお声です。","respondent":"丸谷教育総合支援センター長","answer":"通学帽につきまして、小学校では各校が定めているものではあります。頭が蒸れてしまうといったことにつきましては、学校とも上手に協議していただいて、改善を求める声を上げていただければと考えております。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問・要望","question":"私の先輩議員が一般質問で初めて取り上げて、２０１３年、ＨＥＡＲＴＳに導入されました。そこで、現在の体制などをお聞きしたいのですが、現在配置されている人員体制と運用、活用内容も併せてお知らせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"不登校の低年齢化に合わせてということですけれども、特に対象年齢は定めておりませんので、小学校１年生から支援に当たっているところです。","id":"exchange-134"},{"speaker":"こんの委員","kind":"質問・要望","question":"どう対処したらよいか分からない、この先をどうしていったらよいのか分からない保護者や家庭においては、有効な支援だと考えております。体制を取ってくださるということですが、今後はこうしたことの強化を求めていきたいと思いますが、ご見解を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"ＨＥＡＲＴＳの設置に伴って、１０年ほど進んでいく中で、人員についても徐々に増やしているという現状があります。そういった不登校児童・生徒の人数の増加や、学校や家庭のニーズに合わせて、人員も強化できればと考えます。","id":"exchange-135"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした福祉という観点が非常に大事だと考えていますので、そのためにも、どうかスクールソーシャルワーカーの体制を強化していただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"藤原委員","kind":"質問","question":"３９１ページ、図書館運営費で、９月１１日に大雨が降りましたが、図書館において被害はあったのか尋ねました。","respondent":"三ツ橋品川図書館長","answer":"９月１２日から１８日まで臨時休館しておりまして、閲覧室に立ち入ることができなくて、１９日から廊下に臨時カウンターを設置しております。","id":"exchange-137"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、やはり図書というのは品川区民の財産でもあり、大切なものですよね。いつ災害が起こるか分からないわけですから、９月１１日の件をきっかけに、この辺についてはいかがか尋ねました。","respondent":"三ツ橋品川図書館長","answer":"止水板の設置なども、大崎図書館分館だけでなく全体の図書館において、しっかりと検討して対策を練っていきたいと考えています。なお、９月１１日でしたけれども、そちらに関しましては、この日は休館日でしたので、区民の方、ご利用者は被害に遭われなかったという状況です。","id":"exchange-138"},{"speaker":"藤原委員","kind":"質問・要望","question":"３７７ページの文化財保護費なのですけれども、当然歴史のある古いものが多いと思うのですけれども、これも９月１１日に大雨が降りました。年間どのぐらいの金額で、年間何件ぐらいの実績があるか、まず伺います。","respondent":"舩木庶務課長","answer":"しっかりと対応すべきものには対応していくということを前提とするものですが、今年度は１件、実績があります。主に、倒壊してしまいそうな屋根の修繕など、安全に影響があるものをしっかりと修繕・手当てしていくということで、予算対応をしています。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問","question":"０件だというお話なのですけれども、１００件以上ある指定文化財の中で、全部本当に分かっているのでしょうか。きちんと言っていくというのも、所管としてやっていかないといけないと思うのですが、その辺についてはいかがか尋ねました。","respondent":"舩木庶務課長","answer":"所有者の方が第一義的には管理責任を負っていただいて、保護も含めてということなのですけれども、この辺りの周知の方法については少し考えてまいりたいと思います。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり指定しているわけですから、一義的には第１段階で所有者というのも分かるのですけれども、区が指定して、お手伝いをしていく。ここはしっかり予算要求をしていただいて、やっていってほしいと求めましたけれども、改めて答弁をお願いします。","respondent":"舩木庶務課長","answer":"これまでの過去の実績を踏まえての予算編成、予算の考え方になっておりますので、真に必要な対応は、しっかりと財政当局とも協議した上で対応していくという、基本的な考え方にはなろうかと思いますので、そこはそういうことを踏まえて、引き続き支援してまいりたいと考えます。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問","question":"「日本はどういうところがよかったですか」などというと、食べ物や観光地を海外の方が言うのですけれども、１人の方がこう言ったのです。教育の現場では改正された部分について、どういう形でこの文章を、具体的に学校教育としてされているのか尋ねました。","respondent":"酒川指導課長","answer":"スポットを当てて指導するとすれば、社会科の学習が、特に強調して指導できる点ではないかと考えています。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、日本に生まれ育って、日本人としての誇りを持って生きていけるような子どもたちを、ぜひつくっていってほしいと求めました。今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"まつざわ委員","kind":"質問","question":"この約６,７００万円という投資に対しまして、社会参画への意欲を育むという目的を十分に達成できているというご認識でしょうか。は評価をお伺いいたします。","respondent":"唐澤教育施策推進担当課長","answer":"主権者教育につきましては、市民科の中で系統的な指導を各学年の発達段階に応じて実施しています。引き続き、子どもの実態や社会の動向等を注視して、充実に努めていければと考えております。","id":"exchange-144"},{"speaker":"まつざわ委員","kind":"質問","question":"そこでお聞きします。今度、地域の課題解決に挑戦するプロジェクト学習といった、より実践的な主権者教育をカリキュラムに導入するお考えはありますか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"カリキュラムの具体的な内容については、今後、市民科検討委員会の中でも協議していければと考えています。地域の方と連携・協働しながら、こうした取組については各校で普及して、また広く周知していければと考えています。","id":"exchange-145"},{"speaker":"まつざわ委員","kind":"提案","question":"ご提案なのですけれども、そういった市民科の中の机上の議論といいますか、教科書のものだけではなかなか分からないのも事実だと思っています。全学校に、これからの市民科の中に、もう体系的に導入していくという考え方というのはいかがか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"体験的・実践的な学習を取り入れることは非常に有効なことだと考えていますので、改めてカリキュラムについては検討していきたいと考えています。","id":"exchange-146"},{"speaker":"まつざわ委員","kind":"質問","question":"政治的中立性の正しい理解というもの、また具体的な授業実践の方法を学ぶための研修というのを十分実施しているとお考えでしょうか。現状の研修体制について説明するよう求めました。","respondent":"唐澤教育施策推進担当課長","answer":"良識ある公民として必要な政治的教養は、教育上、尊重されなければならないということが示されておりますので、先ほど申し上げた事例などを校長連絡会や各研修の場で共有する際には、そうしたことも含めて教職員に伝えていければと考えています。","id":"exchange-147"},{"speaker":"まつざわ委員","kind":"質問","question":"教育を担う先生がしっかりと、自信と情熱を持って授業に臨める環境というのが、まずとても大事だと思っています。教員が要はどこまで教えていくのか、専門的な研修プログラムというものも根本的に強化していくことが大切と思いますが、ご見解を説明するよう求めました。","respondent":"唐澤教育施策推進担当課長","answer":"例えば弁護士や政治家など、まずは引き続き、そうした専門的講師による市民科授業の充実には努めていきたいと考えております。併せて、最後になるのですけれども、カリキュラムの具体的な内容については、市民科検討委員会の中でも十分な議論の中、検討していければと思います。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/239858?Template=document&Id=7261#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":112665,"voices":348}}]);
